INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-1_q1', 'ap-diag-1', 1, false, 'C', 'Limits', 'easy', 'Evaluate $\lim_{x \to 3} \frac{x^2 - 9}{x - 3}$.', '["0","3","6","Undefined"]'::jsonb, 'Factor numerator: $x^2 - 9 = (x - 3)(x + 3)$. Cancel $(x - 3)$ to get $\lim_{x \to 3} (x + 3) = 6$.'),
  ('ap-diag-1_q2', 'ap-diag-1', 2, false, 'C', 'Limits', 'easy', 'What is $\lim_{x \to 0} \frac{\sin(4x)}{x}$?', '["0","1","4","Does not exist"]'::jsonb, 'Using $\lim_{u \to 0} \frac{\sin(k u)}{u} = k$, we get 4.'),
  ('ap-diag-1_q3', 'ap-diag-1', 3, false, 'B', 'Limits', 'medium', 'Find $\lim_{x \to \infty} \frac{5x^3 - 2x + 1}{2x^3 + 7x^2}$.', '["0","2.5","5","$\\infty$"]'::jsonb, 'Leading coefficients ratio: 5/2 = 2.5.'),
  ('ap-diag-1_q4', 'ap-diag-1', 4, false, 'A', 'Derivatives', 'easy', 'If $f(x) = 4x^3 - 5x^2 + 7x - 2$, what is $f''(x)$?', '["$12x^2 - 10x + 7$","$12x^2 - 5x + 7$","$4x^2 -10x$","$12x^3 - 10x^2$"]'::jsonb, 'Apply power rule term by term: $12x^2 - 10x + 7$.'),
  ('ap-diag-1_q5', 'ap-diag-1', 5, false, 'A', 'Derivatives', 'medium', 'Find the slope of the tangent line to $x^2 + y^2 = 25$ at $(3, 4)$.', '["$\\frac{-3}{4}$","$\\frac{3}{4}$","$\\frac{-4}{3}$","$\\frac{4}{3}$"]'::jsonb, '$2x + 2y y'' = 0 \implies y'' = $-x$/y = -3/4$.'),
  ('ap-diag-1_q6', 'ap-diag-1', 6, false, 'A', 'Integrals', 'easy', 'Evaluate $\int (3x^2 - 4x + 5) dx$.', '["$x^3 - 2x^2 + 5x + C$","$6x - 4 + C$","$x^3 - 4x^2 + 5x + C$","$3x^3 - 2x^2 + C$"]'::jsonb, 'Power rule for integration gives $x^3 - 2x^2 + 5x + C$.'),
  ('ap-diag-1_q7', 'ap-diag-1', 7, false, 'B', 'Integrals', 'medium', 'Find $\int_{0}^{\pi/2} \sin(x) \cos(x)\,dx$.', '["0","0.5","1","2"]'::jsonb, 'Substitution $u = \sin(x)$ gives $[u^2/2]_0^1 = 0.5$.'),
  ('ap-diag-1_q8', 'ap-diag-1', 8, false, 'A', 'Applications', 'medium', 'Find the average value of $f(x) = x^2$ on $[0, 3]$.', '["3","4.5","9","27"]'::jsonb, '$\frac{1}{3}$\int_{0}^{3} x^2 dx = $frac{1}{3} [x^3/3]_0^3 = 3$.'),
  ('ap-diag-1_q9', 'ap-diag-1', 9, false, 'B', 'Derivatives', 'medium', 'Find $\frac{d}{dx}[\sin(x^2)]$.', '["$\\cos(x^2)$","$2x\\cos(x^2)$","$-\\sin(x^2)$","\\$2\\cos(x^2)$"]'::jsonb, 'Chain rule: $\cos(x^2) \cdot 2x = 2x\cos(x^2)$.'),
  ('ap-diag-1_q10', 'ap-diag-1', 10, false, 'B', 'Derivatives', 'medium', 'Use the product rule to differentiate $f(x) = x^2 e^x$.', '["$2xe^x$","$x^2 e^x + 2xe^x$","$2xe^x - x^2 e^x$","$x^2 e^x$"]'::jsonb, '$f''(x) = x^2 e^x + 2x e^x$ by product rule.'),
  ('ap-diag-1_q11', 'ap-diag-1', 11, false, 'B', 'Limits', 'medium', 'Evaluate $\lim_{x \to 0} \frac{1 - \cos x}{x^2}$.', '["0","$\\frac{1}{2}$","1","Does not exist"]'::jsonb, 'Using L''Hopital or Taylor series: limit equals 1/2.'),
  ('ap-diag-1_q12', 'ap-diag-1', 12, false, 'B', 'Derivatives', 'easy', 'What is the derivative of $\ln(x)$?', '["$x$","\\$1/x$","$e^x$","$\\ln(x)/x$"]'::jsonb, '$\frac{d}{dx}[\ln x] = \frac{1}{x}$.'),
  ('ap-diag-1_q13', 'ap-diag-1', 13, false, 'C', 'Integrals', 'medium', 'Evaluate $\int e^{3x} dx$.', '["$e^{3x} + C$","$3e^{3x} + C$","$\\frac{1}{3}e^{3x} + C$","$\\frac{e^{3x}}{x} + C$"]'::jsonb, '$\int e^{3x} dx = \frac{1}{3}e^{3x}  + C$.'),
  ('ap-diag-1_q14', 'ap-diag-1', 14, false, 'B', 'Applications', 'medium', 'If $f''(x) > 0$ on $(a, b)$, then $f$ is:', '["Decreasing on $(a,b)$","Increasing on $(a,b)$","Concave up","Has a local max"]'::jsonb, 'Positive first derivative means the function is increasing on that interval.'),
  ('ap-diag-1_q15', 'ap-diag-1', 15, false, 'B', 'Applications', 'medium', 'Find the critical points of $f(x) = x^3 -3x$.', '["$x = 0$","$x = \\pm 1$","$x = \\pm 3$","$x = 1$ only"]'::jsonb, '$f''(x) = 3x^2 - 3 = 0 \implies x = \pm 1$.'),
  ('ap-diag-1_q16', 'ap-diag-1', 16, false, 'B', 'Integrals', 'hard', 'Evaluate $\int_1^e \frac{\ln(x)}{x}\,dx$.', '["0","$\\frac{1}{2}$","1","e"]'::jsonb, 'Let $u = \ln x$, $du = dx/x$. Integral becomes  \int_{0}^{1} u$\, du = 1/2$.'),
  ('ap-diag-1_q17', 'ap-diag-1', 17, false, 'A', 'Derivatives', 'hard', 'Find $\frac{d}{dx}[\tan^{-1}(x)]$.', '["$\\frac{1}{1+x^2}$","$\\frac{1}{\\sqrt{1-x^2}}$","$-\\frac{1}{1+x^2}$","$\\sec^2(x)$"]'::jsonb, 'Standard derivative: $\frac{d}{dx}[\arctan x] = \frac{1}{1+x^2}$.'),
  ('ap-diag-1_q18', 'ap-diag-1', 18, false, 'A', 'Applications', 'medium', 'The second derivative test: if $f''(c)=0$ and $f''''(c) > 0$, then $f$ has a:', '["Local minimum at $x=c$","Local maximum at $x=c$","Inflection point","No conclusion"]'::jsonb, 'Positive second derivative at a critical point indicates a local minimum.'),
  ('ap-diag-1_q19', 'ap-diag-1', 19, false, 'A', 'Integrals', 'medium', 'Use substitution: $\int 2x(x^2+1)^4 dx$.', '["$\\frac{(x^2+1)^5}{5}  + C$","$\\frac{(x^2+1)^5}{10}  + C$","$8x(x^2+1)^3 + C$","$(x^2+1)^5  + C$"]'::jsonb, 'Let $u = x^2+\$1$, $du = 2x\\,$dx$. Integral = $u^5/5 + C$.'),
  ('ap-diag-1_q20', 'ap-diag-1', 20, false, 'B', 'Limits', 'hard', 'Apply L''Hopital''s Rule: $\lim_{x \to 0} \frac{e^x - 1}{x}$.', '["0","1","e","Does not exist"]'::jsonb, 'Both numerator and denominator are 0/0. Differentiate: $e^x/1 = 1$ at $x=0$.'),
  ('ap-diag-1_q21', 'ap-diag-1', 21, false, 'A', 'Applications', 'medium', 'The area between $y = x^2$ and $y = x$ from $x=0$ to $x=1$ is:', '["$\\frac{1}{6}$","$\\frac{1}{3}$","$\\frac{1}{2}$","1"]'::jsonb, '$\int_0^1 (x - x^2) dx = 1/2 - 1/3 = 1/6$.'),
  ('ap-diag-1_q22', 'ap-diag-1', 22, false, 'B', 'Derivatives', 'medium', 'What is $\frac{d}{dx}[x^x]$?', '["$x \\cdot x^{x-1}$","$x^x(1 + \\ln x)$","$x^x \\ln x$","$x^{x-1}$"]'::jsonb, 'Take $\ln y = x \ln x$. Then $y''/y = \ln x + 1$, so $y'' = x^x(1+\ln x)$.'),
  ('ap-diag-1_q23', 'ap-diag-1', 23, false, 'B', 'Integrals', 'medium', 'Evaluate $\int \cos^2(x) dx$.', '["$\\frac{\\sin(2x)}{4}  + C$","$\\frac{x}{2} + \\frac{\\sin(2x)}{4}  + C$","$-\\sin^2(x)  + C$","$\\cos(x)\\sin(x)  + C$"]'::jsonb, 'Use $\cos^2 x = (1+\cos 2x)/2$: integral = $x/2 + \sin(2x)/4 + C$.'),
  ('ap-diag-1_q24', 'ap-diag-1', 24, false, 'B', 'Applications', 'hard', 'Volume from rotating $y=\sqrt{x}$ around x-axis, $x=0$ to $x=4$:', '["\\$4\\pi$","\\$8\\pi$","\\$16\\pi$","\\$32\\pi$"]'::jsonb, '$V = \pi$\int_{0}^{4} x$\,dx = \pi[x^2/2]_0^4 = 8\pi$.'),
  ('ap-diag-1_q25', 'ap-diag-1', 25, false, 'B', 'Derivatives', 'easy', 'Find $\frac{d}{dx}[\cos(3x)]$.', '["$-\\sin(3x)$","$-3\\sin(3x)$","\\$3\\cos(3x)$","$\\sin(3x)$"]'::jsonb, 'Chain rule: $-\sin(3x) \cdot 3 = -3\sin(3x)$.'),
  ('ap-diag-1_q26', 'ap-diag-1', 26, false, 'C', 'Limits', 'easy', '$\lim_{x \to 2} (3x^2 - 4) = $?', '["2","4","8","12"]'::jsonb, 'Direct substitution: \$3(4) - 4 = 8$.'),
  ('ap-diag-1_q27', 'ap-diag-1', 27, false, 'B', 'Integrals', 'easy', 'Evaluate $\int_{0}^{2} 3\,dx$.', '["3","6","9","0"]'::jsonb, '$$\int_{0}^{2} 3$\,dx = 3x\\Big|_0^2 = 6$.'),
  ('ap-diag-1_q28', 'ap-diag-1', 28, false, 'C', 'Applications', 'hard', 'A particle moves with velocity $v(t) = t^2 - 4$. Total distance on $[0,3]$ is:', '["3","$\\frac{11}{3}$","$\\frac{17}{3}$","9"]'::jsonb, '$v=0$ at $t=2$. Distance =  \int_{0^2(4-t}^{2)dt} $+\int_2^3(t^2-4)dt = 16/3 + 1/3 = 17/3$.'),
  ('ap-diag-1_q29', 'ap-diag-1', 29, false, 'A', 'Derivatives', 'medium', 'Using quotient rule, $\frac{d}{dx}\left[\frac{x^2}{\cos x}\right]$ =', '["$\\frac{2x\\cos x + x^2\\sin x}{\\cos^2 x}$","$\\frac{2x}{-\\sin x}$","$2x\\cos x$","$\\frac{2x\\cos x - x^2\\sin x}{\\cos^2 x}$"]'::jsonb, 'Quotient rule: numerator = $2x\cos x - x^2(-\sin x) = 2x\cos x + x^2\sin x$.'),
  ('ap-diag-1_q30', 'ap-diag-1', 30, false, 'B', 'Applications', 'hard', 'Linearization of $f(x)=\sqrt{x}$ at $x=9$ approximates $\sqrt{9.1}$ as:', '["3.0150","3.0167","3.0200","3.0100"]'::jsonb, '$L(x) = 3 + \frac{1}{6}(x-9)$. $L(9.1) = 3 + 0.1/6 \approx 3.0167$.'),
  ('ap-topic-englang-rhet_q1', 'ap-topic-englang-rhet', 1, false, 'C', 'Rhetoric', 'easy', 'Which rhetorical appeal relies on establishing speaker credibility and moral authority?', '["Logos","Pathos","Ethos","Kairos"]'::jsonb, 'Ethos appeals to character, credibility, and authority.'),
  ('ap-topic-englang-rhet_q2', 'ap-topic-englang-rhet', 2, false, 'A', 'Rhetorical Analysis', 'medium', 'What is an appeal to *logos* in rhetorical argumentation?', '["An appeal to logic, empirical data, structured reasoning, and factual evidence","An appeal to the audience''s intense emotional sympathy","An appeal based on the speaker''s moral authority and credibility","An attack on the opponent''s personal character"]'::jsonb, 'Logos utilizes deductive syllogisms, statistics, verified facts, and sound rational argumentation.'),
  ('ap-topic-englang-rhet_q3', 'ap-topic-englang-rhet', 3, false, 'A', 'Rhetorical Analysis', 'medium', 'What is an appeal to *ethos*?', '["Establishing the credibility, moral character, expertise, and trustworthiness of the speaker/author","Evoking sorrow or fear in the audience","Using mathematical proofs","Repeating words for musical cadence"]'::jsonb, 'Ethos convinces the audience that the author is qualified, fair-minded, and ethical.'),
  ('ap-topic-englang-rhet_q4', 'ap-topic-englang-rhet', 4, false, 'A', 'Rhetorical Analysis', 'medium', 'What is *parallelism* (parallel syntax) in rhetoric?', '["The repetition of similar grammatical structures within words, phrases, or clauses for balance and rhetorical emphasis","The comparison of two unlike things using ''like'' or ''as''","Contradictory terms placed side-by-side","The emotional climax of an essay"]'::jsonb, 'Parallel syntax creates rhythm, clarity, and persuasive balance (e.g. ''I came, I saw, I conquered'').'),
  ('ap-topic-englang-rhet_q5', 'ap-topic-englang-rhet', 5, false, 'A', 'Rhetorical Analysis', 'medium', 'What is *antithesis*?', '["The juxtaposition of contrasting ideas in balanced, parallel grammatical phrasing","An understatement designed to minimize significance","An exaggerated claim not meant to be taken literally","A question asked solely for dramatic effect"]'::jsonb, 'Antithesis places opposites in direct parallel contrast (e.g. ''One small step for man, one giant leap for mankind'').'),
  ('ap-topic-englang-rhet_q6', 'ap-topic-englang-rhet', 6, false, 'A', 'Rhetorical Analysis', 'medium', 'What is an *ad hominem* logical fallacy?', '["Attacking the personal character or motives of the opponent rather than addressing the substance of their argument","Assuming that correlation implies causation","Misrepresenting the opponent''s argument to make it easier to attack","Arguing that an idea is true simply because it is popular"]'::jsonb, 'Ad hominem fallacies distract from the core thesis by launching irrelevant personal insults.'),
  ('ap-topic-englang-rhet_q7', 'ap-topic-englang-rhet', 7, false, 'A', 'Rhetorical Analysis', 'medium', 'What is the *straw man* fallacy?', '["Oversimplifying or distorting an opponent''s argument into an extreme, vulnerable version and then attacking that fabricated position","Assuming a chain reaction of catastrophic consequences","Using circular reasoning","Appealing to false authority"]'::jsonb, 'A straw man fallacy refutes an exaggerated caricature of the opponent''s true claim.'),
  ('ap-topic-englang-rhet_q8', 'ap-topic-englang-rhet', 8, false, 'A', 'Rhetorical Analysis', 'medium', 'What is *chiasmus*?', '["A rhetorical device in which grammatical structures or concepts are repeated in reverse order ($A-B-B-A$)","A sudden pause in speech","A rhyme at the end of every line","A long narrative metaphor"]'::jsonb, 'Chiasmus reverses phrasing in an criss-cross pattern (e.g. ''Ask not what your country can do for you—ask what you can do for your country'').'),
  ('ap-topic-englang-rhet_q9', 'ap-topic-englang-rhet', 9, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'In classical rhetoric, how is the "exigence" of a text defined within the rhetorical situation?', '["The urgent occasion, catalyst, or real-world problem that prompts the author to write or speak","The concluding emotional appeal delivered in the peroration","The grammatical complexity of the author''s compound-complex sentences","The historical accuracy of empirical citations used in the text"]'::jsonb, 'Exigence (part of Bitzer''s rhetorical situation) is the specific issue, deficiency, or urgent crisis that provokes or inspires the writer to create the discourse.'),
  ('ap-topic-englang-rhet_q10', 'ap-topic-englang-rhet', 10, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'Which rhetorical device is utilized in Neil Armstrong''s famous statement: "That''s one small step for man, one giant leap for mankind"?', '["Antithesis","Chiasmus","Polysyndeton","Litotes"]'::jsonb, 'Antithesis juxtaposes two contrasting ideas in balanced parallel grammatical structures ("small step" vs "giant leap").'),
  ('ap-topic-englang-rhet_q11', 'ap-topic-englang-rhet', 11, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'hard', 'What constitutes an "ad hominem" logical fallacy in persuasive argumentation?', '["Attacking the personal character, motives, or background of the opponent rather than addressing the substance of their argument","Misrepresenting an opponent''s position to make it easier to attack","Assuming that because event B followed event A, event A caused event B","Arguing that an action must be taken because everyone else is doing it"]'::jsonb, 'An ad hominem fallacy attacks the person making the claim (character, identity, motives) rather than addressing the factual evidence or logical validity of the claim itself.'),
  ('ap-topic-englang-rhet_q12', 'ap-topic-englang-rhet', 12, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'How does a periodic sentence create rhetorical emphasis compared to a loose (cumulative) sentence?', '["It withholds the main independent clause and central meaning until the very end of the sentence, building suspense and climax","It places the main subject and verb at the very beginning and adds accumulating descriptive modifiers at the end","It repeats the same initial phrase across successive independent clauses","It contains no subordinate or dependent clauses"]'::jsonb, 'A periodic sentence reserves the main clause until the period at the end, creating dramatic anticipation. A cumulative (loose) sentence begins with the main idea and adds clarifying phrases afterward.'),
  ('ap-topic-englang-rhet_q13', 'ap-topic-englang-rhet', 13, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'Which rhetorical appeal relies on establishing the speaker''s moral character, credibility, expertise, and shared values with the audience?', '["Ethos","Pathos","Logos","Kairos"]'::jsonb, 'Ethos establishes authority and trust through demonstrated competence, fair-mindedness, moral integrity, and shared community values.'),
  ('ap-topic-englang-rhet_q14', 'ap-topic-englang-rhet', 14, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'hard', 'What is the function of a concession and rebuttal in a persuasive argumentative essay?', '["Acknowledging the validity of a counterargument (concession) and subsequently demonstrating why one''s own position remains superior (rebuttal), enhancing ethos and refuting objections","Surrendering one''s primary thesis to agree with opposing perspectives","Insulting opponents to discourage debate","Omitting any mention of opposing evidence to maintain rhetorical consistency"]'::jsonb, 'Granting a valid opposing point demonstrates intellectual honesty (ethos) before refuting it (logos), neutralizing criticisms and strengthening the overall argument.'),
  ('ap-topic-englang-rhet_q15', 'ap-topic-englang-rhet', 15, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'Which syntactical scheme involves the repetition of a word or phrase at the beginning of successive sentences or clauses, as in Martin Luther King Jr.''s "I have a dream"?', '["Anaphora","Epistrophe","Asyndeton","Zeugma"]'::jsonb, 'Anaphora is the deliberate repetition of initial words or phrases across consecutive clauses, creating rhythmic momentum and emotional resonance.'),
  ('ap-topic-englang-rhet_q16', 'ap-topic-englang-rhet', 16, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'What constitutes an "either-or" (false dilemma) logical fallacy?', '["Presenting complex multifaceted issues as having only two extreme, mutually exclusive alternatives while ignoring intermediate possibilities","Drawing an absolute universal conclusion from an unrepresentative sample size of one","Using emotionally loaded terminology to cloud empirical reasoning","Restating the claim in different words as the proof of the claim"]'::jsonb, 'A false dilemma reduces a complex spectrum of choices into an artificial binary ("either you support this policy completely, or you want society to collapse"), manipulating the audience into choosing the preferred extreme.'),
  ('ap-topic-englang-rhet_q17', 'ap-topic-englang-rhet', 17, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'hard', 'In rhetorical terms, what is the meaning of "kairos"?', '["The opportune, opportune timing and cultural readiness for making an argument","The emotional intensity of vivid figurative descriptions","The logical coherence of a deductive syllogism","The length of the introductory paragraph"]'::jsonb, 'Kairos refers to the critical timeliness and appropriateness of a message: delivering the right words at the exact cultural or political moment when the audience is receptive.'),
  ('ap-topic-englang-rhet_q18', 'ap-topic-englang-rhet', 18, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'What is litotes in rhetorical style?', '["A deliberate understatement formulated by negating the opposite, such as \"She is not unmindful of the danger\"","An extreme, deliberate exaggeration used for comedic or dramatic effect","An address to an absent person or personified inanimate abstraction","The substitution of an associated object for the noun itself"]'::jsonb, 'Litotes employs double negatives or understatement by asserting a positive statement through the denial of its opposite (e.g., "not bad" meaning good, "no small matter" meaning very important).'),
  ('ap-topic-englang-rhet_q19', 'ap-topic-englang-rhet', 19, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'hard', 'What distinction separates inductive reasoning from deductive reasoning in rhetorical logic?', '["Inductive reasoning synthesizes specific empirical observations to formulate a generalized conclusion (probable truth); deductive reasoning applies a universal general premise to reach a specific necessary conclusion","Inductive reasoning guarantees mathematical certainty; deductive reasoning produces only vague probabilities","Inductive reasoning appeals strictly to emotions; deductive reasoning relies on authority","Both reasoning forms are logically identical"]'::jsonb, 'Induction moves from specific instances to general rules (scientific data synthesis). Deduction moves from broad universal premises through syllogisms to logically necessary specific instances.'),
  ('ap-topic-englang-rhet_q20', 'ap-topic-englang-rhet', 20, false, 'A', 'Rhetorical Analysis & Persuasive Devices', 'medium', 'What figure of speech is exemplified in the phrase: "The pen is mightier than the sword"?', '["Metonymy","Synecdoche","Personification","Hyperbole"]'::jsonb, 'Metonymy replaces the name of a concept with the name of an object closely linked to it: "pen" represents the written word/diplomacy, and "sword" represents military violence.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-englit-poetry_q1', 'ap-topic-englit-poetry', 1, false, 'B', 'Poetry', 'medium', 'A 14-line poem written in iambic pentameter with an ABAB CDCD EFEF GG rhyme scheme is a:', '["Petrarchan Sonnet","Shakespearean Sonnet","Villanelle","Ode"]'::jsonb, 'This structure defines an English or Shakespearean sonnet.'),
  ('ap-topic-englit-poetry_q2', 'ap-topic-englit-poetry', 2, false, 'A', 'Poetry & Devices', 'medium', 'What is the meter of a standard Shakespearean (English) sonnet?', '["Iambic pentameter (five pairs of unstressed/stressed syllables per line)","Dactylic hexameter","Trochaic tetrameter","Anapestic trimeter"]'::jsonb, 'Shakespearean sonnets consist of 14 lines of iambic pentameter with rhyme scheme $ABAB\,CDCD\,EFEF\,GG$.'),
  ('ap-topic-englit-poetry_q3', 'ap-topic-englit-poetry', 3, false, 'A', 'Poetry & Devices', 'medium', 'What is *enjambment* in poetry?', '["The continuation of a sentence or syntactic unit across the end of a poetic line without terminal punctuation","A pause marked by a comma or dash in the middle of a line","A rhyming couplet concluding a poem","The repetition of vowel sounds"]'::jsonb, 'Enjambment pulls the reader across line breaks without pausing, building momentum and altering emphasis.'),
  ('ap-topic-englit-poetry_q4', 'ap-topic-englit-poetry', 4, false, 'A', 'Poetry & Devices', 'medium', 'What poetic device is exemplified by "the leaves danced playfully in the whispering wind"?', '["Personification","Hyperbole","Synecdoche","Metonymy"]'::jsonb, 'Personification attributes human traits, emotions, and actions (dancing, whispering) to non-human elements.'),
  ('ap-topic-englit-poetry_q5', 'ap-topic-englit-poetry', 5, false, 'A', 'Poetry & Devices', 'medium', 'What is a *caesura* in verse?', '["A deliberate structural pause or break within a poetic line, often marked by a dash, colon, or period","The final rhyming syllable of a stanza","A poem written in praise of an object","The meter of epic poetry"]'::jsonb, 'Caesura creates rhythmic variation, tension, or contemplative pauses inside a verse line.'),
  ('ap-topic-englit-poetry_q6', 'ap-topic-englit-poetry', 6, false, 'A', 'Poetry & Devices', 'medium', 'What is *synecdoche*?', '["A figure of speech where a physical part of something represents the whole (e.g. ''all hands on deck'')","A comparison using ''like'' or ''as''","An intentional exaggeration","A pleasant-sounding combination of words"]'::jsonb, 'Synecdoche uses a constituent part to stand for the whole entity (''hands'' representing sailors).'),
  ('ap-topic-englit-poetry_q7', 'ap-topic-englit-poetry', 7, false, 'A', 'Poetry & Devices', 'medium', 'What is an *elegy*?', '["A formal, reflective poem lamenting the death of an individual or a solemn loss","A humorous five-line poem with AABBA rhyme","A 14-line love poem","A long narrative poem celebrating hero deeds"]'::jsonb, 'Elegies are meditative, mournful lyric poems dedicated to commemorating the deceased.'),
  ('ap-topic-englit-poetry_q8', 'ap-topic-englit-poetry', 8, false, 'A', 'Poetry & Devices', 'medium', 'What is *apostrophe* as a literary device in poetry?', '["A direct address to an absent person, an abstract concept (e.g. Death), or an inanimate object","A punctuation mark indicating possession only","The repetition of initial consonant sounds","An unrhymed line in a stanza"]'::jsonb, 'Apostrophe occurs when the speaker addresses a non-responsive or abstract entity directly (''O Romeo, Romeo!'').'),
  ('ap-topic-englit-poetry_q9', 'ap-topic-englit-poetry', 9, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'What metrical pattern defines standard Shakespearean sonnets, consisting of five metrical feet of an unstressed syllable followed by a stressed syllable per line?', '["Iambic pentameter","Trochaic tetrameter","Anapestic hexameter","Dactylic dimeter"]'::jsonb, 'Iambic pentameter consists of 5 iambs (unstressed-stressed: $\smile /$) per line, totaling 10 syllables (e.g., "Shall I compare thee to a summer''s day?").'),
  ('ap-topic-englit-poetry_q10', 'ap-topic-englit-poetry', 10, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'In an Italian (Petrarchan) sonnet, what is the structural turning point between the opening octave (8 lines) and the concluding sestet (6 lines) called?', '["Volta (turn)","Caesura","Refrain","Enjambment"]'::jsonb, 'The volta marks an emotional, thematic, or logical pivot where the poem shifts from presenting an emotional dilemma or question (octave) to offering a resolution or reflection (sestet).'),
  ('ap-topic-englit-poetry_q11', 'ap-topic-englit-poetry', 11, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'hard', 'What is a villanelle in poetic form?', '["A 19-line poem with 5 tercets and a final quatrain, structured around two repeating refrains and an ABA rhyme scheme (e.g., Dylan Thomas''s \"Do not go gentle into that good night\")","A 14-line poem written in unrhymed free verse","A mournful 3-stanza lament written exclusively for funerals","A narrative poem recounting chivalric battles in rhyming couplets"]'::jsonb, 'A villanelle has 19 lines: five tercets ($aba$) followed by a quatrain ($abaa$), with lines 1 and 3 of the first tercet recurring systematically as alternating refrains.'),
  ('ap-topic-englit-poetry_q12', 'ap-topic-englit-poetry', 12, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'What poetic device occurs when a syntactic sentence or thought runs over from one poetic line to the next without terminal punctuation?', '["Enjambment","End-stopped line","Caesura","Internal rhyme"]'::jsonb, 'Enjambment carries a phrase over the line break without punctuation, accelerating rhythm, creating suspense, or emphasizing the first word of the following line.'),
  ('ap-topic-englit-poetry_q13', 'ap-topic-englit-poetry', 13, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'Which literary device is used when a speaker directly addresses an absent person, a deceased figure, or a personified inanimate abstraction (e.g., "O Death, where is thy sting?")?', '["Apostrophe","Metonymy","Anachronism","Oxymoron"]'::jsonb, 'Apostrophe is a rhetorical figure where the speaker addresses an entity that cannot physically reply (e.g., the moon, nature, death, or an absent beloved).'),
  ('ap-topic-englit-poetry_q14', 'ap-topic-englit-poetry', 14, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'hard', 'What distinguishes a dramatic monologue (such as Robert Browning''s "My Last Duchess") from a soliloquy?', '["In a dramatic monologue, a single fictional persona addresses an identified silent auditor whose reactions shape the speaker''s involuntary self-revelation","In a dramatic monologue, the character is alone on stage speaking directly to themselves and the audience","A dramatic monologue must be written in unrhymed dactylic hexameter","A dramatic monologue contains multiple speaking characters conversing in dialogue"]'::jsonb, 'In a dramatic monologue, a distinct speaker reveals their psychological character to a silent in-poem listener (e.g., the envoy in "My Last Duchess"). A soliloquy is delivered when an actor is alone on stage disclosing inner thoughts.'),
  ('ap-topic-englit-poetry_q15', 'ap-topic-englit-poetry', 15, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'What is a "caesura" in poetry?', '["A deliberate pause or break occurring within the interior of a line of verse, often marked by a dash, comma, or period","The final rhyming couplet of an English sonnet","A regular repetition of vowel sounds across consonant boundaries","The substitution of an unrhymed syllable at the end of a stanza"]'::jsonb, 'A caesura (often denoted by $||$) is a rhythmic pause inside a line of poetry, creating dramatic tension, pacing shifts, or ideological contrast within the line.'),
  ('ap-topic-englit-poetry_q16', 'ap-topic-englit-poetry', 16, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'hard', 'What characterizes a "metaphysical conceit," famously utilized by poets like John Donne and George Herbert?', '["An elaborate, intellectually daring metaphor establishing an unexpected analogy between two seemingly disparate, unrelated objects (e.g., lovers'' souls and a drafting compass)","A simple conventional simile comparing beauty to a red rose","A pastoral poem praising rural shepherd life","An unrhymed medieval battle elegy"]'::jsonb, 'Metaphysical conceits forge startling, witty connections between spiritual emotional experiences and empirical science, geography, or mathematics (e.g., Donne comparing separated lovers to the twin feet of a compass).'),
  ('ap-topic-englit-poetry_q17', 'ap-topic-englit-poetry', 17, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'Which sound device is created by the repetition of internal vowel sounds in nearby words (e.g., "The cragg\underline{y} tr\underline{ee}s sl\underline{ee}p")?', '["Assonance","Consonance","Alliteration","Onomatopoeia"]'::jsonb, 'Assonance is the repetition of identical or similar vowel sounds within nearby non-rhyming words, creating lyrical musicality and emotional coloration.'),
  ('ap-topic-englit-poetry_q18', 'ap-topic-englit-poetry', 18, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'What is the rhyme scheme of a standard Shakespearean (English) sonnet?', '["ABAB CDCD EFEF GG","ABBA ABBA CDE CDE","AABB CCDD EEFF GG","ABCB DEFE GHIH JJ"]'::jsonb, 'A Shakespearean sonnet contains 14 lines organized into three quatrains and a closing rhyming couplet: $ABAB\;CDCD\;EFEF\;GG$.'),
  ('ap-topic-englit-poetry_q19', 'ap-topic-englit-poetry', 19, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'hard', 'What distinguishes free verse poetry from blank verse poetry?', '["Blank verse is written in unrhymed iambic pentameter, whereas free verse lacks both regular meter and regular rhyme scheme","Blank verse has no set rhythm; free verse always follows strict AABB rhyme","Free verse must always be written in 14 lines","Blank verse requires repeating refrains like a villanelle"]'::jsonb, 'Blank verse adheres strictly to unrhymed iambic pentameter (common in Shakespeare and Milton). Free verse (pioneered by Walt Whitman) discards fixed metrical patterns, line lengths, and end rhymes altogether.'),
  ('ap-topic-englit-poetry_q20', 'ap-topic-englit-poetry', 20, false, 'A', 'Poetic Forms, Meter & Figurative Devices', 'medium', 'What is synecdoche in poetic language?', '["A figure of speech in which a part of something is used to represent the whole (e.g., \"All hands on deck\")","The attribution of human emotional traits to inanimate landscape weather","A direct comparison between two things using \"like\" or \"as\"","A contradiction in terms that reveals a deeper truth"]'::jsonb, 'Synecdoche uses a literal part to signify the whole (e.g., "hands" representing sailors, "wheels" representing a car).'),
  ('ap-topic-arthist-ancient_q1', 'ap-topic-arthist-ancient', 1, false, 'A', 'Art History', 'easy', 'The Parthenon in Athens, Greece, was constructed in which architectural order?', '["Doric","Ionic","Corinthian","Composite"]'::jsonb, 'The Parthenon is a premier example of Classical Doric architecture.'),
  ('ap-topic-arthist-ancient_q2', 'ap-topic-arthist-ancient', 2, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What anatomical posturing distinguishes the Classical Greek *Doryphoros* (Spear Bearer) by Polykleitos from earlier Archaic Kouros statues?', '["*Contrapposto*: a dynamic, organic weight shift where weight rests on one leg, causing hips and shoulders to counterbalance naturally","A rigid, bilateral frontal stance with arms locked at sides and a stiff \"Archaic smile\"","A seated, highly stylized posture carved into relief basalt","An emotional, theatrical contortion characteristic of the Hellenistic period"]'::jsonb, 'Polykleitos developed his *Canon* of proportions and introduced *contrapposto* in *Doryphoros* (c. 450 BCE), replacing stiff Archaic kouroi with a naturalistic weight shift (engaged right leg, relaxed left leg).'),
  ('ap-topic-arthist-ancient_q3', 'ap-topic-arthist-ancient', 3, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What architectural innovation allowed the builders of the Roman Pantheon (c. 125 CE) to construct its massive unreinforced concrete dome?', '["Graded volcanic pozzolana concrete (lightened with pumice near the top), deep sunken ceiling coffers, and a central open oculus","Extensive wooden truss frameworks spanning the entire exterior","Solid granite blocks held together with molten lead dowels","A steel cantilever armature supporting the outer rotunda"]'::jsonb, 'Hadrian''s Pantheon remains the world''s largest unreinforced concrete dome. Engineers thinned the dome from base to summit, used lighter aggregates (pumice), carved weight-relieving sunken coffers, and pierced the apex with a 9-meter oculus.'),
  ('ap-topic-arthist-ancient_q4', 'ap-topic-arthist-ancient', 4, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'hard', 'How did the artistic style of the Amarna Period under Pharaoh Akhenaten (c. 1353-1336 BCE) break dramatically from traditional Egyptian canon?', '["Figures were depicted with curvilinear fluid forms, elongated necks, slack bellies, and intimate domestic family interactions under the Aten sun disk","Figures were depicted as hyper-idealized athletic warriors in rigid frontal symmetry","Human representation was outlawed in favor of purely geometric relief carvings","Sculptures were rendered exclusively in miniature bronze animal figurines"]'::jsonb, 'Akhenaten instituted monotheistic Aten worship and abandoned formal Egyptian conventions. Artworks (e.g., relief of Akhenaten, Nefertiti, and daughters) feature exaggerated curves, undulating lines, elongated skulls, and emotional tenderness.'),
  ('ap-topic-arthist-ancient_q5', 'ap-topic-arthist-ancient', 5, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What function did the prehistoric megalithic monument of Stonehenge serve in Neolithic Britain?', '["An astronomical calendar marking solar solstices and lunar cycles, and a ceremonial sacred burial landscape","A defensive stone fortress protecting an urban market","A subterranean storage bunker for harvested grains","A Roman civic forum and bathhouse"]'::jsonb, 'Stonehenge utilizes post-and-lintel construction with sarsen stones and bluestones aligned precisely with the sunrise on the summer solstice and sunset on the winter solstice, functioning as an astronomical observatory and funerary ritual site.'),
  ('ap-topic-arthist-ancient_q6', 'ap-topic-arthist-ancient', 6, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What political and divine message is communicated on the basalt *Stele of Hammurabi* (c. 1780 BCE)?', '["King Hammurabi receives the scepter and ring of kingship directly from the sun god Shamash, establishing the divine origin and legitimacy of his codified laws","Hammurabi is depicted bowing in defeat before an Egyptian pharaoh","The stele records a treaty ceding Babylonian lands to the Assyrian Empire","Hammurabi is shown sacrificing lions to celebrate an athletic victory"]'::jsonb, 'The relief at the top depicts Shamash handing symbols of sovereign authority to Hammurabi, validating the 282 legal rulings inscribed below in cuneiform as divinely ordained.'),
  ('ap-topic-arthist-ancient_q7', 'ap-topic-arthist-ancient', 7, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'hard', 'What stylistic evolution differentiates Hellenistic Greek sculpture (such as the *Seated Boxer* or *Winged Victory of Samothrace*) from Classical Greek sculpture?', '["Hellenistic sculpture embraces intense emotional pathos, dynamic diagonal movement, theatricality, and raw human vulnerability","Hellenistic sculpture returned to rigid, emotionless geometric abstraction","Hellenistic sculpture completely eliminated marble and bronze in favor of unfired clay","Hellenistic sculpture rejected all representations of the human form"]'::jsonb, 'Unlike the serene, self-contained idealism of the High Classical era (*Doryphoros*), Hellenistic art dramatizes theatrical emotion, bodily suffering (the battered *Seated Boxer*), and sweeping wind-whipped drapery (*Nike of Samothrace*).'),
  ('ap-topic-arthist-ancient_q8', 'ap-topic-arthist-ancient', 8, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What was the primary function of the colossal winged human-headed bulls (*Lamassu*) erected at the gateway palaces of Assyrian kings like Sargon II?', '["Apotropaic guardians designed to intimidate foreign ambassadors and spiritually protect the citadel from evil forces","Memorial tombstones marking the burial crypts of Assyrian queens","Support pillars holding up the central roof trusses of residential houses","Statues commemorating athletic wrestling victories"]'::jsonb, 'Lamassu were apotropaic guardian figures carved in high relief with five legs (appearing standing from the front and walking from the side), projecting imperial power and terrifying enemies.'),
  ('ap-topic-arthist-ancient_q9', 'ap-topic-arthist-ancient', 9, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What portrait style characterizes sculpture during the Roman Republic, as seen in the *Head of a Roman Patrician*?', '["*Verism*: an unvarnished, hyper-realistic depiction of aging, deep facial wrinkles, and baldness to signify gravitas, wisdom, and republican civic virtue","Hyper-youthful idealization based on Greek gods","Caricature intended to mock political rivals","Elongated abstract forms inspired by sub-Saharan wood carvings"]'::jsonb, 'Republican verism rejected youthful Greek perfection, emphasizing every wrinkle, furrow, and sunken cheek to project *gravitas* (seriousness), *dignitas*, and dutiful devotion to the Republic.'),
  ('ap-topic-arthist-ancient_q10', 'ap-topic-arthist-ancient', 10, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'hard', 'In the *Palette of King Narmer* (c. 3000 BCE), how is hierarchical scale utilized to convey political dominance?', '["King Narmer is depicted as significantly larger than all other human figures, visually asserting his supreme pharaonic authority over unified Upper and Lower Egypt","Enemy soldiers are depicted as giants towering over Egyptian warriors","The gods Horus and Hathor are shown smaller than common foot soldiers","All figures are drawn identical in height to symbolize social equality"]'::jsonb, 'Hierarchical scale (hieratic proportion) depicts Narmer substantially larger than his vizier, foot soldiers, and defeated foes, asserting divine kingship and political unification.'),
  ('ap-topic-arthist-ancient_q11', 'ap-topic-arthist-ancient', 11, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What optical refinements did architects Iktinos and Kallikrates incorporate into the Parthenon in Athens to correct for human visual distortions?', '["*Entasis* (slight convex swelling of the columns), leaning columns slightly inward, and bowing the stylobate upward in the center","Constructing columns with completely unequal diameters","Building the roof with a concave downward pitch","Leaving the temple open without any surrounding colonnade"]'::jsonb, 'To prevent straight lines from appearing sagged or pinched to the human eye from a distance, Greek architects bowed horizontal lines slightly upward and gave columns convex swelling (*entasis*).'),
  ('ap-topic-arthist-ancient_q12', 'ap-topic-arthist-ancient', 12, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What iconographical elements in the imperial statue *Augustus of Prima Porta* (c. 20 BCE) convey the Pax Romana and the emperor''s divine lineage?', '["The dolphin and cupid at his feet referencing descent from Venus, and the breastplate (cuirass) depicting the diplomatic return of Roman military standards from Parthia","A crown of thorns and a shepherd''s crook","A toga depicting scenes from the Trojan War with a lion headdress","A sword dripping with blood alongside defeated barbarian captives"]'::jsonb, 'Cupid riding a dolphin connects Augustus to Venus (via Aeneas), reinforcing his divine Julian descent. The breastplate commemorates his greatest diplomatic triumph: recovering Roman standards from the Parthians without war.'),
  ('ap-topic-arthist-ancient_q13', 'ap-topic-arthist-ancient', 13, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'hard', 'What distinguishes the Etruscan *Sarcophagus of the Spouses* (c. 520 BCE) from contemporary Archaic Greek funerary sculpture?', '["It depicts a husband and wife reclining together as equals on a banquet couch, reflecting the unusually prominent social status of Etruscan women","It is carved from solid Carrara marble with complete anatomical precision","It contains the mummified remains of Etruscan priests wrapped in linen","It forbids any depiction of female figures in accordance with Etruscan religious law"]'::jsonb, 'Unlike classical Greek banquets (symposia) where women were excluded, Etruscan society allowed married couples to banquet jointly, celebrated in this painted terracotta sarcophagus with animated gestural warmth.'),
  ('ap-topic-arthist-ancient_q14', 'ap-topic-arthist-ancient', 14, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What architectural format defines the New Kingdom Egyptian temple complex at Karnak (Temple of Amun-Re)?', '["Axial symmetry progressing through pylons, open peristyle courtyards, and a massive hypostyle hall with towering clerestory lighting, leading to a dark inner sanctuary","A circular rotunda topped with a hemispherical dome","A stepped ziggurat with exterior monumental ramps","An amphitheater cut into the living cliffside"]'::jsonb, 'Karnak represents classic pylon temple axial design: worshippers progressed along a sacred axis from bright courtyards into the monumental 134-column hypostyle hall, ending in the dim, restricted sanctuary of the god.'),
  ('ap-topic-arthist-ancient_q15', 'ap-topic-arthist-ancient', 15, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'Why were prehistoric cave paintings in Lascaux and Pech Merle predominantly located deep inside subterranean dark zones rather than near cave mouths?', '["They were ceremonial, ritual sanctuaries for shamanic hunting practices and spirit world communication rather than casual decorative dwelling art","Prehistoric humans lived permanently in the absolute dark depths of caves","The cave mouths had completely collapsed prior to human arrival","Early artists sought to protect the paintings from sunlight damage"]'::jsonb, 'Habitation occurred near cave entrances. The placement of paintings deep in pitch-black chambers accessible only through treacherous tunnels indicates sacred ritual, initiation, or hunting-magic significance.'),
  ('ap-topic-arthist-ancient_q16', 'ap-topic-arthist-ancient', 16, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'hard', 'How did the mortuary temple of Queen Hatshepsut at Deir el-Bahri harmoniously integrate with its natural environment?', '["Its three rising colonnaded terraces and horizontal colonnades visually mirror the dramatic vertical fissures and cliffs of the sandstone desert mountain behind it","It was constructed as a subterranean bunker hidden beneath the Nile floodwaters","It was built out of dark imported volcanic basalt that contrasted with the yellow desert","It was oriented away from the sun toward the north star"]'::jsonb, 'Designed by architect Senenmut, Hatshepsut''s terraced mortuary temple reflects organic harmony: its rhythmic pale limestone post-and-lintel colonnades echo the natural striations of the towering cliffs.'),
  ('ap-topic-arthist-ancient_q17', 'ap-topic-arthist-ancient', 17, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What scene is depicted on the Roman *Ludovisi Battle Sarcophagus* (c. 250 CE)?', '["A dense, highly crowded, chaotic battle scene between Roman soldiers and barbarian Goths, reflecting late imperial turmoil and a rejection of classical space","A peaceful pastoral banquet celebrating the harvest","A procession of senate patricians offering sacrifice at a temple","The coronation of Emperor Constantine in Byzantium"]'::jsonb, 'The Ludovisi Sarcophagus features deep relief with figures piled claustrophobically without a unified groundline, reflecting 3rd-century imperial anxiety, military crisis, and movement toward late antique expressionism.'),
  ('ap-topic-arthist-ancient_q18', 'ap-topic-arthist-ancient', 18, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What pottery technique was used to create the Athenian *Niobides Krater* (c. 460 BCE), allowing artists to paint delicate anatomical details with a brush rather than incising with a stylus?', '["Red-figure painting technique, where figures were reserved in natural red clay and negative space was painted with black slip","Black-figure technique, where figures were painted in black silhouettes and incised","White-ground lekythos technique used exclusively for domestic water jugs","Polychrome encaustic wax painting on terracotta"]'::jsonb, 'The red-figure technique, pioneered in Athens around 530 BCE, inverted black-figure: artists painted the background black, leaving figures in red terracotta, permitting subtle brushwork for muscles, facial expressions, and overlapping figures on multiple levels.'),
  ('ap-topic-arthist-ancient_q19', 'ap-topic-arthist-ancient', 19, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'hard', 'What structural purpose did a Mesopotamian ziggurat (such as the White Temple at Uruk) serve in ancient Sumerian society?', '["A monumental raised mud-brick platform elevating the temple closer to the sky gods, symbolizing a cosmic mountain and protecting the sacred shrine from floods","A tomb vault for burial of common civilian citizens","An amphitheater designed for public musical performances","A granary storage facility for storing dried fish"]'::jsonb, 'Sumerians built towering mud-brick ziggurats with bent-axis approaches to elevate the temple shrine (the "waiting room" of the deity) closer to heaven, functioning as the religious, administrative, and economic heart of the city-state.'),
  ('ap-topic-arthist-ancient_q20', 'ap-topic-arthist-ancient', 20, false, 'A', 'Ancient Mediterranean & Global Prehistory', 'medium', 'What material and structural system enabled Romans to construct the Colosseum (Flavian Amphitheater) with multi-tiered seating for 50,000 spectators?', '["Poured Roman concrete (opus caementicium) combined with a barrel-and-groin vaulted annular ring corridor system faced with travertine limestone","Solid carved marble post-and-lintel colonnades","Mud-brick walls reinforced with cedar timbers","Stacked dry-stone blocks without mortar"]'::jsonb, 'Concrete barrel and groin vaults formed annular ring corridors supporting the cavea tiers, allowing rapid entry and exit (vomitoria) while the exterior displayed classical architectural orders (Doric, Ionic, Corinthian).'),
  ('ap-topic-music-harmony_q1', 'ap-topic-music-harmony', 1, false, 'B', 'Music Theory', 'medium', 'In tonal harmony, a V - I chord cadence is called a:', '["Plagal Cadence","Authentic Cadence","Deceptive Cadence","Half Cadence"]'::jsonb, 'V to I creates a strong Authentic Cadence.'),
  ('ap-topic-music-harmony_q2', 'ap-topic-music-harmony', 2, false, 'A', 'Harmony & Voice Leading', 'medium', 'In four-part chorale voice leading (SATB), why are parallel perfect fifths and parallel perfect octaves strictly forbidden between any two voices?', '["They destroy the contrapuntal independence of the individual voices by merging them into an acoustic acoustic blend","They produce unacceptable dissonance that clashes with the tonic triad","They are physically unplayable on the pipe organ","They prevent the soprano from singing the melody"]'::jsonb, 'Parallel perfect consonances (5ths and 8ves) undermine polyphony because the human auditory system perceives the two moving voices as a single blended voice, destroying voice independence.'),
  ('ap-topic-music-harmony_q3', 'ap-topic-music-harmony', 3, false, 'A', 'Harmony & Voice Leading', 'medium', 'What chord sequence and melodic soprano condition define a Perfect Authentic Cadence (PAC)?', '["A $V$ (or $V^7$) to $I$ root-position progression, with the tonic scale degree ($\\hat{1}$) in the soprano of the final $I$ chord","A $IV$ to $I$ progression with $\\hat{3}$ in the soprano","A $V$ to $vi$ progression where the bass moves up by step","Any progression that ends on an inverted dominant $V^6$"]'::jsonb, 'A Perfect Authentic Cadence requires: both $V$ and $I$ in root position, and the soprano must resolve to the tonic pitch $\hat{1}$ on the final $I$ chord. (If either chord is inverted or soprano ends on $\hat{3}$ or $\hat{5}$, it is an Imperfect Authentic Cadence, IAC).'),
  ('ap-topic-music-harmony_q4', 'ap-topic-music-harmony', 4, false, 'A', 'Harmony & Voice Leading', 'medium', 'What cadence occurs when a phrase concludes on a dominant triad ($V$), creating an open, unresolved harmonic pause?', '["Half Cadence (HC)","Plagal Cadence (PC)","Deceptive Cadence (DC)","Phrygian Half Cadence exclusively in major"]'::jsonb, 'A Half Cadence ends on the dominant harmony ($V$), functioning like a comma in musical punctuation, requiring a subsequent phrase to provide harmonic resolution.'),
  ('ap-topic-music-harmony_q5', 'ap-topic-music-harmony', 5, false, 'A', 'Harmony & Voice Leading', 'hard', 'What is the figured bass inversion symbol for a second-inversion seventh chord?', '["$\\text{V}^{4}_{3}$","$\\text{V}^{6}_{5}$","$\\text{V}^{4}_{2}$","$\\text{V}^7$"]'::jsonb, 'Seventh chord inversions: Root position $= 7$; First inversion (third in bass) $= 6/5$; Second inversion (fifth in bass) $= 4/3$; Third inversion (seventh in bass) $= 4/2$ (or 2).'),
  ('ap-topic-music-harmony_q6', 'ap-topic-music-harmony', 6, false, 'A', 'Harmony & Voice Leading', 'medium', 'When resolving a dominant seventh chord ($V^7$) to tonic ($I$), what is the mandatory voice-leading resolution for the chordal seventh and the leading tone in an outer voice?', '["The chordal seventh must resolve step-wise downward by step ($\\hat{4} \\to \\hat{3}$), and the leading tone must resolve upward by half-step ($\\hat{7} \\to \\hat{1}$)","Both the seventh and leading tone must leap downward by a third","The seventh resolves upward to $\\hat{5}$, and the leading tone moves to $\\hat{2}$","The seventh remains static as a common tone"]'::jsonb, 'In $V^7$, the tritone between the leading tone ($\hat{7}$) and chordal seventh ($\hat{4}$) demands resolution: $\hat{7}$ resolves up to $\hat{1}$, while $\hat{4}$ resolves down to $\hat{3}$ in the tonic triad.'),
  ('ap-topic-music-harmony_q7', 'ap-topic-music-harmony', 7, false, 'A', 'Harmony & Voice Leading', 'hard', 'In a 4-3 suspension, what are the three successive metric phases of the non-chord tone?', '["Preparation (consonance on weak beat), Suspension (dissonance held on strong beat), Resolution (stepwise downward resolution to consonance on weak beat)","Attack on strong beat, leap upward by fifth, resolution to tonic","Consonance on strong beat, dissonance on weak beat, leap downward","Chromatic step upward, common tone held, octave leap"]'::jsonb, 'A suspension unfolds in three stages: Preparation (a note is sounded as a consonance), Suspension (the note is sustained as the bass moves, creating a metric accent dissonance), and Resolution (falls step-wise to a consonance).'),
  ('ap-topic-music-harmony_q8', 'ap-topic-music-harmony', 8, false, 'A', 'Harmony & Voice Leading', 'medium', 'What is a "Deceptive Cadence"?', '["A dominant chord ($V$) resolving unexpectedly to a submediant chord ($vi$ in major, $VI$ in minor) instead of the expected tonic ($I$)","A subdominant chord ($IV$) resolving directly to tonic ($I$)","A tonic chord resolving to an augmented sixth chord","A dominant seventh resolving to a diminished seventh"]'::jsonb, 'A Deceptive Cadence deceives the ear''s expectation of tonic resolution by substituting the submediant ($vi$) for $I$ following a dominant $V$, allowing phrase expansion.'),
  ('ap-topic-music-harmony_q9', 'ap-topic-music-harmony', 9, false, 'A', 'Harmony & Voice Leading', 'hard', 'What chord is a secondary dominant ($V^7/V$) in the key of C Major?', '["$D^7$ (D - F# - A - C)","$G^7$ (G - B - D - F)","$A^7$ (A - C# - E - G)","$C^7$ (C - E - G - Bb)"]'::jsonb, 'In C Major, the dominant is G Major ($V$). The dominant seventh of G Major is built on D ($D - F\sharp - A - C$), which is $D^7$. Thus, $V^7/V$ in C Major is $D^7$.'),
  ('ap-topic-music-harmony_q10', 'ap-topic-music-harmony', 10, false, 'A', 'Harmony & Voice Leading', 'medium', 'What is a "Plagal Cadence"?', '["A $IV \\to I$ (subdominant to tonic) progression, often called the \"Amen\" cadence","A $V \\to I$ progression in root position","A $ii^6 \\to V$ progression preceding a half cadence","A $vii^{\\circ 6} \\to I$ progression"]'::jsonb, 'A Plagal Cadence moves from subdominant ($IV$) to tonic ($I$), historically familiar as the concluding "Amen" in sacred choral hymns.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-music-harmony_q11', 'ap-topic-music-harmony', 11, false, 'A', 'Harmony & Voice Leading', 'medium', 'Which non-chord tone is approached by leap and resolved by stepwise motion in the opposite direction?', '["Appoggiatura","Passing tone","Neighbor tone","Suspension"]'::jsonb, 'An appoggiatura is an accented non-chord tone that is approached by an upward (or downward) leap and resolved step-wise in the contrary direction.'),
  ('ap-topic-music-harmony_q12', 'ap-topic-music-harmony', 12, false, 'A', 'Harmony & Voice Leading', 'hard', 'When doubling notes in a root-position major or minor triad in four-part SATB harmony, what note is the primary and most acoustically stable choice to double?', '["The root of the triad","The third of the triad","The fifth of the triad","The seventh of the triad"]'::jsonb, 'In root-position triads, doubling the root reinforces the fundamental acoustic harmonic series and provides stability. Doubling the third is generally avoided (especially if it is a tendency tone like the leading tone).'),
  ('ap-topic-music-harmony_q13', 'ap-topic-music-harmony', 13, false, 'A', 'Harmony & Voice Leading', 'medium', 'What is a "passing tone"?', '["A non-chord tone that fills the melodic interval of a third between two chord tones by stepwise motion in the same direction","A non-chord tone that steps away from a chord tone and returns to the same chord tone","A note held as a pedal point in the lowest bass voice","A chromatic inflection used to modulate to a foreign key"]'::jsonb, 'A passing tone connects two distinct chord tones a third apart by moving in scalar stepwise fashion in a consistent direction.'),
  ('ap-topic-music-harmony_q14', 'ap-topic-music-harmony', 14, false, 'A', 'Harmony & Voice Leading', 'hard', 'In harmonic minor keys, why must the seventh scale degree be raised by an accidental when writing dominant harmonies ($V$ or $V^7$)?', '["To create a leading tone a half-step below the tonic, ensuring a pull that drives authentic cadential resolution","To avoid augmented fourth intervals with the subdominant","To convert the minor key into a parallel major key permanently","Because minor keys cannot contain minor triads"]'::jsonb, 'Natural minor possesses a subtonic (whole step below tonic). Raising $\hat{7}$ by a half step creates the leading tone, transforming minor $v$ into a major dominant $V$ with a resolving leading tone to $\hat{1}$.'),
  ('ap-topic-music-harmony_q15', 'ap-topic-music-harmony', 15, false, 'A', 'Harmony & Voice Leading', 'medium', 'What constitutes a "neighbor tone" (auxiliary tone)?', '["A non-chord tone that steps away from a chord tone (up or down) and immediately steps back to the original chord tone","A non-chord tone that leaps to another chord tone","A chord tone sustained across two full bars","A chromatic alteration of the root note"]'::jsonb, 'A neighbor tone departs from a chord tone by step (upper or lower neighbor) and returns to the same pitch.'),
  ('ap-topic-music-harmony_q16', 'ap-topic-music-harmony', 16, false, 'A', 'Harmony & Voice Leading', 'hard', 'What is a "pivot chord" in common-practice diatonic modulation?', '["A chord that serves a dual diatonic harmonic function in both the initial home key and the destination new key","An augmented sixth chord resolving outward to an octave","A chord played exclusively by the brass section during a key change","A dissonant non-functional chord that halts the progression"]'::jsonb, 'A pivot chord (common chord) belongs naturally to both the departing key and arriving key (e.g., $vi$ in C major is $ii$ in G major), providing a smooth harmonic bridge for modulation.'),
  ('ap-topic-music-harmony_q17', 'ap-topic-music-harmony', 17, false, 'A', 'Harmony & Voice Leading', 'medium', 'In first inversion triads (figured as 6), what note is located in the lowest (bass) voice?', '["The third of the triad","The root of the triad","The fifth of the triad","The seventh of the triad"]'::jsonb, 'In first inversion, the chordal third is in the bass, creating an interval of a 6th and a 3rd above the bass, indicated in figured bass as 6 (short for 6/3).'),
  ('ap-topic-music-harmony_q18', 'ap-topic-music-harmony', 18, false, 'A', 'Harmony & Voice Leading', 'hard', 'What voice-leading error occurs if two voices leap in the same direction into a perfect fifth or octave, and the highest voice leaps?', '["Direct (hidden) fifths or octaves","Parallel fifths","Voice crossing","Voice overlap"]'::jsonb, 'Direct (hidden) octaves or fifths occur when the soprano and bass move by similar motion into a perfect consonance and the soprano leaps, which can sound like parallel fifths/octaves.'),
  ('ap-topic-music-harmony_q19', 'ap-topic-music-harmony', 19, false, 'A', 'Harmony & Voice Leading', 'medium', 'What is a "pedal point" in harmonic analysis?', '["A sustained or repeated pitch (usually in the bass) that persists while harmonies in the upper voices shift around it, creating alternating consonance and dissonance","A rapid pedal alternation on the harp","The highest note achievable on a piccolo","A dynamic marking instructing the player to play softly"]'::jsonb, 'Named after organ foot pedals, a pedal point sustains a single pitch (most often the tonic or dominant in the bass) while shifting chord progressions move above it.'),
  ('ap-topic-music-harmony_q20', 'ap-topic-music-harmony', 20, false, 'A', 'Harmony & Voice Leading', 'hard', 'What is the standard functional progression of harmonic syntax in common-practice Western art music?', '["Tonic ($I$) $\\to$ Predominant ($ii$ or $IV$) $\\to$ Dominant ($V$ or $vii^\\circ$) $\\to$ Tonic ($I$)","Dominant $\\to$ Predominant $\\to$ Tonic $\\to$ Submediant","Tonic $\\to$ Dominant $\\to$ Predominant $\\to$ Subdominant","Predominant $\\to$ Tonic $\\to$ Dominant $\\to$ Subdominant"]'::jsonb, 'Tonal functional harmony follows the syntactical cycle: Tonic establishes stability $\to$ Predominant prepares dominant tension $\to$ Dominant creates instability $\to$ Tonic resolves the cycle ($T \to PD \to D \to T$).'),
  ('ap-topic-2dart-portfolio_q1', 'ap-topic-2dart-portfolio', 1, false, 'A', '2-D Art', 'easy', 'Which principle of design refers to the visual weight distribution in a 2-D artwork?', '["Balance","Proportion","Rhythm","Contrast"]'::jsonb, 'Balance addresses symmetry, asymmetry, and weight distribution.'),
  ('ap-topic-2dart-portfolio_q2', 'ap-topic-2dart-portfolio', 2, false, 'A', 'Composition & Design Elements', 'medium', 'How is visual balance achieved in an asymmetrical two-dimensional composition?', '["By balancing disparate visual elements of varying size, color, value, or texture across an informal axis so they possess equal visual weight","By arranging identical mirrored elements on either side of a strict central vertical axis","By placing all large dark objects in the exact center of the canvas","By eliminating all negative space from the composition"]'::jsonb, 'Asymmetrical balance relies on informal balance: a small intense saturated color or complex texture can counterbalance a large muted shape, creating dynamic equilibrium without symmetry.'),
  ('ap-topic-2dart-portfolio_q3', 'ap-topic-2dart-portfolio', 3, false, 'A', 'Composition & Design Elements', 'medium', 'What color harmony utilizes colors that sit directly opposite each other on the standard color wheel (e.g., blue and orange)?', '["Complementary color scheme","Analogous color scheme","Monochromatic color scheme","Triadic color scheme"]'::jsonb, 'Complementary colors reside directly across the color wheel. Juxtaposing them maximizes simultaneous contrast, making both colors appear more vibrant.'),
  ('ap-topic-2dart-portfolio_q4', 'ap-topic-2dart-portfolio', 4, false, 'A', 'Composition & Design Elements', 'medium', 'How does the "rule of thirds" guide compositional layout in 2-D design?', '["By dividing the frame into a $3 \\times 3$ grid and positioning primary focal points along the gridlines or at their four intersections","By requiring that an artwork contain exactly three colors and three shapes","By leaving one-third of the canvas completely blank","By drawing all figures with triangular geometric shapes"]'::jsonb, 'The rule of thirds offsets focal elements from the dead center, aligning them with vertical and horizontal third-lines or intersection points to create natural visual flow.'),
  ('ap-topic-2dart-portfolio_q5', 'ap-topic-2dart-portfolio', 5, false, 'A', 'Composition & Design Elements', 'hard', 'In the AP 2-D Art and Design Portfolio, what defines "Sustained Investigation"?', '["An inquiry-based, in-depth exploration of materials, processes, and ideas centered on a guiding question, documented across related artworks and process notes","A collection of 15 unrelated technical master copies of historic paintings","A timed four-hour drawing exercise completed without revisions","A digital animation reel submitted without preparatory sketches"]'::jsonb, 'The Sustained Investigation requires students to formulate an inquiry question and demonstrate practice, experimentation, and revision over time through 15 digital slides showing finished works and process documentation.'),
  ('ap-topic-2dart-portfolio_q6', 'ap-topic-2dart-portfolio', 6, false, 'A', 'Composition & Design Elements', 'medium', 'What is the figure-ground relationship in two-dimensional graphic design?', '["The perceptual distinction between the positive shape of the focal subject (figure) and the surrounding negative background space (ground)","The physical ratio between the weight of oil paint and canvas thickness","The measurement of human figures relative to real-life scale","The chemical reaction between gesso primer and ink"]'::jsonb, 'Figure-ground organization (a core Gestalt visual principle) refers to how the viewer''s brain distinguishes positive forms (figure) from the surrounding or underlying negative space (ground).'),
  ('ap-topic-2dart-portfolio_q7', 'ap-topic-2dart-portfolio', 7, false, 'A', 'Composition & Design Elements', 'medium', 'How do designers create "visual hierarchy" on a poster or digital page?', '["By manipulating scale, contrast, value, color, and placement to guide the viewer''s eye to the most critical information first","By making all text fonts identical in size and boldness","By placing all elements randomly across the margins","By removing all blank space between paragraphs"]'::jsonb, 'Visual hierarchy structures information priority. Dominant headers, high-contrast colors, and scale variations direct eye movement from primary focal elements down to supporting secondary details.'),
  ('ap-topic-2dart-portfolio_q8', 'ap-topic-2dart-portfolio', 8, false, 'A', 'Composition & Design Elements', 'hard', 'What is the difference between a shape''s "value" and its "chroma" (saturation)?', '["Value refers to the relative lightness or darkness of a hue, whereas chroma refers to its purity, intensity, or saturation","Value refers to the monetary worth of pigments; chroma refers to drying time","Value is unique to acrylic paint; chroma applies only to watercolors","Value and chroma are identical terms for hue"]'::jsonb, 'Color dimensions include hue (the color family, e.g., blue), value (lightness/darkness from white to black), and chroma/saturation (intensity from dull gray to pure vibrant pigment).'),
  ('ap-topic-2dart-portfolio_q9', 'ap-topic-2dart-portfolio', 9, false, 'A', 'Composition & Design Elements', 'medium', 'Which principle of design creates a sense of visual oneness, cohesiveness, and harmony among diverse elements in a work?', '["Unity","Variety","Emphasis","Contrast"]'::jsonb, 'Unity ties the elements together into an integrated whole through repetition, proximity, continuity, and consistent palette, preventing visual chaos.'),
  ('ap-topic-2dart-portfolio_q10', 'ap-topic-2dart-portfolio', 10, false, 'A', 'Composition & Design Elements', 'medium', 'What is a "monochromatic" color scheme?', '["A color palette derived from a single base hue extended using its tints (with white), shades (with black), and tones (with gray)","A palette containing only black and white with no color pigments","A combination of three equidistant hues on the color wheel","A composition using every primary and secondary color simultaneously"]'::jsonb, 'Monochromatic designs utilize variations of one single hue, modulating value and saturation through tints, shades, and tones to produce cohesive harmony.'),
  ('ap-topic-2dart-portfolio_q11', 'ap-topic-2dart-portfolio', 11, false, 'A', 'Composition & Design Elements', 'hard', 'How does the concept of "repetition with variation" prevent visual monotony in rhythm and pattern?', '["By repeating recurring motifs while subtly altering their scale, orientation, color, or texture to maintain viewer engagement","By placing identical stamps in straight rigid rows across the picture plane","By erasing every alternate element on the canvas","By changing the canvas size halfway through production"]'::jsonb, 'Unvaried repetition creates dullness; introducing subtle variations in size, angle, or value injects visual interest while preserving underlying rhythmic rhythm.'),
  ('ap-topic-2dart-portfolio_q12', 'ap-topic-2dart-portfolio', 12, false, 'A', 'Composition & Design Elements', 'medium', 'What design principle is utilized when an artist introduces a sudden stark change in size, value, or color to draw the viewer''s focus to a specific area?', '["Contrast and Emphasis","Formal symmetry","Subordination","Atmospheric blurring"]'::jsonb, 'Contrast juxtaposes opposing visual properties (e.g., dark against light, rough against smooth), creating a focal point of emphasis that anchors visual attention.'),
  ('ap-topic-2dart-portfolio_q13', 'ap-topic-2dart-portfolio', 13, false, 'A', 'Composition & Design Elements', 'medium', 'In digital graphic design, what is the primary advantage of working with vector graphics (e.g., SVG, AI) over raster graphics (e.g., JPEG, PNG)?', '["Vector graphics are defined by mathematical formulas (points, lines, curves) and can scale infinitely without pixelation or loss of clarity","Vector graphics represent photorealistic natural camera textures better than raster images","Vector graphics can only be viewed in black and white","Vector files cannot be edited after export"]'::jsonb, 'Vector graphics rely on scalable geometric paths, permitting resolution-independent resizing from postage stamps to billboards without degradation. Raster images are grid-dependent pixels that pixelate when enlarged.'),
  ('ap-topic-2dart-portfolio_q14', 'ap-topic-2dart-portfolio', 14, false, 'A', 'Composition & Design Elements', 'hard', 'What is an "analogous" color scheme in design?', '["A palette of colors that sit adjacent to each other on the color wheel (such as yellow, yellow-green, and green), sharing a common base hue","A palette formed by two complementary color pairs","A scheme that excludes all primary colors","Colors that have identical chemical properties"]'::jsonb, 'Analogous colors are side-by-side neighbors on the color wheel, creating serene, low-contrast, naturally harmonious palettes.'),
  ('ap-topic-2dart-portfolio_q15', 'ap-topic-2dart-portfolio', 15, false, 'A', 'Composition & Design Elements', 'medium', 'What role does "negative space" play in successful two-dimensional compositions?', '["It defines positive forms, provides breathing room, prevents visual clutter, and balances the composition","It represents accidental errors that must be painted over","It decreases the readability of text and figures","It is only found in photographic contact sheets"]'::jsonb, 'Negative space is the intentional unoccupied area around and between subjects. Active use of negative space clarifies silhouettes, balances positive weight, and guides ocular rhythm.'),
  ('ap-topic-2dart-portfolio_q16', 'ap-topic-2dart-portfolio', 16, false, 'A', 'Composition & Design Elements', 'medium', 'In typography, what distinguishes a "serif" typeface from a "sans-serif" typeface?', '["Serif fonts feature small decorative finishing strokes (feet) at the ends of letter stems, while sans-serif fonts have clean, unembellished line endings","Serif fonts can only be rendered in italicized script","Sans-serif fonts cannot be used on computer screens","Serif typefaces have no lowercase letters"]'::jsonb, 'Serifs are small projected feet at stroke ends (e.g., Times New Roman). Sans-serif ("without serif") fonts (e.g., Helvetica, Arial) feature clean strokes, favored in modern digital UI.'),
  ('ap-topic-2dart-portfolio_q17', 'ap-topic-2dart-portfolio', 17, false, 'A', 'Composition & Design Elements', 'hard', 'What is "implied line" in visual art and design?', '["A perceived path of eye movement suggested by aligned edges, sightlines of figures, or directional pointers without a continuous physical drawn stroke","A line drawn with invisible UV ink","A line etched into a copper printmaking plate","A contour line drawn with a graphite 6B pencil"]'::jsonb, 'An implied line is an optical pathway constructed by the viewer''s cognitive closure (e.g., where a depicted subject looks, pointing gestures, or rhythmic spacing of discrete shapes).'),
  ('ap-topic-2dart-portfolio_q18', 'ap-topic-2dart-portfolio', 18, false, 'A', 'Composition & Design Elements', 'medium', 'What is the "golden ratio" (approximately $1.618$) frequently applied to classical and modern composition?', '["A mathematical proportional relationship where the ratio of the whole to the larger segment equals the ratio of the larger to the smaller segment, yielding aesthetically pleasing balance","The exact weight ratio of oil to turpentine in glaze mixing","The speed at which oil paint oxidizes in natural light","The ratio of primary colors to secondary colors in a painting"]'::jsonb, 'The golden ratio ($\phi \approx 1.618$) produces natural harmonic proportions (e.g., Fibonacci spiral, golden rectangle) celebrated for organic aesthetic balance in architectural and visual layouts.'),
  ('ap-topic-2dart-portfolio_q19', 'ap-topic-2dart-portfolio', 19, false, 'A', 'Composition & Design Elements', 'medium', 'What is "radial balance" in two-dimensional design?', '["A circular composition where visual elements radiate outward from a central focal hub, like ripples in water or a rose window","A grid-based layout with vertical columns of equal width","An asymmetrical scatter of triangles in one corner","A black-and-white print with high value contrast"]'::jsonb, 'Radial balance organizes elements around a shared central focal point, radiating outward uniformly in rotational symmetry (e.g., mandalas, spokes of a wheel).'),
  ('ap-topic-2dart-portfolio_q20', 'ap-topic-2dart-portfolio', 20, false, 'A', 'Composition & Design Elements', 'hard', 'In color theory, what is "simultaneous contrast"?', '["The optical effect where two adjacent colors influence each other''s appearance, causing them to look more intensely saturated or shift in perceived hue and value","Mixing complementary pigments together on a palette until they form neutral gray","Printing two layers of CMYK ink at the exact same moment","The fading of color pigments when exposed to incandescent lighting"]'::jsonb, 'Identified by Michel Eugène Chevreul, simultaneous contrast explains that placing two colors side by side causes the eye to project the complementary color onto each neighbor, accentuating differences in hue and value.'),
  ('ap-topic-3dart-sculpture_q1', 'ap-topic-3dart-sculpture', 1, false, 'B', '3-D Art', 'easy', 'Sculpting by removing material from a block of wood or stone is called:', '["Additive process","Subtractive process","Modeling","Assembling"]'::jsonb, 'Carving is a subtractive process.'),
  ('ap-topic-3dart-sculpture_q2', 'ap-topic-3dart-sculpture', 2, false, 'A', 'Form, Space & Materials', 'medium', 'What is the fundamental difference between an additive sculptural process and a subtractive sculptural process?', '["Additive sculpture builds up a form by assembling or modeling materials (e.g., clay modeling, metal welding); subtractive sculpture carves away material from a solid block (e.g., marble or wood carving)","Additive sculpture uses only organic materials; subtractive sculpture uses only plastics","Additive sculpture is two-dimensional; subtractive sculpture is three-dimensional","Additive sculpture requires casting in bronze, while subtractive sculpture requires 3D printing"]'::jsonb, 'Additive processes construct form by joining or adding materials (clay modeling, welded steel, assemblage). Subtractive processes reveal form by removing, chiseling, or carving away excess mass from a parent block.'),
  ('ap-topic-3dart-sculpture_q3', 'ap-topic-3dart-sculpture', 3, false, 'A', 'Form, Space & Materials', 'medium', 'How does "sculpture in the round" (freestanding sculpture) differ from relief sculpture?', '["Freestanding sculpture is finished and intended to be viewed from all 360 degrees, while relief sculpture projects from a supporting two-dimensional background plane","Freestanding sculpture must be hung on a gallery wall","Relief sculpture can only be viewed outdoors","Sculpture in the round must be cast in liquid wax"]'::jsonb, 'Freestanding sculpture in the round is fully 3D and unattached to any backing, encouraging the spectator to walk around it. Relief sculpture (bas-relief or high-relief) projects from a flat backing matrix.'),
  ('ap-topic-3dart-sculpture_q4', 'ap-topic-3dart-sculpture', 4, false, 'A', 'Form, Space & Materials', 'medium', 'What defines "kinetic sculpture" in modern 3-D art, as pioneered by Alexander Calder?', '["A three-dimensional artwork that incorporates actual physical movement powered by wind, motorized mechanisms, or viewer interaction (e.g., hanging mobiles)","A sculpture that depicts a runner frozen in motion using marble","A neon light installation that does not physically move","A bronze statue mounted on a revolving turntable"]'::jsonb, 'Kinetic sculpture makes physical movement an integral formal component. Alexander Calder''s delicately balanced hanging mobiles move with subtle ambient air currents.'),
  ('ap-topic-3dart-sculpture_q5', 'ap-topic-3dart-sculpture', 5, false, 'A', 'Form, Space & Materials', 'hard', 'In three-dimensional design, what is "negative space" (or negative volume)?', '["The empty space or opening enclosed by, flowing through, or immediately surrounding the positive sculptural mass (e.g., voids in Henry Moore sculptures)","The weight of the pedestal holding up the sculpture","Material lost during foundry metal casting","The shadow cast onto the gallery floor"]'::jsonb, 'Negative space in 3D art is the activated void within or between physical forms. Sculptors like Henry Moore treated pierced voids as expressive sculptural elements equal in importance to solid mass.'),
  ('ap-topic-3dart-sculpture_q6', 'ap-topic-3dart-sculpture', 6, false, 'A', 'Form, Space & Materials', 'medium', 'What is "assemblage" in sculptural practice?', '["A three-dimensional composition constructed from pre-existing found objects, manufactured items, and scavenged raw materials","Carving a single block of wood using traditional gouges","Melting scrap copper into an ingot","Throwing a clay vessel on a potter''s wheel"]'::jsonb, 'Assemblage (pioneered by Dadaists and artists like Louise Nevelson) constructs 3D works out of non-traditional found materials and ready-mades, recontextualizing everyday artifacts.'),
  ('ap-topic-3dart-sculpture_q7', 'ap-topic-3dart-sculpture', 7, false, 'A', 'Form, Space & Materials', 'hard', 'What structural factor dictates the stability of a freestanding monumental sculpture resting on a small base?', '["Ensuring that the center of gravity of the sculpture falls vertically inside the perimeter of its base of support","Painting the upper surface with a lighter color value","Using hollow clay throughout the sculpture","Polishing the outer surface to reduce wind resistance"]'::jsonb, 'Physical equilibrium requires that the sculpture''s center of gravity project vertically within its ground contact boundary (base of support), preventing tipping torques without hidden internal armatures.'),
  ('ap-topic-3dart-sculpture_q8', 'ap-topic-3dart-sculpture', 8, false, 'A', 'Form, Space & Materials', 'medium', 'What is an "armature" in sculpture?', '["An internal rigid framework or skeletal skeleton (often made of wire, wood, or steel) built to support heavy malleable modeling materials like clay or plaster","The outer protective wax layer applied to finished bronze","The wooden pedestal on which a statue is exhibited","The chisel used to carve lettering into granite"]'::jsonb, 'An armature serves as the internal structural skeleton that prevents wet clay, wax, or plaster from sagging or collapsing under gravity during modeling.'),
  ('ap-topic-3dart-sculpture_q9', 'ap-topic-3dart-sculpture', 9, false, 'A', 'Form, Space & Materials', 'medium', 'What defines a "site-specific" sculpture or installation (such as Robert Smithson''s *Spiral Jetty*)?', '["An artwork conceived, designed, and physically integrated with a specific location, whose meaning is inextricably linked to its physical, ecological, or architectural context","A portable bronze statue that can be shipped to any gallery worldwide","A sculpture that is always housed indoors under controlled museum lighting","A miniature clay maquette made for classroom evaluation"]'::jsonb, 'Site-specific art (including Earthworks) is created for and inseparable from its particular landscape or architectural environment; removing it destroys its context and intended meaning.'),
  ('ap-topic-3dart-sculpture_q10', 'ap-topic-3dart-sculpture', 10, false, 'A', 'Form, Space & Materials', 'hard', 'What is the lost-wax casting process (*cire perdue*) in traditional metal sculpture?', '["A casting method where a duplicate metal sculpture is cast from an original wax model: the wax is melted away inside a refractory mold and replaced with molten bronze","Carving away wax until a solid stone figure emerges","Welding pre-cut sheets of steel together with oxyacetylene torches","Dipping dried clay into molten glass"]'::jsonb, 'Lost-wax casting involves modeling a wax original, coating it with heat-resistant plaster/ceramic slurry, heating the mold to melt and drain the wax ("lost wax"), and pouring molten bronze into the resulting hollow cavity.'),
  ('ap-topic-3dart-sculpture_q11', 'ap-topic-3dart-sculpture', 11, false, 'A', 'Form, Space & Materials', 'medium', 'In three-dimensional design, what constitutes "bas-relief" (low relief) sculpture?', '["Forms that project only slightly and shallowly from the background surface (such as the raised portrait on a minted coin)","Sculptural figures that are undercut and detached almost completely from the wall","A hollow bronze statue with zero thickness","A stone carving with deep recesses exceeding half the volume of the figures"]'::jsonb, 'Bas-relief (low relief) has minimal projection from the background plane, casting soft shadows without substantial undercutting, as seen on coins or friezes.'),
  ('ap-topic-3dart-sculpture_q12', 'ap-topic-3dart-sculpture', 12, false, 'A', 'Form, Space & Materials', 'medium', 'How do 3-D artists utilize "planes" in sculptural construction?', '["By assembling flat two-dimensional surface sheets (like cardboard, sheet metal, or plywood) at varying angles to enclose and define three-dimensional volumes","By sanding wood surfaces until all corners are rounded into spheres","By throwing clay exclusively on motorized rotating wheels","By painting shadows onto gallery pedestal walls"]'::jsonb, 'Planar construction translates flat 2D planes into 3D forms: interlocking, folding, or welding flat sheets creates geometric facets, internal voids, and angular volumes.'),
  ('ap-topic-3dart-sculpture_q13', 'ap-topic-3dart-sculpture', 13, false, 'A', 'Form, Space & Materials', 'hard', 'What is "tensile strength" in sculptural materials, and how does it compare to "compressive strength"?', '["Tensile strength is the ability of a material to withstand stretching or pulling forces without snapping (high in steel cable); compressive strength is the ability to withstand crushing or pushing loads (high in stone and concrete)","Tensile strength refers to resistance to water; compressive strength refers to fire resistance","Both terms refer to the shiny luster of polished bronze","Stone has high tensile strength and steel has zero compressive strength"]'::jsonb, 'Stone, concrete, and brick have immense compressive strength (support immense weight pushing down) but weak tensile strength (crack under bending/pulling). Steel and rope excel under tension.'),
  ('ap-topic-3dart-sculpture_q14', 'ap-topic-3dart-sculpture', 14, false, 'A', 'Form, Space & Materials', 'medium', 'What is a "maquette" in sculptural planning?', '["A small preliminary scale model or study made of clay, wax, or wire to test form, balance, and proportions before fabricating the full-scale sculpture","The finished stone sculpture ready for gallery display","The certificate of authenticity signed by an art dealer","The mold used to melt gold ingots"]'::jsonb, 'Sculptors create maquettes as rapid 3D prototypes to work out compositional lines, spatial dynamics, and structural balance before committing expensive materials and labor to full scale.'),
  ('ap-topic-3dart-sculpture_q15', 'ap-topic-3dart-sculpture', 15, false, 'A', 'Form, Space & Materials', 'medium', 'How does tactile texture differ from visual texture in three-dimensional sculpture?', '["Tactile texture is the actual, physical surface feel (rough, smooth, ribbed, abrasive) that can be experienced through touch; visual texture is the optical illusion of surface feel on a 2D plane","Tactile texture applies only to digital 3D models","Visual texture can only be felt with bare hands","There is no distinction in three-dimensional art"]'::jsonb, 'In 3D sculpture, texture is literal and tactile: the grain of unpolished limestone, the chill of brushed steel, or the roughness of burlap, engaging the viewer''s somatosensory perception.'),
  ('ap-topic-3dart-sculpture_q16', 'ap-topic-3dart-sculpture', 16, false, 'A', 'Form, Space & Materials', 'hard', 'What defines "ephemeral sculpture" in contemporary art practice (such as Andy Goldsworthy''s ice or leaf arrangements)?', '["Sculpture made from transient, impermanent natural materials designed to decay, melt, or disperse back into the environment over time, documented primarily through photography","Sculpture carved from diamond-hard granite intended to survive for millennia","A bronze statue cast inside an airtight museum vitrine","Cast iron railway spikes forged into permanent furniture"]'::jsonb, 'Ephemeral art embraces transience and entropy: using leaves, river ice, flower petals, or sand, the artist constructs delicate forms that disintegrate naturally, surviving only via photographic records.'),
  ('ap-topic-3dart-sculpture_q17', 'ap-topic-3dart-sculpture', 17, false, 'A', 'Form, Space & Materials', 'medium', 'What is the role of light and shadow in activating the surface of three-dimensional sculpture?', '["Directional illumination defines three-dimensional relief, reveals surface texture, creates cast shadows, and clarifies form in space","Lighting has zero effect on three-dimensional forms","Light serves only to dry the sculptural sealant","Light flattens 3D sculpture into a 2D silhouette under all angles"]'::jsonb, 'Without directional light, 3D form cannot be visually perceived. Highlights, core shadows, and deep cast shadows define contours, undercuts, and spatial depth in real time.'),
  ('ap-topic-3dart-sculpture_q18', 'ap-topic-3dart-sculpture', 18, false, 'A', 'Form, Space & Materials', 'medium', 'What is "cantilever" construction in three-dimensional sculpture and architecture?', '["A horizontal beam, slab, or form that extends out into space supported only at one anchored end, with no vertical support beneath the overhang","A vertical column supporting an architrave","A spherical dome resting on four squinches","A subterranean stone foundation"]'::jsonb, 'A cantilever projects outward into space anchored only at one end (e.g., Frank Lloyd Wright''s Fallingwater balconies), defying gravity through internal tensile reinforcement.'),
  ('ap-topic-3dart-sculpture_q19', 'ap-topic-3dart-sculpture', 19, false, 'A', 'Form, Space & Materials', 'hard', 'How do "ready-mades" (conceptualized by Marcel Duchamp with *Fountain*, 1917) challenge traditional sculptural definitions?', '["By asserting that an artist''s conceptual choice and recontextualization of an ordinary manufactured object constitutes art, rather than hand-crafted artisanal carving or modeling","By demanding that all sculptures be carved from Italian Carrara marble","By proving that art can only be evaluated by physical monetary weight","By requiring that all artworks be signed with a pseudonymous pseudonym"]'::jsonb, 'Duchamp''s ready-mades separated art from craft: by selecting an everyday manufactured urinal, rotating it, and placing it in an exhibition, he argued that the artist''s intellectual idea is the essence of art.'),
  ('ap-topic-3dart-sculpture_q20', 'ap-topic-3dart-sculpture', 20, false, 'A', 'Form, Space & Materials', 'medium', 'In the AP 3-D Art and Design portfolio, how should an artist document a three-dimensional sculpture for evaluation?', '["By submitting multiple digital photographic views showing the work from different angles, a detail shot showing surface texture/process, and an optional reference scale view","By mailing the physical bronze sculpture directly to the College Board testing center","By submitting a single low-resolution black-and-white flat photograph","By describing the artwork in a written essay without any visual images"]'::jsonb, 'Because 3D works occupy physical space, the AP portfolio requires multiple photographic angles and detail shots to demonstrate volume, material execution, and spatial activation.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-drawing-mark_q1', 'ap-topic-drawing-mark', 1, false, 'A', 'Drawing', 'easy', 'Using fine parallel lines drawn close together to create value and shading is called:', '["Hatching","Stippling","Blending","Sfumato"]'::jsonb, 'Hatching uses parallel lines to build tonal value.'),
  ('ap-topic-drawing-mark_q2', 'ap-topic-drawing-mark', 2, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is the primary objective of "blind contour drawing" in observational drawing training?', '["To forge intense hand-eye coordination by closely observing the subject''s contours without ever looking down at the drawing surface","To draw rapid imagined fantasy creatures with eyes closed","To practice shading smooth dark charcoal gradations","To create photorealistic architectural blueprints"]'::jsonb, 'Blind contour drawing forces the draftsman to bypass cognitive assumptions by tracking physical contours with the eyes while the pencil mirrors the ocular path without glancing at the paper.'),
  ('ap-topic-drawing-mark_q3', 'ap-topic-drawing-mark', 3, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'How do "cross-contour lines" describe the three-dimensional form of an object on a flat sheet of paper?', '["By curving across the interior surface of the form like latitude lines on a globe, communicating volume, depth, and topographical curvature","By drawing only the flat outer silhouette edges of the subject","By creating high-contrast black borders around all shapes","By drawing straight horizontal lines across the entire background"]'::jsonb, 'Cross-contour lines travel across the body of a form (like wire contour cages), mapping surface topography and curvature into believable three-dimensional volume.'),
  ('ap-topic-drawing-mark_q4', 'ap-topic-drawing-mark', 4, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What shading technique builds tonal value and gradient density using clusters of closely spaced, non-crossing parallel lines?', '["Hatching","Cross-hatching","Stippling","Scumbling"]'::jsonb, 'Hatching uses parallel linear strokes. Modulating the proximity, thickness, and pressure of the parallel lines creates lighter or darker tonal values.'),
  ('ap-topic-drawing-mark_q5', 'ap-topic-drawing-mark', 5, false, 'A', 'Mark-Making & Line Mechanics', 'hard', 'In academic tonal rendering (chiaroscuro) of a sphere illuminated by a single directional light source, what is "reflected light"?', '["Light bouncing from the tabletop or surrounding environment back into the shadow side of the sphere, nestled between the core shadow and cast shadow","The brightest pinpoint glare where light strikes directly perpendicular to the sphere","The dark shadow cast directly onto the supporting tabletop","The ambient light in the room that eliminates all shadows"]'::jsonb, 'A fully modeled sphere displays five distinct zones: highlight, midtone (halftone), core shadow (crest of the form shadow), reflected light (ambient bounce light softening the shadow edge), and cast shadow.'),
  ('ap-topic-drawing-mark_q6', 'ap-topic-drawing-mark', 6, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'How does graphite pencil grading scale from 9H to 9B?', '["H pencils contain more clay binder, producing hard, light, precise lines; B pencils contain more graphite, producing soft, dark, smudgeable lines; HB is balanced medium","H pencils are dark black; B pencils are light gray","B pencils are made of charcoal; H pencils are made of wax","Higher numbers on H pencils mean darker and softer marks"]'::jsonb, 'The grading scale reflects lead composition: "H" (Hardness) creates pale, crisp marks; "B" (Blackness) contains softer graphite for deep velvety shadows; HB sits at center.'),
  ('ap-topic-drawing-mark_q7', 'ap-topic-drawing-mark', 7, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is the primary function of "gesture drawing" in life drawing from a live model?', '["To quickly capture the essential rhythm, posture, weight distribution, and energy of the pose in 30 to 60 seconds using fluid expressive marks","To meticulously render every individual hair follicle and fingernail","To measure facial proportions using mechanical calipers","To produce a finished exhibition-ready portrait in charcoal"]'::jsonb, 'Gesture drawing uses rapid, loose, sweeping strokes to record the dynamic essence, axis lines, and movement of a human form before embarking on detailed anatomical rendering.'),
  ('ap-topic-drawing-mark_q8', 'ap-topic-drawing-mark', 8, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What mark-making method constructs tonal value and texture through the controlled application of thousands of individual dots?', '["Stippling","Cross-hatching","Sgraffito","Burnishing"]'::jsonb, 'Stippling (common in pen-and-ink drawing) builds smooth value transitions by varying the physical density and spacing of individual ink dots.'),
  ('ap-topic-drawing-mark_q9', 'ap-topic-drawing-mark', 9, false, 'A', 'Mark-Making & Line Mechanics', 'hard', 'In atmospheric (aerial) perspective, how does an artist create the illusion of deep outdoor spatial recession in a landscape drawing?', '["By reducing contrast, softening edges, rendering distant objects in lighter values with cooler tones, and decreasing detail in the background","By drawing distant mountains with thicker, darker black outlines than foreground rocks","By making distant trees twice as tall as foreground trees","By eliminating all horizon lines from the composition"]'::jsonb, 'Atmospheric particles scatter light over distance. Artists simulate this by making foreground elements sharp, dark, and detailed, while distant mountains fade into pale, low-contrast, cool hazes.'),
  ('ap-topic-drawing-mark_q10', 'ap-topic-drawing-mark', 10, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is "line weight" (line quality) and how does varying it enhance a drawing?', '["The thickness, darkness, or lightness of a drawn mark; varying it suggests volume, shadows, mass, and brings foreground edges forward","The physical weight of the paper measured in pounds (e.g., 140 lb paper)","The amount of pressure required to break the pencil lead","The number of lines drawn per square inch"]'::jsonb, 'Dynamic line weight uses delicate, thin lines where light hits a form, and thick, heavy lines on the underside of forms or in foreground contours to convey weight, depth, and shadow.'),
  ('ap-topic-drawing-mark_q11', 'ap-topic-drawing-mark', 11, false, 'A', 'Mark-Making & Line Mechanics', 'hard', 'What distinguishes vine (willow) charcoal from compressed charcoal?', '["Vine charcoal is lightweight, powdery, easily erased or wiped away with a cloth, and produces soft grays; compressed charcoal uses a binder, creating intense velvety blacks that are difficult to erase","Vine charcoal is waterproof; compressed charcoal is water-soluble","Vine charcoal cannot be smudged; compressed charcoal can only be drawn on glass","Compressed charcoal is made without burning wood"]'::jsonb, 'Vine charcoal (burnt willow twigs) contains no binder, making it ideal for preliminary structural layouts and soft wipes. Compressed charcoal incorporates carbon black and binders, yielding permanent, intense darks.'),
  ('ap-topic-drawing-mark_q12', 'ap-topic-drawing-mark', 12, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'In two-point linear perspective, where do all sets of horizontal parallel lines receding away from the viewer converge?', '["At two separate vanishing points situated along the horizontal eye-level line (horizon line)","At a single vanishing point located in the exact center of the page","At a vertical vanishing point located in the sky","They remain parallel and never converge"]'::jsonb, 'Two-point perspective represents objects viewed at an angle (corner-on). Vertical lines remain perpendicular, while the two sets of receding horizontal edges converge toward left and right vanishing points on the horizon.'),
  ('ap-topic-drawing-mark_q13', 'ap-topic-drawing-mark', 13, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is a "reductive" (subtractive) drawing technique using charcoal or graphite?', '["Covering the paper entirely with an even tone of charcoal or graphite first, and then drawing by erasing into the tone to pull out highlights and light forms","Drawing with white chalk on black construction paper","Using digital software to decrease canvas resolution","Trimming the margins of a finished drawing with a blade"]'::jsonb, 'In reductive drawing, the artist lays down an initial ground of dark value and uses kneaded erasers, plastic erasers, or chamois cloths to sculpt out lights, highlights, and midtones.'),
  ('ap-topic-drawing-mark_q14', 'ap-topic-drawing-mark', 14, false, 'A', 'Mark-Making & Line Mechanics', 'hard', 'How does the "core shadow" differ from the "cast shadow" on a three-dimensional drawn form?', '["The core shadow is the darkest band of tone lying directly on the physical object where the form turns away from the light source; the cast shadow is the dark silhouette the object projects onto an adjacent surface","The core shadow falls on the floor; the cast shadow is on the ceiling","The core shadow is white; the cast shadow is black","They are identical terms for ambient room light"]'::jsonb, 'The core shadow is an intrinsic part of the form shadow where light rays can no longer graze the curvature. The cast shadow is the extrinsic obstruction shadow falling onto a neighboring surface, featuring a crisp umbra edge near the contact point.'),
  ('ap-topic-drawing-mark_q15', 'ap-topic-drawing-mark', 15, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is "scumbling" in mark-making and drawing?', '["A dry, circular, scribbled mark-making technique where loose, layered circular motions build soft, diffused textural value","Carving lines into wet paint with a wooden palette knife","Spattering wet ink across the page with a toothbrush","Drawing straight mechanical lines using a T-square"]'::jsonb, 'Scumbling employs small, circular, erratic pencil or pastel strokes layered over one another to produce irregular, velvety tonal surfaces with subtle underlayer reveal.'),
  ('ap-topic-drawing-mark_q16', 'ap-topic-drawing-mark', 16, false, 'A', 'Mark-Making & Line Mechanics', 'hard', 'What is the function of "sighting" (using a pencil held at arm''s length) in observational drawing?', '["To measure relative proportions, angles of tilt, and comparative unit lengths between subjects to ensure accurate observational scale and alignment","To shade distant shadows without touching the paper","To sharpen the point of a soft lead pencil","To test paper thickness before drawing"]'::jsonb, 'Comparative sighting uses a pencil held with a locked elbow and one eye closed as a sighting stick, using the thumb to measure relative proportion ratios and check angular alignments against the horizontal/vertical.'),
  ('ap-topic-drawing-mark_q17', 'ap-topic-drawing-mark', 17, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is an "ink wash"?', '["Diluting black drawing ink with varied amounts of water and applying it with a brush to create translucent gradations of gray tone","Washing paper in soapy water to remove graphite smudges","Drawing strictly with waterproof technical rollerball pens","Spraying solvent over oil pastels"]'::jsonb, 'An ink wash uses sumi or India ink thinned with water to paint luminous washes ranging from pale translucent tones to opaque blacks, bridging drawing and watercolor painting.'),
  ('ap-topic-drawing-mark_q18', 'ap-topic-drawing-mark', 18, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What is "tooth" in drawing paper substrates?', '["The surface roughness or grain texture of the paper that grabs and holds dry media particles (like charcoal and pastel)","The thickness of cardboard packaging","The serrated edge created by spiral-bound sketchbooks","A chemical sizing agent preventing water absorption"]'::jsonb, 'Paper "tooth" refers to the microscopic physical texture of the paper fibers. A rough tooth holds many layers of chalk or pastel, while a smooth plate finish (like Bristol board) suits fine pen work.'),
  ('ap-topic-drawing-mark_q19', 'ap-topic-drawing-mark', 19, false, 'A', 'Mark-Making & Line Mechanics', 'hard', 'What is "cross-hatching" and how does varying the crossing angles impact the resulting tonal surface?', '["Layering sets of intersecting parallel strokes at opposing angles; closer spacing and multiple intersecting layers create denser, darker values with dimensional modeling","Erasing crossed marks to produce pure white paper","Drawing overlapping circles with colored pencils","Applying gouache over watercolor washes"]'::jsonb, 'Cross-hatching builds tonal richness through intersecting arrays of parallel lines. Crossing lines at subtle angles (rather than rigid $90^\circ$ perpendiculars) produces smooth atmospheric gradations and follows surface curvature.'),
  ('ap-topic-drawing-mark_q20', 'ap-topic-drawing-mark', 20, false, 'A', 'Mark-Making & Line Mechanics', 'medium', 'What distinguishes the AP Drawing portfolio from the AP 2-D Art and Design portfolio?', '["AP Drawing focuses specifically on mark-making, line quality, surface manipulation, and the illusion of depth/rendering, whereas AP 2-D emphasizes compositional design principles, typography, and layout","AP Drawing only allows black graphite pencils; AP 2-D allows color","AP Drawing requires 3D clay sculptures to be photographed","There is no distinction; both portfolios have identical grading rubrics and criteria"]'::jsonb, 'AP Drawing evaluates mark-making craftsmanship, mark intentionality, rendering of light/form, and expressive mark mechanics, whereas AP 2-D focuses on broader graphic design, composition, framing, and visual design principles.'),
  ('ap-topic-spanish-vocab_q1', 'ap-topic-spanish-vocab', 1, false, 'B', 'Spanish', 'easy', 'Which tense is used to express habitual past actions in Spanish?', '["Preterite","Imperfect","Future","Conditional"]'::jsonb, 'The imperfect tense expresses repeated or ongoing past actions.'),
  ('ap-topic-spanish-vocab_q2', 'ap-topic-spanish-vocab', 2, false, 'A', 'ap-topic-spanlang-vocab', 'medium', 'En el contexto de un artículo sobre la sostenibilidad urbana en América Latina, ¿qué significado tiene la palabra ''paulatinamente'' en la frase: ''La adopción de fuentes renovables ha crecido paulatinamente en la última década''?', '["De manera gradual y progresiva con el tiempo","De forma súbita e inesperada","Con gran resistencia y dificultad política","Únicamente en ciertas regiones metropolitanas"]'::jsonb, '''Paulatinamente'' significa de manera lenta, gradual y continua a lo largo del tiempo.'),
  ('ap-topic-spanish-vocab_q3', 'ap-topic-spanish-vocab', 3, false, 'B', 'ap-topic-spanlang-formal', 'medium', '¿Cuál de las siguientes opciones expresa una recomendación formal apropiada en un correo electrónico dirigido al director de una ONG ambiental?', '["Oye, creo que deberías probar el programa nuevo en el pueblo.","Le sugiero encarecidamente que considere implementar el programa piloto en nuestra comunidad.","Hazme el favor de meter el proyecto aquí si tienes tiempo.","Te digo que pongas el plan verde de una vez por todas."]'::jsonb, 'El registro formal epistolar en español requiere el uso del pronombre ''usted'' (o ''le''), fórmulas corteses de cortesía y el modo subjuntivo tras verbos de recomendación (''Le sugiero... que considere'').'),
  ('ap-topic-spanish-vocab_q4', 'ap-topic-spanish-vocab', 4, false, 'C', 'ap-topic-spanlang-grammar', 'hard', 'Identifique la oración en la que se utiliza correctamente el subjuntivo para expresar duda o incertidumbre:', '["Es evidente que todos los ciudadanos comprendan la importancia del reciclaje.","Pienso que la energía solar sea la única alternativa viable a corto plazo.","Dudo que el gobierno destine fondos suficientes para la conservación del humedal este año.","No hay duda de que los niveles de contaminación disminuyan significativamente."]'::jsonb, 'El verbo de duda ''Dudar que'' rige obligatoriamente subjuntivo (''destine''), mientras que expresiones de certeza como ''es evidente que'', ''pienso que'' o ''no hay duda de que'' rigen indicativo en oraciones afirmativas.'),
  ('ap-topic-spanish-vocab_q5', 'ap-topic-spanish-vocab', 5, false, 'D', 'ap-topic-spanlang-discourse', 'medium', 'En un ensayo argumentativo formal en español, ¿cuál de los siguientes conectores lógicos es el más idóneo para introducir un contraargumento?', '["Por consiguiente y como consecuencia directa,","Asimismo cabe agregar que,","En primer lugar para comenzar la exposición,","No obstante las ventajas citadas anteriormente,"]'::jsonb, '''No obstante'' es una locución conjuntiva adversativa formal equivalente a ''a pesar de'' o ''sin embargo'', ideal para matizar o contrastar argumentos.'),
  ('ap-topic-spanish-vocab_q6', 'ap-topic-spanish-vocab', 6, false, 'A', 'ap-topic-spanlang-grammar', 'medium', '¿Qué matiz semántico aporta el uso del pretérito imperfecto frente al pretérito indefinido en: ''Cuando vivía en Bogotá, visitaba el Museo del Oro con frecuencia''?', '["Describe una acción habitual y repetitiva en el pasado sin delimitar un fin concreto.","Indica un evento puntual que interrumpió una acción en desarrollo.","Expresa una acción completada inmediatamente antes de otro evento pasado.","Señala una hipótesis o condición irreal en el pasado."]'::jsonb, 'El pretérito imperfecto (''vivía'', ''visitaba'') se emplea para expresar hábitos, rutinas o estados de duración indefinida en el pasado.'),
  ('ap-topic-spanish-vocab_q7', 'ap-topic-spanish-vocab', 7, false, 'B', 'ap-topic-spanlang-vocab', 'easy', 'En una entrevista radial sobre microcréditos rurales, el entrevistado afirma: ''El proyecto no solo empoderó a las mujeres artesanas, sino que dinamizó la economía comarcal''. ¿Qué significa ''dinamizó''?', '["Sustituyó por completo las fuentes tradicionales de empleo","Activó y aceleró el desarrollo económico de la zona","Causó una grave inflación en los precios de los productos","Limitó el comercio exclusivamente al ámbito doméstico"]'::jsonb, '''Dinamizar'' significa infundir vigor, actividad y movimiento a un proceso o sector económico.'),
  ('ap-topic-spanish-vocab_q8', 'ap-topic-spanish-vocab', 8, false, 'C', 'ap-topic-spanlang-register', 'easy', 'Al redactar una solicitud formal de beca universitaria, ¿cuál es la fórmula de despedida más protocolaria y congruente?', '["Bueno, me avisas cualquier cosa pronto, un abrazo,","Hasta luego y espero que me des la oportunidad,","Agradeciendo de antemano su atención, le saluda atentamente,","Saludos cordiales a todos por allá en la oficina,"]'::jsonb, '''Agradeciendo de antemano su atención, le saluda atentamente'' es una fórmula estándar de cortesía formal en el cierre de cartas y correspondencia académica institucional.'),
  ('ap-topic-spanish-vocab_q9', 'ap-topic-spanish-vocab', 9, false, 'D', 'ap-topic-spanlang-vocab', 'medium', 'En el fragmento: ''El informe recalca la necesidad de mitigar los estragos de la sequía'', ¿cuál es el antónimo contextual de ''mitigar''?', '["Atenuar","Moderar","Paliar","Agravar"]'::jsonb, '''Mitigar'' significa disminuir, suavizar o atenuar. Su antónimo directo es ''agravar'' o ''intensificar''.'),
  ('ap-topic-spanish-vocab_q10', 'ap-topic-spanish-vocab', 10, false, 'A', 'ap-topic-spanlang-grammar', 'hard', '¿Cuál es la función sintáctica del pronombre ''se'' en la frase: ''Se construyeron nuevas ciclovías para fomentar el transporte ecológico''?', '["Signo de pasiva refleja","Pronombre reflexivo directo","Pronombre recíproco","Variante de ''le'' ante pronombre de objeto directo"]'::jsonb, 'En ''Se construyeron nuevas ciclovías'', ''se'' funciona como marca de pasiva refleja, concordando el verbo en plural con el sujeto paciente (''nuevas ciclovías'').'),
  ('ap-topic-spanish-vocab_q11', 'ap-topic-spanish-vocab', 11, false, 'B', 'ap-topic-spanlang-idioms', 'medium', 'En una conversación sobre las celebraciones tradicionales en Oaxaca, un participante comenta: ''La Guelaguetza pone de manifiesto la solidaridad comunitaria''. ¿Qué significa ''poner de manifiesto''?', '["Ocultar intencionalmente","Evidenciar y mostrar con claridad","Cuestionar la autenticidad","Restringir la participación popular"]'::jsonb, 'La locución verbal ''poner de manifiesto'' denota hacer patente, exhibir o evidenciar una cualidad o realidad.'),
  ('ap-topic-spanish-vocab_q12', 'ap-topic-spanish-vocab', 12, false, 'C', 'ap-topic-spanlang-grammar', 'hard', 'Seleccione la opción que contiene una concordancia gramatical correcta en español:', '["La problema principal de la comunidad fue resuelto rápidamente.","Habían muchas personas esperando la apertura del centro de salud.","El agua clara que brotaba del manantial estaba muy fresca.","Hubieron varias complicaciones durante la conferencia magistral."]'::jsonb, '''Agua'' es sustantivo femenino que toma el artículo ''el'' en singular por comenzar con ''a'' tónica, pero los adjetivos concuerdan en femenino (''clara'', ''fresca''). Las formas impersonales del verbo haber en pasado son ''había'' y ''hubo'' (invariables en singular).'),
  ('ap-topic-spanish-vocab_q13', 'ap-topic-spanish-vocab', 13, false, 'D', 'ap-topic-spanlang-vocab', 'medium', 'En un debate sobre inteligencia artificial, un experto señala: ''Es menester establecer marcos regulatorios éticos antes de su despliegue masivo''. ''Es menester'' es equivalente a:', '["Es secundario o prescindible","Es poco probable que ocurra","Es contraproducente e innecesario","Es necesario y obligatorio"]'::jsonb, '''Es menester'' es una expresión culta que significa ''es indispensable'', ''es preciso'' o ''hace falta''.'),
  ('ap-topic-spanish-vocab_q14', 'ap-topic-spanish-vocab', 14, false, 'A', 'ap-topic-spanlang-devices', 'easy', '¿Qué figura retórica se aprecia en la expresión: ''La selva amazónica es el pulmón del planeta''?', '["Metáfora","Hipérbole","Sinestesia","Onomatopeya"]'::jsonb, 'Identifica directamente la selva con un órgano vital purificador de aire sin emplear nexos comparativos explícitos (''como''), constituyendo una metáfora.'),
  ('ap-topic-spanish-vocab_q15', 'ap-topic-spanish-vocab', 15, false, 'B', 'ap-topic-spanlang-culture', 'easy', 'En un texto sobre ecoturismo en Costa Rica, ¿cuál de las siguientes afirmaciones ilustra mejor el concepto de ''conservación comunitaria''?', '["Grandes corporaciones hoteleras extranjeras acaparan las tierras protegidas.","Los pobladores locales gestionan las reservas naturales y reinvierten los beneficios en infraestructura comunitaria.","Se prohíbe de forma absoluta cualquier tipo de ingreso humano a los parques nacionales.","El gobierno central vende las concesiones forestales a industrias madereras."]'::jsonb, 'La conservación comunitaria implica el protagonismo activo y beneficio de los habitantes locales en la preservación de su entorno biogeográfico.'),
  ('ap-topic-spanish-vocab_q16', 'ap-topic-spanish-vocab', 16, false, 'C', 'ap-topic-spanlang-grammar', 'medium', 'Identifique la oración con el uso correcto de las preposiciones ''por'' y ''para'':', '["Estudió toda la noche para aprobar el examen y salió temprano por la lluvia.","Hizo el informe por su jefe para que lo entregara por la mañana.","Viajó por España para estudiar y compró el libro por diez dólares para su hermano.","Caminó para el parque por ver las flores exóticas."]'::jsonb, '''Por España'' indica tránsito/ámbito, ''para estudiar'' finalidad, ''por diez dólares'' precio/intercambio, y ''para su hermano'' destinatario; todos los usos son normativamente correctos.'),
  ('ap-topic-spanish-vocab_q17', 'ap-topic-spanish-vocab', 17, false, 'D', 'ap-topic-spanlang-data', 'easy', 'Al analizar un gráfico sobre tasas de alfabetización juvenil, ¿qué expresión sintetiza con mayor precisión una tendencia al alza constante?', '["Los valores fluctuaron drásticamente sin exhibir un rumbo definido.","La gráfica muestra un estancamiento prolongado con declive terminal.","Los indicadores alcanzaron un mínimo histórico sin perspectivas de cambio.","Se observa un incremento sostenido a lo largo de las tres últimas décadas."]'::jsonb, '''Incremento sostenido'' es el término técnico formal exacto para denotar un crecimiento constante y continuado en análisis de datos sociodemográficos.'),
  ('ap-topic-spanish-vocab_q18', 'ap-topic-spanish-vocab', 18, false, 'A', 'ap-topic-spanlang-culture', 'medium', 'En el contexto de la literatura hispanoamericana, el término ''cosmovisión'' se refiere principalmente a:', '["La concepción integral del mundo y de la existencia propia de una cultura o época.","La técnica poética de combinar rimas asonantes y consonantes en una estrofa.","El estilo arquitectónico colonial importado de Europa en el siglo XVI.","La crítica filológica de manuscritos medievales."]'::jsonb, '''Cosmovisión'' (Weltanschauung) alude a la manera particular en que una comunidad o grupo cultural percibe, interpreta y se relaciona con el cosmos y la realidad.'),
  ('ap-topic-spanish-vocab_q19', 'ap-topic-spanish-vocab', 19, false, 'B', 'ap-topic-spanlang-grammar', 'hard', '¿Cuál es el valor aspectual de la perífrasis verbal ''llevar + gerundio'' en: ''Los científicos llevan investigando esa mutación genética cinco años''?', '["Expresa una acción terminada de forma repentina.","Indica la continuidad de una acción iniciada en el pasado que perdura en el presente.","Señala la inminencia o proximidad de un suceso futuro.","Denota la repetición obligatoria de un mandato."]'::jsonb, 'La perífrasis durativa ''llevar + gerundio'' cuantifica el lapso temporal durante el cual una acción se ha venido desarrollando desde el pasado hasta el momento del habla.'),
  ('ap-topic-spanish-vocab_q20', 'ap-topic-spanish-vocab', 20, false, 'C', 'ap-topic-spanlang-discourse', 'easy', 'En un artículo de divulgación científica, el autor concluye: ''En suma, la transición energética no es una opción, sino un imperativo categórico''. La locución ''En suma'' funciona como:', '["Introductor de una digresión temática ajena","Marcador de objeción parcial a la tesis","Conector de recapitulación o síntesis final","Elemento de ejemplificación circunstancial"]'::jsonb, '''En suma'' sintetiza y recapitula las ideas principales expuestas para arribar a una conclusión unificada.'),
  ('ap-topic-spanishlit-reading_q1', 'ap-topic-spanishlit-reading', 1, false, 'B', 'Spanish Lit', 'medium', 'Don Quijote de la Mancha was written by which famous Spanish author?', '["Gabriel García Márquez","Miguel de Cervantes","Federico García Lorca","Pablo Neruda"]'::jsonb, 'Cervantes published Don Quijote in 1605.'),
  ('ap-topic-spanishlit-reading_q2', 'ap-topic-spanishlit-reading', 2, false, 'A', 'ap-topic-spanlit-lorca', 'medium', 'En la obra teatral ''La casa de Bernarda Alba'' de Federico García Lorca, ¿qué simboliza primordialmente el bastón de Bernarda?', '["La autoridad tiránica y el poder patriarcal que ejerce sobre sus hijas","El apoyo cariñoso que brinda a su anciana madre María Josefa","La debilidad física y la decadencia de la aristocracia rural","El deseo de libertad y escape encarnado por Adela"]'::jsonb, 'El bastón de Bernarda Alba es el símbolo central de su dominio opresivo, mando indiscutible y vigilancia moral asfixiante sobre el hogar.'),
  ('ap-topic-spanishlit-reading_q3', 'ap-topic-spanishlit-reading', 3, false, 'B', 'ap-topic-spanlit-poetry', 'medium', '¿Qué tema central del Renacimiento y Barroco se manifiesta en el soneto ''En tanto que de rosa y azucena'' de Garcilaso de la Vega?', '["La crítica mordaz a la corrupción eclesiástica","El ''Carpe diem'' y la fugacidad de la juventud y la belleza terrenal","La exaltación de las gestas militares de los conquistadores","La nostalgia por el retorno a la vida pastoril eterna"]'::jsonb, 'Garcilaso exhorta a la dama a gozar de su juventud y lozanía antes de que el tiempo inexorable cubra de nieve (canas) su hermosa cabeza (''Carpe diem'' y ''Tempus fugit'').'),
  ('ap-topic-spanishlit-reading_q4', 'ap-topic-spanishlit-reading', 4, false, 'C', 'ap-topic-spanlit-picaresque', 'medium', 'En la novela picaresca ''Lazarillo de Tormes'', ¿cuál es la función principal del tratado primero con el ciego en la formación del protagonista?', '["Proporcionarle una educación religiosa devota y virtuosa","Enseñarle el oficio de escudero y las normas de caballería","Despertar a Lázaro de su inocencia infantil y enseñarle a sobrevivir en un mundo hostil mediante el engaño","Otorgarle estabilidad económica y honor ante la sociedad toledana"]'::jsonb, 'El ciego es el maestro iniciático de Lázaro; tras el golpe contra el toro de piedra, Lázaro despierta de su ingenuidad (''que un mozo del ciego un punto ha de saber más que el diablo'').'),
  ('ap-topic-spanishlit-reading_q5', 'ap-topic-spanishlit-reading', 5, false, 'D', 'ap-topic-spanlit-baroque', 'medium', '¿Qué recurso estilístico caracteriza de manera sobresaliente el monólogo de Segismundo en ''La vida es sueño'' de Calderón de la Barca (''¿Qué es la vida? Un frenesí...'')?', '["La sátira grotesca y la parodia caballeresca","El verso libre sin metro ni rima definida","La descripción costumbrista de las tabernas de Polonia","El cuestionamiento existencial y la antítesis entre ilusión y realidad"]'::jsonb, 'Calderón expone la doctrina barroca del desengaño mediante agudas antítesis y reflexiones metafísicas sobre la naturaleza ilusoria de la existencia terrenal.'),
  ('ap-topic-spanishlit-reading_q6', 'ap-topic-spanishlit-reading', 6, false, 'A', 'ap-topic-spanlit-modernism', 'hard', 'En el poema ''A Roosevelt'' de Rubén Darío, ¿qué contraste fundamental establece el poeta nicaragüense?', '["La potencia material y militarista de EE.UU. frente a la herencia espiritual, poética y católica de la América hispana","La riqueza de las metrópolis europeas frente al atraso agrario latinoamericano","La naturaleza pacífica de los líderes políticos frente a la agresividad de los poetas","El desarrollo de la industria del carbón frente a la agricultura tradicional"]'::jsonb, 'Darío enfrenta el imperialismo expansivo de Theodore Roosevelt contra la dignidad cultural, histórica y espiritual de la ''América ingenua que tiene sangre indígena y reza a Jesucristo''.'),
  ('ap-topic-spanishlit-reading_q7', 'ap-topic-spanishlit-reading', 7, false, 'B', 'ap-topic-spanlit-borges', 'medium', 'En el relato ''Borges y yo'' de Jorge Luis Borges, ¿cuál es el eje temático principal?', '["La descripción autobiográfica de los viajes de juventud por Europa","La dualidad del ser y la tensión irreconciliable entre la persona íntima y la figura pública o literaria","El repudio ideológico a las vanguardias literarias del siglo XX","La investigación policial de un crimen en un laberinto bonaerense"]'::jsonb, 'El microrrelato explora la escisión ontológica entre el ''yo'' íntimo que prefiere los mapas y el café y el ''otro'' Borges, el escritor consumido por la celebridad y la posteridad.'),
  ('ap-topic-spanishlit-reading_q8', 'ap-topic-spanishlit-reading', 8, false, 'C', 'ap-topic-spanlit-boom', 'medium', '¿Qué elemento del realismo mágico se manifiesta de manera patente en ''El ahogado más hermoso del mundo'' de Gabriel García Márquez?', '["La explicación científica y forense de las mareas atlánticas","La denuncia documental de abusos laborales en una bananera","La transformación colectiva y embellecimiento mítico de un pueblo pesquero desolado a partir de la llegada de un cadáver colosal","El conflicto bélico fratricida entre conservadores y liberales"]'::jsonb, 'Esteban, el ahogado monumental, transfigura la imaginación, la estética y la solidaridad del árido pueblo caribeño, fundiendo lo milagroso con la cotidianeidad sin asombro de los lugareños.'),
  ('ap-topic-spanishlit-reading_q9', 'ap-topic-spanishlit-reading', 9, false, 'D', 'ap-topic-spanlit-romancero', 'easy', 'En el romance fronterizo ''Romance de la pérdida de Alhama'' (''¡Ay de mi Alhama!''), el estribillo cumple la función de:', '["Celebrar con júbilo la victoria militar cristiana","Presentar datos cuantitativos sobre las tropas contendientes","Introducir una reflexión humorística que distiende la tensión bélica","Intensificar el tono elegíaco y subrayar el lamento colectivo ante la caída inminente del reino nazarí"]'::jsonb, 'El estribillo ''¡Ay de mi Alhama!'' condensa el dolor desgarrador y el presagio fatal de la pérdida definitiva de Granada para los musulmanes andalusíes.'),
  ('ap-topic-spanishlit-reading_q10', 'ap-topic-spanishlit-reading', 10, false, 'A', 'ap-topic-spanlit-unamuno', 'hard', 'En ''San Manuel Bueno, mártir'' de Miguel de Unamuno, ¿cuál es el secreto trágico que atormenta al sacerdote Don Manuel?', '["No cree en la inmortalidad del alma ni en la vida eterna, pero finge creer para mantener la paz espiritual de sus feligreses","Haber cometido un asesinato en su juventud que oculta a la justicia","Estar enamorado en secreto de Ángela Carballino","Poseer riquezas mal habidas heredadas del extranjero"]'::jsonb, 'Don Manuel encarna la tragedia existencial unamuniana: carece de fe en la resurrección terrena, pero se inmola a diario pastoreando la devoción del pueblo para evitarles la angustia del vacío existencial.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-spanishlit-reading_q11', 'ap-topic-spanishlit-reading', 11, false, 'B', 'ap-topic-spanlit-meter', 'hard', '¿Cuál es la estructura métrica clásica de la silva empleada por sor Juana Inés de la Cruz y fray Luis de León?', '["Catorce versos endecasílabos distribuidos en dos cuartetos y dos tercetos","Combinación libre de versos endecasílabos (11) y heptasílabos (7) con rima consonante a gusto del poeta","Ocho versos octosílabos con rima asonante en los pares","Cuatro versos alejandrinos monorrimos con cesura central"]'::jsonb, 'La silva es una estrofa renacentista/barroca italiana compuesta por versos libres o rimados de 7 y 11 sílabas métricas combinados a criterio del autor.'),
  ('ap-topic-spanishlit-reading_q12', 'ap-topic-spanishlit-reading', 12, false, 'C', 'ap-topic-spanlit-sorjuana', 'medium', 'En el poema ''Hombres necios que acusáis'' de Sor Juana Inés de la Cruz, la poetisa denuncia:', '["La pérdida de las posesiones coloniales españolas en Ultramar","La ignorancia de los poetas de su tiempo respecto a las matemáticas","La doble moral y la hipocresía patriarcal de los hombres que culpan a las mujeres de los mismos vicios que ellos incitan","La falta de piedad religiosa en los monasterios novohispanos"]'::jsonb, 'Sor Juana desmonta la injusticia de género argumentando que los varones seducen a las damas y luego desprecian moralmente su ''caída'' (''¿cuál mayor culpa ha tenido... la que peca por la paga o el que paga por pecar?'').'),
  ('ap-topic-spanishlit-reading_q13', 'ap-topic-spanishlit-reading', 13, false, 'D', 'ap-topic-spanlit-fuentes', 'medium', 'En ''Chac Mool'' de Carlos Fuentes, ¿qué conflicto central articula la trama fantástica?', '["El descubrimiento arqueológico de una tumba maya intacta en Yucatán","La huida clandestina de un guerrillero zapatista hacia Acapulco","La especulación inmobiliaria en la Ciudad de México durante los años 50","La reactivación de un dios prehispánico de la lluvia que invade y devora la vida cotidiana y la identidad moderna de Filiberto"]'::jsonb, 'Fuentes recrea el choque entre el pasado indígena mítico (el Chac Mool viviente) y la burocracia mexicanista contemporánea, culminando con la suplantación de Filiberto.'),
  ('ap-topic-spanishlit-reading_q14', 'ap-topic-spanishlit-reading', 14, false, 'A', 'ap-topic-spanlit-theater', 'easy', 'En ''El burlador de Sevilla y convidado de piedra'' atribuida a Tirso de Molina, ¿cuál es la célebre frase con la que Don Juan pospone su arrepentimiento moral?', '["''¡Tan largo me lo fiais!''","''¡Poderoso caballero es don Dinero!''","''¡Vivir para ver, morir para saber!''","''¡A Dios pongo por testigo que venceré!''"]'::jsonb, 'Don Juan desprecia los avisos de condena eterna creyendo que la muerte está lejana con su reiterado ''¡Tan largo me lo fiais!'', hasta que Don Gonzalo lo condena sin prórroga.'),
  ('ap-topic-spanishlit-reading_q15', 'ap-topic-spanishlit-reading', 15, false, 'B', 'ap-topic-spanlit-naturalism', 'medium', '¿Qué visión del mundo campesino gallego plasma Emilia Pardo Bazán en su cuento naturalista ''Las medias rojas''?', '["Una visión idílica y bucólica de la armonía rural campesina","Un determinismo social implacable y una violencia patriarcal brutal que cercena los sueños de emancipación de Ildara","Un elogio al progreso industrial que lleva riqueza al campo","Un manifiesto comunista en favor de la reforma agraria revolucionaria"]'::jsonb, 'Pardo Bazán ilustra los postulados naturalistas al mostrar cómo la brutal paliza del tío Clodio desfigura a Ildara, destruyendo su única vía de escape (emigrar a América) por ser mujer y campesina desamparada.'),
  ('ap-topic-spanishlit-reading_q16', 'ap-topic-spanishlit-reading', 16, false, 'C', 'ap-topic-spanlit-machado', 'medium', 'En ''Soledades, II'' (''He andado muchos caminos'') de Antonio Machado, ¿cómo contrasta el poeta a las ''gentes malas'' con la ''buena gente''?', '["Los ricos hacendados urbanos frente a los clérigos asceticistas de Castilla","Los científicos positivistas frente a los artistas bohemios de Madrid","Los pedantes soberbios que miran con desdén frente a los campesinos sencillos que laboran, beben vino y descansan bajo tierra","Los soldados profesionales frente a los comerciantes de ferias"]'::jsonb, 'Machado elogia a la gente trabajadora que vive sin presunciones (''viven, laboran, pasan y sueñan'') frente a los ''mala gente que camina y va apestando la tierra''.'),
  ('ap-topic-spanishlit-reading_q17', 'ap-topic-spanishlit-reading', 17, false, 'D', 'ap-topic-spanlit-chronicles', 'hard', '¿Cuál es el propósito discursivo de Hernán Cortés en su ''Segunda carta de relación'' dirigida al emperador Carlos V?', '["Denunciar la crueldad de los conquistadores hacia los indígenas como Las Casas","Solicitar el relevo militar y el regreso inmediato a la isla de Cuba","Explicar la flora y fauna tropical desde una perspectiva exclusivamente botánica","Legitimar su expedición no autorizada y magnificar las riquezas y civilización del imperio mexica para obtener el favor real"]'::jsonb, 'Cortés redacta su carta como alegato jurídico y político para validar ante la Corona su insubordinación frente a Diego Velázquez, deslumbrando al monarca con las maravillas y tesoros de Tenochtitlan.'),
  ('ap-topic-spanishlit-reading_q18', 'ap-topic-spanishlit-reading', 18, false, 'A', 'ap-topic-spanlit-cortazar', 'medium', 'En ''La noche boca arriba'' de Julio Cortázar, ¿qué técnica narrativa genera la tensión y la sorpresa final en el lector?', '["El desdoblamiento onírico y la inversión gradual de la realidad entre el paciente accidentado y el indio moteca perseguido","La inclusión de documentos epistolares verídicos de la época azteca","El monólogo interior en flujo de conciencia de una enfermera nocturna","La narración policial lineal contada desde el punto de vista del motociclista"]'::jsonb, 'Cortázar yuxtapone el mundo moderno del hospital con la guerra florida azteca, revelando al final que la realidad primordial era la del guerrero sacrificado y el hospital era su sueño final.'),
  ('ap-topic-spanishlit-reading_q19', 'ap-topic-spanishlit-reading', 19, false, 'B', 'ap-topic-spanlit-guillen', 'medium', 'En el poema ''Balada de los dos abuelos'' de Nicolás Guillén, la reconciliación final de los dos ancestros representa:', '["El rechazo absoluto de cualquier influencia hispánica en el Caribe","La integración mestiza, armónica y fraternal de las raíces africanas y europeas en la identidad nacional cubana","La conversión forzosa de los esclavos al catolicismo ortodoxo","El triunfo militar de los cimarrones sobre las tropas coloniales"]'::jsonb, 'Guillén funde a Don Federico (abuelo blanco con gorguera) y Facundo (abuelo negro con lanza y tambor) en un abrazo de igualdad y orgullo mulato (''los dos se abrazan, cantan, lloran'').'),
  ('ap-topic-spanishlit-reading_q20', 'ap-topic-spanishlit-reading', 20, false, 'C', 'ap-topic-spanlit-dragun', 'hard', '¿Qué convención teatral rompe de manera revolucionaria Osvaldo Dragún en ''El hombre que se convirtió en perro''?', '["Usa decorados hiperrealistas con animales vivos en el proscenio","Respeta rígidamente la regla neoclásica de las tres unidades (tiempo, lugar y acción)","Emplea técnicas del teatro del absurdo y distanciamiento brechtiano para denunciar la deshumanización del trabajador en el sistema capitalista","Excluye el diálogo verbal confiando únicamente en la mímica musical de ópera"]'::jsonb, 'Dragún expone la alienación socioeconómica extrema obligando a un hombre sin empleo a aceptar el puesto de perro guardián, despojándolo de su lenguaje y dignidad humana mediante el teatro dialéctico.'),
  ('ap-topic-french-lang_q1', 'ap-topic-french-lang', 1, false, 'B', 'French', 'easy', 'Which French subjunctive trigger requires the use of the subjonctif?', '["Il est cierto que","Il faut que","Il est vrai que","Je pense que"]'::jsonb, '''Il faut que'' (necessity) requires the subjunctive mood.'),
  ('ap-topic-french-lang_q2', 'ap-topic-french-lang', 2, false, 'A', 'ap-topic-french-vocab', 'easy', 'Dans le cadre d''un article sur la transition écologique en France, quel est le sens précis de l''expression ''empreinte carbone''?', '["La quantité totale de gaz à effet de serre émise par une activité ou un individu","Le coût financier de l''installation de panneaux solaires","La surface de forêt détruite pour l''urbanisation","Le taux de particules fines mesuré dans le métro parisien"]'::jsonb, 'L''empreinte carbone mesure le volume total de gaz à effet de serre (GES), notamment le dioxyde de carbone, généré par une entité ou un processus.'),
  ('ap-topic-french-lang_q3', 'ap-topic-french-lang', 3, false, 'B', 'ap-topic-french-grammar', 'medium', 'Laquelle des phrases suivantes illustre l''emploi correct du subjonctif après une conjonction marquant le but?', '["Bien que le climat est doux, il porte un manteau épais.","Le professeur explique la règle afin que tous les étudiants comprennent la leçon.","Il étudie sérieusement parce qu''il veuille réussir son concours.","Dès que nous ayons fini de manger, nous partirons au cinéma."]'::jsonb, 'La locution conjonctive de but ''afin que'' (ou ''pour que'') exige impérativement le mode subjonctif (''comprennent'').'),
  ('ap-topic-french-lang_q4', 'ap-topic-french-lang', 4, false, 'C', 'ap-topic-french-register', 'easy', 'Dans un courriel formel adressé au doyen d''une université francophone, quelle formule de politesse est la plus appropriée pour conclure?', '["À plus tard et merci pour votre aide amicale,","Bien à vous et bonne journée,","Veuillez agréer, Monsieur le Doyen, l''expression de mes salutations distinguées.","Gros bisous et au plaisir de vous revoir bientôt,"]'::jsonb, '''Veuillez agréer... mes salutations distinguées'' est la formule consacrée du protocole épistolaire soutenu en milieu académique ou professionnel francophone.'),
  ('ap-topic-french-lang_q5', 'ap-topic-french-lang', 5, false, 'D', 'ap-topic-french-grammar', 'hard', 'Quel pronom relatif composé complète correctement la phrase: ''C''est une cause écologique ______ de nombreux bénévoles se dévouent corps et âme''?', '["auquel","pour qui","dans lequel","à laquelle"]'::jsonb, '''Se dévouer à quelque chose'' gouverne la préposition ''à''. Le nom ''cause'' étant féminin singulier, le pronom relatif composé contracté est ''à laquelle''.'),
  ('ap-topic-french-lang_q6', 'ap-topic-french-lang', 6, false, 'A', 'ap-topic-french-idioms', 'medium', 'Lors d''un débat télévisé sur le télétravail, un sociologue mentionne: ''Ce mode d''organisation renforce l''autonomie, mais gare à l''isolement!''. Que signifie l''interjection ''gare à''?', '["Attention à / prenez garde à","Soyez indifférent à","Réjouissez-vous de","Mettez fin à"]'::jsonb, '''Gare à'' est une mise en garde signifiant ''faites attention à'' ou ''prenez garde au danger de''.'),
  ('ap-topic-french-lang_q7', 'ap-topic-french-lang', 7, false, 'B', 'ap-topic-french-grammar', 'medium', 'Dans la phrase: ''Si les pouvoirs publics avaient investi plus tôt dans le ferroviaire, le réseau ______ aujourd''hui beaucoup plus efficace'', quelle est la forme verbale correcte?', '["sera","serait","ait été","avait été"]'::jsonb, 'Pour exprimer un irréel du passé avec conséquence dans le présent (conditionnel présent), la structure est: ''Si + plus-que-parfait ..., conditionnel présent'' (''serait'').'),
  ('ap-topic-french-lang_q8', 'ap-topic-french-lang', 8, false, 'C', 'ap-topic-french-culture', 'medium', 'Que désigne le concept socioculturel français de ''laïcité'' dans les institutions publiques républicaines?', '["L''obligation pour chaque citoyen d''adhérer à une religion officielle","L''interdiction totale de pratiquer un culte dans la sphère privée","La neutralité religieuse rigoureuse de l''État garantissant la liberté de conscience de tous les citoyens","La prééminence accordée aux coutumes médiévales dans le code civil"]'::jsonb, 'La laïcité républicaine implique la séparation des Églises et de l''État, la neutralité des services publics et la liberté de croire ou de ne pas croire.'),
  ('ap-topic-french-lang_q9', 'ap-topic-french-lang', 9, false, 'D', 'ap-topic-french-vocab', 'medium', 'Dans un rapport économique, que signifie le verbe ''endiguer'' dans l''énoncé: ''Les autorités monétaires tentent d''endiguer la flambée des prix''?', '["Accélérer le rythme de croissance","Ignorer délibérément un phénomène","Financer par des emprunts obligataires","Contenir, freiner ou stopper la progression"]'::jsonb, '''Endiguer'' signifie littéralement retenir par des digues, et au sens figuré, contenir ou juguler un débordement indésirable.'),
  ('ap-topic-french-lang_q10', 'ap-topic-french-lang', 10, false, 'A', 'ap-topic-french-grammar', 'medium', 'Identifiez la phrase contenant une inversion interrogative correcte en registre soutenu:', '["Pourquoi les énergies renouvelables suscitent-elles un tel engouement auprès des jeunes?","Pourquoi est-ce que les énergies renouvelables suscitent un engouement?","Pourquoi les énergies renouvelables elles suscitent un engouement?","Pourquoi que les énergies renouvelables suscitent tant d''engouement?"]'::jsonb, 'En français soutenu, l''interrogation avec un sujet lexical complexe exige la reprise du sujet par le pronom personnel correspondant inversé avec le verbe (''suscitent-elles'').'),
  ('ap-topic-french-lang_q11', 'ap-topic-french-lang', 11, false, 'B', 'ap-topic-french-culture', 'easy', 'Quel rôle joue le festival de Cannes dans le rayonnement culturel de la France?', '["C''est un concours littéraire réservé exclusivement aux romans francophones","C''est l''un des événements cinématographiques les plus prestigieux au monde, célébrant la diversité du cinéma international","C''est une foire agricole annuelle dédiée aux produits du terroir provençal","C''est une compétition sportive nautique en Méditerranée"]'::jsonb, 'Le Festival de Cannes est un sommet mondial du 7e art, promouvant le cinéma d''auteur et l''industrie cinématographique internationale.'),
  ('ap-topic-french-lang_q12', 'ap-topic-french-lang', 12, false, 'C', 'ap-topic-french-grammar', 'easy', 'Dans la phrase: ''Bien que ces technologies ______ prometteuses, leur coût de déploiement demeure prohibitif'', choisissez la forme verbale requise:', '["sont","seront","soient","seraient"]'::jsonb, 'La locution conjonctive de concession ''bien que'' exige systématiquement le subjonctif (''soient'').'),
  ('ap-topic-french-lang_q13', 'ap-topic-french-lang', 13, false, 'D', 'ap-topic-french-vocab', 'easy', 'Que signifie l''adjectif ''incontournable'' lorsqu''on décrit une exposition d''art au Musée d''Orsay?', '["Difficile d''accès physique pour les visiteurs","Interdite au jeune public sans surveillance","Controversée et rejetée par les critiques","Indispensable, qu''il faut absolument voir"]'::jsonb, '''Incontournable'' désigne un événement, un fait ou une œuvre de premier plan dont on ne peut faire l''économie.'),
  ('ap-topic-french-lang_q14', 'ap-topic-french-lang', 14, false, 'A', 'ap-topic-french-grammar', 'medium', 'Quelle nuance temporelle apporte le gérondif dans la phrase: ''En consultant les archives départementales, l''historien a découvert un manuscrit inédit''?', '["La simultanéité et la manière entre la recherche et la découverte","Une antériorité lointaine et révolue","Une hypothèse totalement invraisemblable","Une succession chronologique différée de plusieurs années"]'::jsonb, 'Le gérondif (''en consultant'') exprime la simultanéité de deux actions accomplies par le même sujet, indiquant souvent le moyen ou la circonstance temporelle.'),
  ('ap-topic-french-lang_q15', 'ap-topic-french-lang', 15, false, 'B', 'ap-topic-french-culture', 'easy', 'Dans le système éducatif français, qu''est-ce que le diplôme du ''Baccalauréat''?', '["Un diplôme universitaire de troisième cycle de recherche","L''examen national terminal sanctionnant la fin des études secondaires et ouvrant l''accès à l''enseignement supérieur","Un certificat professionnel d''apprentissage manuel","Un concours de recrutement pour les professeurs d''école"]'::jsonb, 'Le baccalauréat (ou ''bac'') est le premier grade universitaire validant la fin du lycée et permettant l''inscription en faculté ou filière supérieure.'),
  ('ap-topic-french-lang_q16', 'ap-topic-french-lang', 16, false, 'C', 'ap-topic-french-grammar', 'hard', 'Identifiez l''accord correct du participe passé avec le verbe pronominal réfléchi dans la phrase suivante:', '["Elles se sont lavées les mains avant de passer à table.","Elles se sont lavés les mains avant de passer à table.","Elles se sont lavé les mains avant de passer à table.","Elles sont se lavé les mains avant de passer à table."]'::jsonb, 'Dans ''se laver les mains'', l''objet direct (''les mains'') est placé après le verbe. Le pronom ''se'' est objet indirect (à elles-mêmes). Le participe passé reste donc invariable: ''lavé''.'),
  ('ap-topic-french-lang_q17', 'ap-topic-french-lang', 17, false, 'D', 'ap-topic-french-vocab', 'medium', 'En linguistique et culture québécoise, que désigne couramment le terme ''magasinage''?', '["Construire un entrepôt de stockage maritime","Classer des livres dans une bibliothèque","Emballer des colis postaux à domicile","Faire des achats dans les boutiques (le shopping)"]'::jsonb, 'Au Québec, ''magasiner'' et ''le magasinage'' sont les équivalents recommandés du terme anglais ''shopping''.'),
  ('ap-topic-french-lang_q18', 'ap-topic-french-lang', 18, false, 'A', 'ap-topic-french-discourse', 'easy', 'Quel connecteur logique convient le mieux pour marquer une opposition nuancée dans une argumentation écrite?', '["En revanche","En conséquence","Tout d''abord","C''est pourquoi"]'::jsonb, '''En revanche'' introduit une idée opposée ou un contrepoint valorisant par rapport à ce qui précède.'),
  ('ap-topic-french-lang_q19', 'ap-topic-french-lang', 19, false, 'B', 'ap-topic-french-idioms', 'medium', 'Dans un éditorial de presse, l''expression ''faire la part belle à'' signifie:', '["Critiquer sévèrement une initiative esthétique","Accorder une place privilégiée ou un avantage considérable à quelqu''un ou quelque chose","Répartir équitablement des parts d''héritage","Partager équitablement les tâches ménagères"]'::jsonb, '''Faire la part belle à'' est une expression idiomatique signifiant donner un traitement de faveur ou accorder une large visibilité.'),
  ('ap-topic-french-lang_q20', 'ap-topic-french-lang', 20, false, 'C', 'ap-topic-french-culture', 'medium', 'Quelle est la principale vocation de l''Organisation internationale de la Francophonie (OIF)?', '["Réguler exclusivement les tarifs douaniers sur le marché européen","Créer une monnaie unique pour l''ensemble des pays d''Afrique subsaharienne","Promouvoir la langue française, la paix, les droits de l''homme et la coopération éducative entre ses États membres","Imposer l''apprentissage du français comme langue unique au sein des Nations Unies"]'::jsonb, 'L''OIF rassemble 88 États et gouvernements voués au rayonnement du français, à la promotion de la démocratie et au dialogue des cultures.'),
  ('ap-topic-german-lang_q1', 'ap-topic-german-lang', 1, false, 'B', 'German', 'medium', 'Which German preposition always takes the dative case?', '["durch","mit","für","gegen"]'::jsonb, '''Mit'' strictly governs the dative case.'),
  ('ap-topic-german-lang_q2', 'ap-topic-german-lang', 2, false, 'A', 'ap-topic-german-culture', 'easy', 'Welche Bedeutung hat das Wort ''Energiewende'' im modernen deutschen gesellschaftlichen und politischen Diskurs?', '["Der Übergang von fossilen Brennstoffen und Kernkraft zu erneuerbaren Energien","Der sofortige Ausstieg aus jeglicher industriellen Produktion","Die vollständige Privatisierung des Stromnetzes","Die exklusive Abhängigkeit von Kohleimporten aus Übersee"]'::jsonb, 'Die ''Energiewende'' bezeichnet die tiefgreifende Umstellung der Energieversorgung in Deutschland hin zu Windkraft, Solar und anderen regenerativen Quellen.'),
  ('ap-topic-german-lang_q3', 'ap-topic-german-lang', 3, false, 'B', 'ap-topic-german-grammar', 'medium', 'Ergänzen Sie den Satz mit der grammatisch korrekten Relativpronomenform: ''Das Thema, über ______ die Experten stundenlang diskutierten, ist von zentraler Bedeutung.''', '["dem","das","dessen","den"]'::jsonb, 'Die Präposition ''über'' verlangt hier den Akkusativ (''über etwas diskutieren''). Das Bezugswort ''Thema'' ist sächlich, also ''über das''.'),
  ('ap-topic-german-lang_q4', 'ap-topic-german-lang', 4, false, 'C', 'ap-topic-german-grammar', 'medium', 'Welcher Konnektor leitet einen untergeordneten Nebensatz ein und bewirkt, dass das finite Verb an das Satzende rückt?', '["denn","jedoch","obwohl","nämlich"]'::jsonb, '''Obwohl'' ist eine subordinierende Konjunktion (Konzessivsatz), die das finite Verb ans Ende des Nebensatzes zwingt. ''Denn'' ist koordinierend (Position 0).'),
  ('ap-topic-german-lang_q5', 'ap-topic-german-lang', 5, false, 'D', 'ap-topic-german-register', 'easy', 'In einer formellen E-Mail an eine Universitätsprofessorin lautet die korrekte Anrede:', '["Hallo Frau Müller, wie geht''s?","Liebe Frau Müller,","Guten Tag Kollegin Müller,","Sehr geehrte Frau Professorin Dr. Müller,"]'::jsonb, '''Sehr geehrte Frau Professorin Dr. Müller'' ist die standardisierte, respektvolle Anrede im formellen akademischen Schriftverkehr in Deutschland.'),
  ('ap-topic-german-lang_q6', 'ap-topic-german-lang', 6, false, 'A', 'ap-topic-german-grammar', 'medium', 'Welche modale Bedeutung drückt das Verb ''sollen'' im folgenden Satz aus: ''Der neue Forschungsbericht soll nächste Woche veröffentlicht werden''?', '["Ein geplantes Vorhaben oder eine Fremdaussage/Erwartung","Eine physische Unmöglichkeit","Ein zwingendes Naturgesetz","Ein persönliches Verbot"]'::jsonb, '''Sollen'' drückt hier einen Plan, eine Ankündigung oder einen von Dritten festgelegten Zeitplan aus.'),
  ('ap-topic-german-lang_q7', 'ap-topic-german-lang', 7, false, 'B', 'ap-topic-german-culture', 'medium', 'Was versteht man in Deutschland unter dem Konzept des ''Dualen Ausbildungssystems''?', '["Ein Hochschulstudium, das zwingend zwei Hauptfächer umfasst","Die parallele Ausbildung im Betrieb mit theoretischem Unterricht an der Berufsschule","Der getrennte Schulunterricht von Mädchen und Jungen","Die Verpflichtung zur Absolvierung von Wehrdienst und Zivildienst gleichzeitig"]'::jsonb, 'Das duale System verbindet praktische Lehre in einem Unternehmen mit fundierter theoretischer Bildung an einer staatlichen Berufsschule.'),
  ('ap-topic-german-lang_q8', 'ap-topic-german-lang', 8, false, 'C', 'ap-topic-german-grammar', 'medium', 'Wählen Sie die korrekte Form des Konjunktivs II der Vergangenheit für: ''Wenn ich von dem Stau gewusst hätte, ______ ich eine andere Route gewählt.''', '["würde","hatte","hätte","habe"]'::jsonb, 'Der irreale Konditionalsatz der Vergangenheit mit dem Hilfsverb ''haben'' bildet das Prädikat mit ''hätte + Partizip II'' (''hätte ... gewählt'').'),
  ('ap-topic-german-lang_q9', 'ap-topic-german-lang', 9, false, 'D', 'ap-topic-german-vocab', 'easy', 'In einem wirtschaftlichen Artikel steht: ''Die Inflation hat den Konsum merklich gedämpft.'' Was bedeutet ''gedämpft'' in diesem Zusammenhang?', '["Gefördert und verdoppelt","Vollständig eliminiert","Unverändert gelassen","Verringert oder abgeschwächt"]'::jsonb, '''Dämpfen'' bedeutet verlangsamen, mindern oder abbremsen (etwa von Kaufkraft oder Konjunktur).'),
  ('ap-topic-german-lang_q10', 'ap-topic-german-lang', 10, false, 'A', 'ap-topic-german-grammar', 'medium', 'Welche Präposition erfordert im Deutschen immer den Genitiv?', '["während","bei","gegenüber","mit"]'::jsonb, '''Während'' gehört zu den klassischen Präpositionen, die standardgemäß den Genitiv regieren (''während des Vortrags'').'),
  ('ap-topic-german-lang_q11', 'ap-topic-german-lang', 11, false, 'B', 'ap-topic-german-idioms', 'easy', 'Was bedeutet die Redewendung ''zwei Fliegen mit einer Klappe schlagen''?', '["Sehr ungeschickt bei der Hausarbeit sein","Zwei Ziele oder Probleme mit einer einzigen Handlung gleichzeitig lösen","Einen schweren Streit in der Familie provozieren","Zwei verschiedene Berufe gleichzeitig ausüben"]'::jsonb, 'Diese geläufige Redensart drückt die doppelte Effizienz einer einzigen Maßnahme aus.'),
  ('ap-topic-german-lang_q12', 'ap-topic-german-lang', 12, false, 'C', 'ap-topic-german-culture', 'easy', 'Welches historische Ereignis wird in Deutschland am 3. Oktober als Nationalfeiertag gefeiert?', '["Der Fall der Berliner Mauer 1989","Das Ende des Zweiten Weltkriegs 1945","Der Tag der Deutschen Einheit (die Wiedervereinigung 1990)","Die Verabschiedung des Grundgesetzes 1949"]'::jsonb, 'Am 3. Oktober 1990 wurde der Beitritt der DDR zur Bundesrepublik Deutschland vollzogen; seitdem ist dies der offizielle Nationalfeiertag.'),
  ('ap-topic-german-lang_q13', 'ap-topic-german-lang', 13, false, 'D', 'ap-topic-german-grammar', 'medium', 'Welche Passivform ist grammatisch korrekt für den Satz: ''Die Ingenieure prüfen die Brücke sorgfältig''?', '["Die Brücke ist von den Ingenieuren sorgfältig geprüft worden sein.","Die Brücke wird den Ingenieuren sorgfältig prüfen.","Die Brücke hat von den Ingenieuren geprüft werden.","Die Brücke wird von den Ingenieuren sorgfältig geprüft."]'::jsonb, 'Vorgangspassiv im Präsens wird mit dem Hilfsverb ''werden'' im Präsens (''wird'') und dem Partizip II (''geprüft'') gebildet. Das Subjekt wird zur ''von + Dativ''-Angabe.'),
  ('ap-topic-german-lang_q14', 'ap-topic-german-lang', 14, false, 'A', 'ap-topic-german-culture', 'easy', 'Was beschreibt der Begriff ''Mülltrennung'' in deutschen Privathaushalten?', '["Das systematische Sortieren von Abfällen nach Wertstoffen (Papier, Glas, Biomüll, Plastik) zum Recycling","Das Verbrennen von Hausmüll im eigenen Garten","Das illegale Entsorgen von Elektroschrott im Wald","Den Export von Industriemüll in Entwicklungsländer"]'::jsonb, 'Mülltrennung ist ein fest verankerter Teil des deutschen Umweltschutzes, bei dem Abfälle nach Kategorien für die Wiederverwertung getrennt gesammelt werden.'),
  ('ap-topic-german-lang_q15', 'ap-topic-german-lang', 15, false, 'B', 'ap-topic-german-grammar', 'medium', 'Ergänzen Sie das Adjektiv mit der richtigen Endung nach dem bestimmten Artikel: ''Die neu______ Technologien bieten innovative Lösungen.''', '["e","en","er","es"]'::jsonb, 'Nach dem bestimmten Artikel im Plural (''die'') lautet die schwache Adjektivendung in allen Kasus ''-en'' (''die neuen Technologien'').'),
  ('ap-topic-german-lang_q16', 'ap-topic-german-lang', 16, false, 'C', 'ap-topic-german-culture', 'easy', 'Was bedeutet das Wort ''Feierabend'' in der deutschen Alltagskultur?', '["Eine offizielle Jubiläumsfeier in einem Großbetrieb","Ein gesetzlicher Ruhetag am Wochenende","Das Ende des täglichen Arbeitstages und der Beginn der Freizeit","Ein religiöser Feiertag im Frühling"]'::jsonb, '''Feierabend'' markiert den wohlverdienten Abschluss der Arbeitszeit und die anschließende persönliche Erholungszeit am Abend.'),
  ('ap-topic-german-lang_q17', 'ap-topic-german-lang', 17, false, 'D', 'ap-topic-german-grammar', 'medium', 'Im Satz: ''Er spricht, als ob er der Experte auf diesem Gebiet ______'', welche Konjunktivform ist stilistisch angemessen?', '["ist","wird sein","gewesen ist","wäre"]'::jsonb, 'Nach Vergleichssätzen mit ''als ob'' steht obligatorisch der Konjunktiv II (''wäre''), um den hypothetischen Charakter zu markieren.'),
  ('ap-topic-german-lang_q18', 'ap-topic-german-lang', 18, false, 'A', 'ap-topic-german-geography', 'easy', 'In welchem Bundesland liegt die bayerische Landeshauptstadt München?', '["Freistaat Bayern","Baden-Württemberg","Nordrhein-Westfalen","Hessen"]'::jsonb, 'München ist die Hauptstadt des süddeutschen Freistaats Bayern.'),
  ('ap-topic-german-lang_q19', 'ap-topic-german-lang', 19, false, 'B', 'ap-topic-german-particles', 'hard', 'Was drückt die Partikel ''doch'' im Satz: ''Komm doch bitte mit ins Konzert!'' aus?', '["Einen absoluten Widerspruch zu einer Lüge","Eine ermutigende, freundliche Verstärkung einer Bitte","Eine zeitliche Verzögerung","Einen Zweifel an der Realität"]'::jsonb, 'Als Modalpartikel in Aufforderungen mildert ''doch'' den Tonfall ab und verleiht der Bitte eine herzliche, ermunternde Nuance.'),
  ('ap-topic-german-lang_q20', 'ap-topic-german-lang', 20, false, 'C', 'ap-topic-german-culture', 'easy', 'Welches Ziel verfolgt das sogenannte ''Reinheitsgebot'' von 1516?', '["Ein Hygieneerlass für die städtische Trinkwasserversorgung","Ein Verbot von schädlichen Farbstoffen in Textilien","Historische Festlegung der erlaubten Zutaten für das Brauen von Bier (Wasser, Malz, Hopfen)","Ein Gesetz zur Reinhaltung der Luft in Städten"]'::jsonb, 'Das bayerische Reinheitsgebot von 1516 ist eine der ältesten lebensmittelrechtlichen Vorschriften der Welt zur Bierherstellung.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-chinese-lang_q1', 'ap-topic-chinese-lang', 1, false, 'B', 'Chinese', 'easy', 'The Spring Festival in China is also commonly known as:', '["Mid-Autumn Festival","Chinese New Year","Dragon Boat Festival","Lantern Festival"]'::jsonb, 'Chunjie (Spring Festival) marks the Lunar New Year.'),
  ('ap-topic-chinese-lang_q2', 'ap-topic-chinese-lang', 2, false, 'A', 'ap-topic-chinese-culture', 'easy', '在中国传统节日中，农历八月十五是哪一个重要的团聚节日？', '["中秋节","端午节","清明节","重阳节"]'::jsonb, '中秋节是农历八月十五，家人团聚赏月并吃月饼，象征圆满吉祥。'),
  ('ap-topic-chinese-lang_q3', 'ap-topic-chinese-lang', 3, false, 'B', 'ap-topic-chinese-grammar', 'easy', '下列句子中，哪一个“把”字句的语法结构完全正确？', '["请把我把书放进书包里。","请把桌子上的书放进书包里。","请放进把书桌子上。","书把请放进书包里。"]'::jsonb, '“把”字句的基本语序为：主语 + 把 + 处置对象（宾语）+ 动词 + 结果补语/方向补语。'),
  ('ap-topic-chinese-lang_q4', 'ap-topic-chinese-lang', 4, false, 'C', 'ap-topic-chinese-idioms', 'medium', '成语“塞翁失马”用来表达什么哲理？', '["遇到困难应该立刻放弃","做事情必须有条理和计划","坏事在一定条件下可以变成好事，祸福相互依存","马跑了就再也找不回来了"]'::jsonb, '“塞翁失马，焉知非福”出自《淮南子》，揭示了祸福相倚、因祸得福的辩证辩思维。'),
  ('ap-topic-chinese-lang_q5', 'ap-topic-chinese-lang', 5, false, 'D', 'ap-topic-chinese-register', 'easy', '在正式商务电子邮件中，作为开头致辞，最得体、尊敬的称呼是：', '["老王，最近怎么样？","喂，王经理在吗？","王兄，见字如面：","尊敬的王经理：您好！"]'::jsonb, '“尊敬的[姓氏+职位]：您好！”是现代中文职场和学术邮件中最规范庄重的书面尊称。'),
  ('ap-topic-chinese-lang_q6', 'ap-topic-chinese-lang', 6, false, 'A', 'ap-topic-chinese-grammar', 'easy', '下列句子中，动态助词“过”表示什么含义？“我去年去过一次北京故宫。”', '["表示曾经拥有的生活经验或经历","表示动作正在进行之中","表示动作即将立刻发生","表示动作持续到将来的状态"]'::jsonb, '动态助词“过”附在动词之后，表示过去曾经发生过某种经历或体验。'),
  ('ap-topic-chinese-lang_q7', 'ap-topic-chinese-lang', 7, false, 'B', 'ap-topic-chinese-culture', 'easy', '中国高铁（CRH）的发展对现代中国社会产生了什么深远影响？', '["彻底取代了所有的民航客运航线","极大地缩短了城市之间的通勤时间，促进了区域经济一体化与人员流动","使得私家汽车在城市完全消失","仅用于偏远农村山区的货物运输"]'::jsonb, '中国高铁网络建设实现了“八纵八横”，重塑了城市群连接与城际通勤模式。'),
  ('ap-topic-chinese-lang_q8', 'ap-topic-chinese-lang', 8, false, 'C', 'ap-topic-chinese-grammar', 'easy', '在中文句型中，“越……越……”常用来表示什么关系？“他的汉语越学越流利。”', '["前后两个动作互相排斥与对立","动作发生的原因与意外转折","程度随着条件的推进而不断加深","假设条件未达成时的遗憾"]'::jsonb, '“越……越……”表示程度随时间的推移或前项条件的变化而成比例递增。'),
  ('ap-topic-chinese-lang_q9', 'ap-topic-chinese-lang', 9, false, 'D', 'ap-topic-chinese-architecture', 'medium', '传统中国建筑中“四合院”的核心布局特征是：', '["依山而建的高耸木制尖顶塔楼","全部采用石头砌成的多层地下迷宫","单一独立的环形混凝土住宅","四面建有房屋，中间围绕一个开放式的庭院"]'::jsonb, '四合院通常由北房、南房和东西厢房四面围合，中央留出方正庭院，讲究内外有别与天人合一。'),
  ('ap-topic-chinese-lang_q10', 'ap-topic-chinese-lang', 10, false, 'A', 'ap-topic-chinese-idioms', 'easy', '成语“画蛇添足”所讽刺的行为是：', '["多此一举，做了多余的事情反而把事情弄糟","绘画技巧非常高超生动","做事认真负责、精益求精","善于发现别人的隐秘缺点"]'::jsonb, '“画蛇添足”比喻做了多余的事不仅无益，反而招致失败。'),
  ('ap-topic-chinese-lang_q11', 'ap-topic-chinese-lang', 11, false, 'B', 'ap-topic-chinese-literature', 'medium', '下列哪一项是中国四大民间传说之一？', '["西游记","白蛇传","三国演义","水浒传"]'::jsonb, '中国四大民间口头传说为：《白蛇传》、《孟姜女哭长城》、《梁山伯与祝英台》、《牛郎织女》。（其余三项为四大名著长篇小说）。'),
  ('ap-topic-chinese-lang_q12', 'ap-topic-chinese-lang', 12, false, 'C', 'ap-topic-chinese-idioms', 'medium', '在中文里，形容一个人“胸有成竹”意思是：', '["特别喜欢在自家庭院种植竹子","胸怀坦荡没有任何秘密","在做事之前心中已经有了成熟完整的谋略与把握","绘画时只擅长画竹叶"]'::jsonb, '原指画竹子前心里先有竹子的生动形象，比喻在行动前早有全盘深思熟虑的方案。'),
  ('ap-topic-chinese-lang_q13', 'ap-topic-chinese-lang', 13, false, 'D', 'ap-topic-chinese-grammar', 'hard', '辨析词语：“必须”和“必需”的区别在于：', '["“必须”只能修饰名词，“必需”修饰动词","两个词完全一样，没有任何区别","“必须”指日常用品，“必需”指道德法规","“必须”是副词，表示一定要；“必需”是动词/形容词，表示不可缺少的事物"]'::jsonb, '“必须”为副词（后接动词/形容词，如必须努力）；“必需”表示必须需要的物品或条件（如生活必需品）。'),
  ('ap-topic-chinese-lang_q14', 'ap-topic-chinese-lang', 14, false, 'A', 'ap-topic-chinese-art', 'medium', '中国书法艺术中的“楷书”主要以什么风格特征著称？', '["字形方正、笔画规整、结构严谨，是学习书法的典范基石","笔画连绵如丝、狂放不羁、极难辨认","直接模拟鸟兽虫鱼的远古象形符号","专门刻在龟甲和青铜器上的刀刻文字"]'::jsonb, '楷书（真书、正书）起于汉魏，字形端庄方正、笔画规范清晰，历来为初学书法者之正统。'),
  ('ap-topic-chinese-lang_q15', 'ap-topic-chinese-lang', 15, false, 'B', 'ap-topic-chinese-grammar', 'easy', '下列句子中，结果补语使用恰当的是：', '["老师讲的重点内容，我都听明白到。","老师讲的重点内容，我都听懂了。","老师讲的重点内容，我都听走完了。","老师讲的重点内容，我都听得着了。"]'::jsonb, '“懂”直接接在动词“听”后充当结果补语，“听懂”表示理解了所听到的内容。'),
  ('ap-topic-chinese-lang_q16', 'ap-topic-chinese-lang', 16, false, 'C', 'ap-topic-chinese-culture', 'medium', '中国的“二十四节气”被列入联合国教科文组织非遗名录，其最初制定的科学依据是：', '["根据月球引力对潮汐的绝对周期性影响","依据皇帝出巡的皇家日程表随机制定","依据太阳在黄道上的位置划分，指导中国古代农业生产活动","模仿外国历法直接翻译引进"]'::jsonb, '二十四节气根据太阳在回归黄道上的视运动轨迹确定，千百年来精准指导农事耕作与物候观察。'),
  ('ap-topic-chinese-lang_q17', 'ap-topic-chinese-lang', 17, false, 'D', 'ap-topic-chinese-grammar', 'medium', '请选出最适合填入括号中的关联词：“（ ）明天下雨，我们（ ）要把这项野外考察任务完成。”', '["因为……所以……","虽然……但是……","只有……才……","即使……也……"]'::jsonb, '“即使……也……”构成让步假设句，强调无论未来天气如何艰难，完成任务的决心不变。'),
  ('ap-topic-chinese-lang_q18', 'ap-topic-chinese-lang', 18, false, 'A', 'ap-topic-chinese-cuisine', 'easy', '在中国饮食文化中，“八大菜系”里的“川菜”最著名的风味特色是：', '["麻辣浓郁，善用花椒与辣椒，调味丰富多变","清淡鲜脆，特别突出食材的原汁原味","重油重糖，擅长深色红烧与蜜汁浸润","主要以牛羊奶制品与烧烤肉类为主"]'::jsonb, '川菜以麻、辣、鲜、香见长，“一菜一格，百菜百味”，以花椒的麻与辣椒的辛香为标志。'),
  ('ap-topic-chinese-lang_q19', 'ap-topic-chinese-lang', 19, false, 'B', 'ap-topic-chinese-modern', 'easy', '在现代中国移动支付极为普及的背景下，“扫码支付”通常使用的是什么技术？', '["指纹按压印泥复印技术","二维码（QR Code）识别技术","传统纸质支票邮寄核验","磁带录音音频比对"]'::jsonb, '通过微信或支付宝扫描商家或个人的动态二维码（QR Code）是当代中国最具代表性的日常移动支付方式。'),
  ('ap-topic-chinese-lang_q20', 'ap-topic-chinese-lang', 20, false, 'C', 'ap-topic-chinese-pragmatics', 'easy', '在日常交际中，当别人竭诚赞美你的中文表达非常流利时，最符合中国传统谦逊美德的回应是：', '["当然了，我天生就是语言天才！","对啊，你说的完全是不可否认的客观事实。","哪里哪里，您过奖了，我还要多向您学习呢！","不用你说，我自己早就知道了。"]'::jsonb, '“哪里哪里，您过奖了”是中国人面对他人由衷夸奖时最经典、谦和得体的礼貌答谢语。'),
  ('ap-topic-japanese-lang_q1', 'ap-topic-japanese-lang', 1, false, 'B', 'Japanese', 'easy', 'Which Japanese writing system is primarily used for foreign loanwords?', '["Hiragana","Katakana","Kanji","Romaji"]'::jsonb, 'Katakana transcribes loanwords and foreign names.'),
  ('ap-topic-japanese-lang_q2', 'ap-topic-japanese-lang', 2, false, 'A', 'ap-topic-japanese-culture', 'easy', '日本における「おもてなし」という文化的概念の核心的な意味は何ですか。', '["見返りを求めず、相手の立場に立って真心を込めて客をもてなす心遣い","高価なプレゼントを強制的に交換する儀礼","観光客から最大限の利益を引き出す商業技術","外国の文化を完全に排除する伝統主義"]'::jsonb, '「おもてなし」は相手に対する深い敬意と細やかな気配りをもって接する日本の伝統的精神です。'),
  ('ap-topic-japanese-lang_q3', 'ap-topic-japanese-lang', 3, false, 'B', 'ap-topic-japanese-grammar', 'medium', '目上の人に対して自分の行動をへりくだって伝える際に用いる、適切な謙譲語はどれですか。', '["明日、先生のオフィスにいらっしゃいます。","明日、先生のオフィスに伺います。","明日、先生のオフィスにおいでになります。","明日、先生のオフィスに行かれます。"]'::jsonb, '「伺う（うかがう）」は「行く」「訪ねる」の謙譲語であり、目上の人を訪ねる自分の動作をへりくだって表現します。'),
  ('ap-topic-japanese-lang_q4', 'ap-topic-japanese-lang', 4, false, 'C', 'ap-topic-japanese-grammar', 'easy', '文脈に合う最も適切な接続詞を選びなさい。「昨夜は遅くまで勉強した。（　　）、試験では実力を発揮できなかった。」', '["だから","つまり","しかし","さらに"]'::jsonb, '努力したことと望ましい結果が出なかったことの逆接を表すため、「しかし」が適切です。'),
  ('ap-topic-japanese-lang_q5', 'ap-topic-japanese-lang', 5, false, 'D', 'ap-topic-japanese-culture', 'medium', '日本の伝統的な住居に見られる「畳（たたみ）」の原料となる植物は何ですか。', '["竹（タケ）","麻（アサ）","和紙（ワシ）","い草（イグサ）"]'::jsonb, '畳表（たたみおもて）は、泥染めされた「い草」を織り上げて作られます。'),
  ('ap-topic-japanese-lang_q6', 'ap-topic-japanese-lang', 6, false, 'A', 'ap-topic-japanese-grammar', 'easy', '次の文の（　）に入る最も適切な助詞を選びなさい。「友達（　）相談してから、進路を決めようと思います。」', '["に","を","で","へ"]'::jsonb, '相談する相手を示す格助詞は「に」を用います（「〜に相談する」）。'),
  ('ap-topic-japanese-lang_q7', 'ap-topic-japanese-lang', 7, false, 'B', 'ap-topic-japanese-culture', 'easy', '日本のお正月において、新年の健康や長寿、子孫繁栄を祈って食べられる伝統料理は何ですか。', '["年越しそば","おせち料理","恵方巻","月見団子"]'::jsonb, '重箱に詰められた「おせち料理」には、黒豆（まめに暮らす）、数の子（子孫繁栄）などの祈りが込められています。'),
  ('ap-topic-japanese-lang_q8', 'ap-topic-japanese-lang', 8, false, 'C', 'ap-topic-japanese-grammar', 'hard', '受身形（受け身）の文として文法的に正しいものはどれですか。', '["雨が降られて、服が濡れた。","雨を降られて、傘をさした。","雨に降られて、服がびしょ濡れになってしまった。","雨に降らせて、家に帰った。"]'::jsonb, '迷惑の受身（間接受身）表現として「雨に降られる」は典型的な日本語の文型です。'),
  ('ap-topic-japanese-lang_q9', 'ap-topic-japanese-lang', 9, false, 'D', 'ap-topic-japanese-idioms', 'medium', 'ことわざ「石の上にも三年」が教える教訓は何ですか。', '["冷たい石には座らないほうが健康に良い","三年間は誰とも話さずに修行すべきである","どんな計画も三年後には変更されるべきだ","辛くても辛抱強く努力を続ければ、必ず成果が得られる"]'::jsonb, '冷たい石でも三年座り続ければ温まることから、忍耐と継続の大切さを説いたことわざです。'),
  ('ap-topic-japanese-lang_q10', 'ap-topic-japanese-lang', 10, false, 'A', 'ap-topic-japanese-register', 'easy', 'ビジネスメールの結びの言葉として、最も標準的で丁寧な挨拶はどれですか。', '["何卒よろしくお願い申し上げます。","じゃあ、また連絡してね。","ご苦労様でした。","それでは失礼しちゃうよ。"]'::jsonb, '「何卒（なにとぞ）よろしくお願い申し上げます」はビジネス文書の結びとして極めて丁寧な敬語表現です。'),
  ('ap-topic-japanese-lang_q11', 'ap-topic-japanese-lang', 11, false, 'B', 'ap-topic-japanese-literature', 'easy', '日本文学の古典『源氏物語』の作者は誰ですか。', '["清少納言","紫式部","与謝野晶子","樋口一葉"]'::jsonb, '平安時代中期に宮廷に仕えた紫式部によって著された全五十四帖の長編小説です。'),
  ('ap-topic-japanese-lang_q12', 'ap-topic-japanese-lang', 12, false, 'C', 'ap-topic-japanese-grammar', 'medium', '「〜ばかり」の用法として、「食べたばかり」の意味を正しく説明しているものはどれですか。', '["いつも食事ばかりしていて他のことをしないこと","これから食事を始めようとしている瞬間","食事を終えてから、ほんの少ししか時間が経っていないこと","食事の量が非常に少なかったこと"]'::jsonb, '動詞のタ形＋「ばかり」は、その動作が完了した直後であることを表します。'),
  ('ap-topic-japanese-lang_q13', 'ap-topic-japanese-lang', 13, false, 'D', 'ap-topic-japanese-tech', 'medium', '新幹線や駅の改札で広く利用されている「Suica」や「PASMO」などの交通系ICカードの基礎技術は何ですか。', '["バーコード手動読み取り","磁気テープ摩擦記録","指紋認証カメラ","非接触型IC通信技術（FeliCa / RFID）"]'::jsonb, 'ソニーが開発した高速非接触ICカード技術「FeliCa」規格が交通系ICカードに採用されています。'),
  ('ap-topic-japanese-lang_q14', 'ap-topic-japanese-lang', 14, false, 'A', 'ap-topic-japanese-culture', 'medium', '日本の「春の七草」を粥にして食べる日（人日の節句）はいつですか。', '["1月7日","3月3日","5月5日","7月7日"]'::jsonb, '1月7日の朝に七草粥（ななくさがゆ）を食べて、無病息災を祈り、正月の祝膳で疲れた胃を休めます。'),
  ('ap-topic-japanese-lang_q15', 'ap-topic-japanese-lang', 15, false, 'B', 'ap-topic-japanese-grammar', 'medium', '使役動詞「書かせる」の意味として正しい解釈はどれですか。', '["先生が生徒の代わりに作文を書いた","先生が生徒に作文を書くように指示または許可した","生徒が先生に作文を書いてもらった","先生が作文を自分で読んだ"]'::jsonb, '使役形（〜せる／〜させる）は、他者に対して動作を行わせる（指示・強制・放任）ことを表します。'),
  ('ap-topic-japanese-lang_q16', 'ap-topic-japanese-lang', 16, false, 'C', 'ap-topic-japanese-aesthetics', 'medium', '「わび・さび（侘・寂）」という美意識が最も強く反映されている伝統文化はどれですか。', '["歌舞伎の派手な立ち回り","夏祭りの花火大会","茶道（茶の湯）","大相撲の土俵入り"]'::jsonb, '千利休が大成した草庵の茶の湯は、簡素さや静けさ、不完全さの中に深い美を見出す「わび・さび」の真髄です。'),
  ('ap-topic-japanese-lang_q17', 'ap-topic-japanese-lang', 17, false, 'D', 'ap-topic-japanese-grammar', 'medium', '敬語表現「お戻りになりましたら」における動詞「戻る」の敬語の種類は何ですか。', '["謙譲語","丁寧語","美化語","尊敬語"]'::jsonb, '「お＋動詞連用形＋になる」は相手の動作を高める規則的な「尊敬語」の形です。'),
  ('ap-topic-japanese-lang_q18', 'ap-topic-japanese-lang', 18, false, 'A', 'ap-topic-japanese-culture', 'easy', '環境問題に関する日本の標語「もったいない（Mottainai）」に込められたメッセージは何ですか。', '["物の価値を十分に生かしきれず無駄にすることを惜しみ、感謝する心","お金を一切使わずに貯金だけを増やすこと","古いものはすぐに捨てて新しい製品を買うこと","外国製の製品を一切買わないこと"]'::jsonb, '「もったいない」はリデュース・リユース・リサイクルに加え、万物への敬意と感謝を表す言葉として国際的にも注目されました。'),
  ('ap-topic-japanese-lang_q19', 'ap-topic-japanese-lang', 19, false, 'B', 'ap-topic-japanese-vocab', 'easy', '文法的に正しい複合動詞を選びなさい。「最後まで諦めずに、困難を乗り（　　）。」', '["出した","越えた","落ちた","込んだ"]'::jsonb, '「困難を乗り越える（のりこえる）」は、障害や試練を克服して前進するという意味の慣用的な複合動詞です。'),
  ('ap-topic-japanese-lang_q20', 'ap-topic-japanese-lang', 20, false, 'C', 'ap-topic-japanese-arts', 'hard', '日本の伝統芸能「能（のう）」の特徴として正しいものはどれですか。', '["人形を三人で操る人形芝居","一人で座布団の上に座り、扇子と手ぬぐいだけで演じる滑稽な噺","演者が専用の面（おもて）をつけ、極限まで抑制された所作と謡で演じる歌舞劇","派手な隈取（くまどり）化粧をして激しく見得を切る芝居"]'::jsonb, '能は室町時代に観阿弥・世阿弥によって大成された仮面歌舞劇です（人形は文楽、座布団は落語、隈取は歌舞伎）。'),
  ('ap-topic-italian-lang_q1', 'ap-topic-italian-lang', 1, false, 'A', 'Italian', 'easy', 'The Italian past tense form ''passato prossimo'' uses which auxiliary verbs?', '["avere or essere","dovere or potere","fare or stare","andare or venire"]'::jsonb, 'Passato prossimo is formed using avere or essere.'),
  ('ap-topic-italian-lang_q2', 'ap-topic-italian-lang', 2, false, 'A', 'ap-topic-italian-culture', 'easy', 'Nel contesto della cultura italiana, che cosa si intende con il termine ''il Rinascimento''?', '["Uno straordinario periodo di fioritura artistica, filosofica e scientifica tra il XIV e il XVI secolo che pose l''uomo al centro dell''universo","Un movimento letterario del Novecento focalizzato sulla tecnologia e la velocità industriale","La riforma agraria del Mezzogiorno avvenuta nel dopoguerra","Una festa gastronomica tradizionale che celebra la vendemmia autunnale"]'::jsonb, 'Il Rinascimento, nato a Firenze, ha segnato il passaggio dal Medioevo alla modernità attraverso la riscoperta dei classici e l''Umanesimo.'),
  ('ap-topic-italian-lang_q3', 'ap-topic-italian-lang', 3, false, 'B', 'ap-topic-italian-grammar', 'medium', 'Quale frase contiene l''uso corretto del congiuntivo presente dopo un verbo di opinione?', '["Penso che Marco ha ragione su questa faccenda delicata.","Credo che Marco abbia ragione su questa faccenda delicata.","So con certezza che Marco sia a casa oggi pomeriggio.","È sicuro che Marco venga alla festa stasera."]'::jsonb, 'Verbi che esprimono opinione o incertezza come ''credere che'' richiedono il congiuntivo (''abbia''). Certezza come ''so con certezza'' richiede l''indicativo.'),
  ('ap-topic-italian-lang_q4', 'ap-topic-italian-lang', 4, false, 'C', 'ap-topic-italian-register', 'easy', 'In una lettera formale a un professore universitario, qual è la formula di apertura più conveniente?', '["Caro professore, come te la passi?","Ciao caro, ti scrivo due righe veloci,","Gentilissimo Chiarissimo Professore,","Ehi docente, mi ascolti un attimo?"]'::jsonb, '''Gentilissimo Chiarissimo Professore'' rispetta la più alta etichetta formale accademica in Italia.'),
  ('ap-topic-italian-lang_q5', 'ap-topic-italian-lang', 5, false, 'D', 'ap-topic-italian-culture', 'easy', 'Che cosa rappresenta il ''Made in Italy'' nell''economia globale contemporanea?', '["Un programma governativo di sussidi esclusivi per l''industria siderurgica pesante","Un marchio obbligatorio per tutti i prodotti importati dall''Asia","Una legge doganale europea che vieta le esportazioni verso le Americhe","L''eccellenza, l''eleganza artigianale e il design nei settori della moda, dell''arredamento, dell''automotive e dell''agroalimentare"]'::jsonb, 'Il ''Made in Italy'' è universalmente sinonimo di qualità, creatività, raffinatezza estetica e tradizione manifatturiera italiana.'),
  ('ap-topic-italian-lang_q6', 'ap-topic-italian-lang', 6, false, 'A', 'ap-topic-italian-grammar', 'medium', 'Scegli il pronome combinato corretto per completare la frase: ''Se hai bisogno del libro di storia, ______ presto volentieri domani.''', '["te lo","ti la","glielo","se ne"]'::jsonb, '''A te'' (ti -> te) + ''il libro'' (lo) forma il pronome combinato ''te lo'' (''te lo presto'').'),
  ('ap-topic-italian-lang_q7', 'ap-topic-italian-lang', 7, false, 'B', 'ap-topic-italian-grammar', 'medium', 'Qual è la differenza d''uso principale tra il ''passato prossimo'' e ''l''imperfetto'' nell''indicativo italiano?', '["L''imperfetto si usa solo per eventi storici medievali, il passato prossimo per fatti di ieri","Il passato prossimo esprime azioni concluse e puntuali; l''imperfetto descrive stati, abitudini o azioni continue nel passato","Non esiste alcuna distinzione, sono perfettamente intercambiabili in qualsiasi frase","L''imperfetto richiede sempre il verbo ausiliare essere"]'::jsonb, 'L''aspetto verbale oppone la compiutezza e puntualità del passato prossimo alla continuità, descrizione e iterazione abituale dell''imperfetto.'),
  ('ap-topic-italian-lang_q8', 'ap-topic-italian-lang', 8, false, 'C', 'ap-topic-italian-idioms', 'easy', 'L''espressione idiomatica ''In bocca al lupo!'' viene usata per:', '["Mettere in guardia contro un pericolo mortale in montagna","Invitare gli ospiti a iniziare un banchetto abbondante","Augurare buona fortuna prima di una prova o di un esame importante","Congedarsi freddamente da una persona sgradita"]'::jsonb, 'È il classico augurio scaramantico italiano a cui si risponde tradizionalmente: ''Crepi il lupo!'' (o ''Viva il lupo!'').'),
  ('ap-topic-italian-lang_q9', 'ap-topic-italian-lang', 9, false, 'D', 'ap-topic-italian-art', 'easy', 'Quale celebre monumento fiorentino è celebre per l''innovativa cupola autoportante progettata da Filippo Brunelleschi?', '["La Basilica di San Pietro in Vaticano","Il Colosseo degli imperatori flavi","La Torre pendente di Pisa","La Cattedrale di Santa Maria del Fiore (il Duomo di Firenze)"]'::jsonb, 'Brunelleschi eresse la gigantesca cupola ottagonale di Santa Maria del Fiore a Firenze senza centine di sostegno in legno, capolavoro dell''ingegneria rinascimentale.'),
  ('ap-topic-italian-lang_q10', 'ap-topic-italian-lang', 10, false, 'A', 'ap-topic-italian-grammar', 'hard', 'Nel periodo ipotetico dell''irrealtà nel passato, quale combinazione di modi e tempi verbali è corretta?', '["Se avessi saputo della riunione, sarei venuto subito.","Se sapessi della riunione, verrei subito.","Se ho saputo della riunione, venivo subito.","Se avrei saputo della riunione, fossi venuto subito."]'::jsonb, 'L''irrealtà nel passato si costruisce con: ''Se + congiuntivo trapassato ..., condizionale composto'' (''Se avessi saputo..., sarei venuto'').')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-italian-lang_q11', 'ap-topic-italian-lang', 11, false, 'B', 'ap-topic-italian-culture', 'easy', 'Che cosa si intende con la tradizione sociale della ''passeggiata'' nei centri storici italiani?', '["Una maratona agonistica organizzata ogni domenica mattina","Il rito serale di camminare per il corso o la piazza principale per incontrarsi, conversare e farsi vedere","Un pellegrinaggio religioso penitenziale verso un santuario alpino","L''obbligo di spostarsi esclusivamente a piedi durante i giorni feriali"]'::jsonb, 'La passeggiata pomeridiana o preserale è un''abitudine sociale fondamentale della vita comunitaria italiana per socializzare nel cuore della città.'),
  ('ap-topic-italian-lang_q12', 'ap-topic-italian-lang', 12, false, 'C', 'ap-topic-italian-grammar', 'medium', 'Quale accordo del participio passato è grammaticalmente corretto con il pronome diretto ''le''?', '["Ho visto delle belle mostre a Roma e le ho visitato tutte.","Ho visto delle belle mostre a Roma e le ho visitati tutti.","Ho visto delle belle mostre a Roma e le ho visitate tutte.","Ho visto delle belle mostre a Roma e le ho visitata tutte."]'::jsonb, 'Quando il passato prossimo è preceduto dai pronomi diretti di 3a persona (lo, la, li, le), l''accordo del participio passato in genere e numero è obbligatorio: ''le ho visitate''.'),
  ('ap-topic-italian-lang_q13', 'ap-topic-italian-lang', 13, false, 'D', 'ap-topic-italian-culture', 'easy', 'Che cos''è la ''Dieta Mediterranea'', patrimonio immateriale dell''UNESCO?', '["Una dieta a base esclusiva di carne rossa e grassi animali idrogenati","Il divieto governativo di consumare pasta e pane nei ristoranti","Un piano di digiuno terapeutico praticato nei monasteri","Un modello nutrizionale equilibrato basato su olio extravergine d''oliva, cereali integrali, legumi, frutta, verdura e moderato consumo di pesce e carne"]'::jsonb, 'La Dieta Mediterranea italiana promuove la salute cardiovascolare e la sostenibilità attraverso cibi freschi, stagionali e non raffinati.'),
  ('ap-topic-italian-lang_q14', 'ap-topic-italian-lang', 14, false, 'A', 'ap-topic-italian-vocab', 'medium', 'Nel brano: ''Le riforme hanno sortito gli effetti sperati'', che cosa significa il verbo ''sortire''?', '["Ottenere, produrre o sorteggiare come esito","Distruggere completamente ogni progresso","Rinviare all''anno successivo","Sottovalutare gravemente le conseguenze"]'::jsonb, '''Sortire'' in questo contesto formale significa conseguire, generare o raggiungere un determinato effetto voluto.'),
  ('ap-topic-italian-lang_q15', 'ap-topic-italian-lang', 15, false, 'B', 'ap-topic-italian-geography', 'easy', 'Quale città italiana è famosa in tutto il mondo per il Carnevale con maschere raffinate settecentesche e canali navigabili?', '["Palermo","Venezia","Torino","Bologna"]'::jsonb, 'Il Carnevale di Venezia è celebre per le sue maschere storiche (la Bauta), gondole e cortei acquei sulla laguna.'),
  ('ap-topic-italian-lang_q16', 'ap-topic-italian-lang', 16, false, 'C', 'ap-topic-italian-grammar', 'medium', 'Individua la frase che utilizza correttamente la particella pronominale ''ne'':', '["Vado a Roma e ne rimango per una settimana.","Ho salutato i miei amici e ne ho invitati a cena.","Abbiamo comprato molte mele mature e ne abbiamo mangiate tre.","Leggo il giornale e ne guardo le immagini."]'::jsonb, '''Ne'' con valore partitivo sostituisce una parte di un insieme quantificabile (''tre di esse'') e richiede l''accordo del participio passato: ''ne abbiamo mangiate tre''.'),
  ('ap-topic-italian-lang_q17', 'ap-topic-italian-lang', 17, false, 'D', 'ap-topic-italian-literature', 'easy', 'Chi è l''autore della celebre opera letteraria ''La Divina Commedia'', pietra miliare della lingua italiana?', '["Francesco Petrarca","Giovanni Boccaccio","Niccolò Machiavelli","Dante Alighieri"]'::jsonb, 'Dante Alighieri è considerato il ''padre della lingua italiana'' grazie alla diffusione e grandezza poetica della sua Divina Commedia in volgare toscano.'),
  ('ap-topic-italian-lang_q18', 'ap-topic-italian-lang', 18, false, 'A', 'ap-topic-italian-culture', 'easy', 'Cosa si intende per ''ferragosto'' nella tradizione festiva italiana?', '["La festività nazionale del 15 agosto, che segna il culmine delle vacanze estive","L''apertura della stagione sciistica invernale in Valle d''Aosta","La celebrazione della liberazione dal nazifascismo il 25 aprile","La commemorazione dei defunti all''inizio di novembre"]'::jsonb, 'Il Ferragosto (Feriae Augusti) è un''antica ricorrenza estiva romana e cattolica (Assunzione) celebrata il 15 agosto con gite fuori porta.'),
  ('ap-topic-italian-lang_q19', 'ap-topic-italian-lang', 19, false, 'B', 'ap-topic-italian-grammar', 'medium', 'Completa la frase con l''imperativo formale (cortesia) del verbo accomodarsi: ''Prego dottore, ______ pure nello studio.''', '["accomodati","si accomodi","accomodatevi","ti accomodi"]'::jsonb, 'L''imperativo formale con ''Lei'' del verbo riflessivo ''accomodarsi'' è ''si accomodi'' (desinenza in -i per la prima coniugazione).'),
  ('ap-topic-italian-lang_q20', 'ap-topic-italian-lang', 20, false, 'C', 'ap-topic-italian-history', 'medium', 'L''istituzione dell''Unione Europea ha visto l''Italia come uno dei sei paesi fondatori originari con la firma di quale storico trattato nel 1957?', '["Il Trattato di Versailles","Il Trattato di Schengen","I Trattati di Roma","Il Trattato di Maastricht"]'::jsonb, 'Nel marzo 1957, i Trattati di Roma istituirono la Comunità Economica Europea (CEE) e l''Euratom tra Italia, Francia, Germania Ovest e Benelux.'),
  ('ap-topic-latin-caesar_q1', 'ap-topic-latin-caesar', 1, false, 'B', 'Latin', 'hard', 'The meter of Vergil''s Aeneid is:', '["Iambic Pentameter","Dactylic Hexameter","Hendecasyllabic","Elegiac Couplet"]'::jsonb, 'Epic poetry like the Aeneid is composed in dactylic hexameter.'),
  ('ap-topic-latin-caesar_q2', 'ap-topic-latin-caesar', 2, false, 'A', 'ap-topic-latin-aeneid', 'medium', 'In Book 1 of Vergil''s Aeneid, what divine conflict initiates the epic journey of Aeneas?', '["Juno''s unrelenting wrath against the Trojans due to the Judgment of Paris and Carthage''s destiny","Venus''s direct attempt to destroy her own son Aeneas at sea","Jupiter''s decree that Rome must never be founded","Neptune''s desire to drown the Trojan fleet without provocation"]'::jsonb, 'Juno''s wrath (''saevae memorem Iunonis ob iram'') stems from Paris''s snub of her beauty, Ganymede''s honors, and the prophecy that a Trojan race will crush her beloved Carthage.'),
  ('ap-topic-latin-caesar_q3', 'ap-topic-latin-caesar', 3, false, 'B', 'ap-topic-latin-grammar', 'medium', 'Translate and identify the grammatical construction: ''His rebus gestis, Caesar exercitum in hiberna reduxit.''', '["Indirect statement: ''Caesar said that these things had been accomplished in winter quarters.''","Ablative absolute: ''With these things having been accomplished, Caesar led the army back into winter quarters.''","Purpose clause: ''In order that these things might be accomplished, Caesar led the army.''","Result clause: ''These things were accomplished so that Caesar led the army.''"]'::jsonb, '''His rebus gestis'' consists of a noun and perfect passive participle in the ablative case functioning grammatically independently as an ablative absolute.'),
  ('ap-topic-latin-caesar_q4', 'ap-topic-latin-caesar', 4, false, 'C', 'ap-topic-latin-caesar', 'easy', 'In Caesar''s De Bello Gallico (Book 1.1), what is the famous opening geopolitical statement?', '["''Arma virumque cano, Troiae qui primus ab oris...''","''Quo usque tandem abutere, Catilina, patientia nostra?''","''Gallia est omnis divisa in partes tres...''","''Gallia tota sub imperio Caesaris semper mansit...''"]'::jsonb, 'Caesar famously opens his commentaries: ''Gallia est omnis divisa in partes tres, quarum unam incolunt Belgae, aliam Aquitani, tertiam... Celtae''.'),
  ('ap-topic-latin-caesar_q5', 'ap-topic-latin-caesar', 5, false, 'D', 'ap-topic-latin-meter', 'easy', 'Identify the meter of Vergil''s Aeneid:', '["Elegiac Couplet","Hendecasyllabic","Sapphic Stanza","Dactylic Hexameter"]'::jsonb, 'Greco-Roman heroic epic poetry, including Homer''s Iliad and Vergil''s Aeneid, is composed exclusively in dactylic hexameter (six metrical feet of dactyls and spondees).'),
  ('ap-topic-latin-caesar_q6', 'ap-topic-latin-caesar', 6, false, 'A', 'ap-topic-latin-grammar', 'hard', 'What syntactic construction follows a verb of fearing in classical Latin (e.g., ''Timeo ne hostes urbem capiant'')?', '["Subjunctive clause introduced by ''ne'' meaning that the feared event WILL happen","Infinitive with subject accusative stating a known fact","Subjunctive clause introduced by ''ut'' meaning that the feared event will NOT happen","Ablative of agent without preposition"]'::jsonb, 'In clauses of fearing, the conjunctions are inverted from English intuition: ''timeo ne'' introduces fear that something WILL occur, while ''timeo ut'' introduces fear that something will NOT occur.'),
  ('ap-topic-latin-caesar_q7', 'ap-topic-latin-caesar', 7, false, 'B', 'ap-topic-latin-caesar', 'medium', 'In De Bello Gallico Book 6, what distinct religious and civic role does Caesar attribute to the Druids?', '["They are frontline shock cavalry warriors in every tribal conflict","They administer divine worship, perform public sacrifices, adjudicate controversies, and are exempt from military service and taxation","They serve as subservient slaves to the tribal military chieftains","They worship Roman gods exclusively and build marble temples in cities"]'::jsonb, 'Caesar records that the Druids occupy the highest elite intellectual and judicial status in Gallic society, arbitrating disputes and preserving sacred oral lore.'),
  ('ap-topic-latin-caesar_q8', 'ap-topic-latin-caesar', 8, false, 'C', 'ap-topic-latin-aeneid', 'easy', 'In Aeneid Book 2, what does the Trojan priest Laocoön warn against regarding the wooden horse?', '["''Dulce et decorum est pro patria mori''","''O tempora, o mores!''","''Timeo Danaos et dona ferentes'' (I fear the Greeks even bearing gifts)","''Forsan et haec olim meminisse iuvabit''"]'::jsonb, 'Laocoön hurls his spear at the Trojan horse and warns his fellow citizens never to trust Greek offerings (''Timeo Danaos et dona ferentes'').'),
  ('ap-topic-latin-caesar_q9', 'ap-topic-latin-caesar', 9, false, 'D', 'ap-topic-latin-rhetoric', 'medium', 'Identify the rhetorical figure of speech in: ''urbs antiqua fuit (Tyrii tenuere coloni)'' where the natural word order is deliberately inverted or interrupted:', '["Chiasmus","Tmesis","Polysyndeton","Parenthesis / Anastrophe"]'::jsonb, 'The insertion of a self-contained explanatory thought within the line constitutes an inserted parenthesis or narrative digression.'),
  ('ap-topic-latin-caesar_q10', 'ap-topic-latin-caesar', 10, false, 'A', 'ap-topic-latin-grammar', 'medium', 'In the sentence: ''Caesar legatos misit qui pacem peterent'', what is the function of the relative clause?', '["Relative clause of purpose: ''Caesar sent envoys to seek peace.''","Relative clause of characteristic describing wicked men","Simple factual relative clause in the indicative","Conditional clause contrary to fact"]'::jsonb, 'A relative pronoun (''qui'') followed by a subjunctive verb (''peterent'') instead of an indicative indicates intent or purpose (''ut ii pacem peterent'').'),
  ('ap-topic-latin-caesar_q11', 'ap-topic-latin-caesar', 11, false, 'B', 'ap-topic-latin-culture', 'easy', 'What Roman cultural ideal, personified by Aeneas as ''pius Aeneas'', forms the moral cornerstone of the epic?', '["Furor: uncontrolled passion and bloodthirsty rage on the battlefield","Pietas: unwavering devotion and duty toward the gods, fatherland, family, and destiny","Otium: peaceful retirement and leisure away from civic duties","Clementia: showing immediate mercy to Turnus without hesitation"]'::jsonb, '''Pietas'' is the central Roman virtue of subordinate submission to divine fate, filial responsibility toward family (Anchises and Ascanius), and civic leadership.'),
  ('ap-topic-latin-caesar_q12', 'ap-topic-latin-caesar', 12, false, 'C', 'ap-topic-latin-grammar', 'easy', 'In indirect statement (oratio obliqua), how are the subject and the verb of the reported speech represented?', '["Subject in the Nominative case, verb in the Subjunctive mood","Subject in the Dative case, verb in the Imperative mood","Subject in the Accusative case, verb in the Infinitive mood","Subject in the Ablative case, verb in the Gerundive form"]'::jsonb, 'Classical Latin indirect statement after mental perception verbs requires an accusative subject and infinitive verb (''Dicit Aeneam Troiam relinquere'').'),
  ('ap-topic-latin-caesar_q13', 'ap-topic-latin-caesar', 13, false, 'D', 'ap-topic-latin-rhetoric', 'medium', 'What is the poetic device known as ''chiasmus'' in Latin poetry?', '["An ABAB parallel arrangement of alternating nouns and adjectives","The repetition of a word at the beginning of successive clauses","The omission of coordinating conjunctions between phrases","An ABBA arrangement of corresponding words or grammatical elements"]'::jsonb, 'Chiasmus is an interlocking ''crosswise'' structure named after the Greek letter Chi (X), patterning elements as A-B-B-A.'),
  ('ap-topic-latin-caesar_q14', 'ap-topic-latin-caesar', 14, false, 'A', 'ap-topic-latin-grammar', 'medium', 'Translate: ''Dux militibus imperavit ut pontem rescinderent.''', '["The leader ordered the soldiers to tear down the bridge.","The leader knew that the soldiers had crossed the bridge.","The leader feared that the soldiers would build a bridge.","The leader prevented the soldiers from touching the bridge."]'::jsonb, '''Imperare'' takes a dative of the person commanded (''militibus'') and an indirect command clause with ''ut'' + subjunctive (''ut pontem rescinderent'').'),
  ('ap-topic-latin-caesar_q15', 'ap-topic-latin-caesar', 15, false, 'B', 'ap-topic-latin-aeneid', 'medium', 'In Aeneid Book 4, what tragic conflict drives Queen Dido to her suicide?', '["The immediate military conquest of Carthage by neighboring Numidian tribes","Her agonizing betrayal between sacred fidelity to her dead husband Sychaeus and consumed passion for Aeneas, who departs by divine command","A curse placed upon her by Apollo that robbed her of her kingdom''s wealth","The murder of her sister Anna by Trojan soldiers"]'::jsonb, 'Dido is devastated by Aeneas''s forced departure to Italy pursuant to Jupiter''s orders via Mercury, cursing his descendants (the Punic Wars) before ending her life on the pyre.'),
  ('ap-topic-latin-caesar_q16', 'ap-topic-latin-caesar', 16, false, 'C', 'ap-topic-latin-grammar', 'medium', 'What is the grammatical construction and meaning of a passive periphrastic: ''Carthago delenda est''?', '["Participle + sum denoting simple past fact: ''Carthage was destroyed.''","Future active infinitive stating potential: ''Carthage will destroy others.''","Gerundive + sum denoting obligation/necessity: ''Carthage must be destroyed.''","Ablative of manner: ''In a destroyed state Carthage remains.''"]'::jsonb, 'The passive periphrastic uses the future passive participle (gerundive) with forms of ''esse'' to express necessity or moral obligation; the agent is placed in the dative case.'),
  ('ap-topic-latin-caesar_q17', 'ap-topic-latin-caesar', 17, false, 'D', 'ap-topic-latin-caesar', 'medium', 'In Caesar''s De Bello Gallico Book 4, why does Caesar construct a massive wooden trestle bridge across the Rhine River in only ten days?', '["To permanently build Roman villas and towns in deep Germania","Because his naval fleet was entirely captured by the Suebi","To retreat in panic from the advancing Helvetian horde","To display Roman engineering supremacy and terrorize the Germanic tribes into submission without permanent annexation"]'::jsonb, 'Caesar explicitly notes that ferrying his legions across on boats was below the dignity of Rome; the engineering marvel proved Roman logistical dominance.'),
  ('ap-topic-latin-caesar_q18', 'ap-topic-latin-caesar', 18, false, 'A', 'ap-topic-latin-meter', 'hard', 'Scan the first metrical foot of Vergil''s line: ''Arma virumque cano...''', '["Dactyl: Ār-mă vĭ- (long, short, short)","Spondee: Ār-mā (long, long)","Trochee: Ār-mă (long, short)","Anapest: ăr-mă-vī (short, short, long)"]'::jsonb, '''Ar-'' is long by position (followed by rm), ''-ma'' is short (followed by single v), and ''vi-'' is short: forming a dactyl (- u u).'),
  ('ap-topic-latin-caesar_q19', 'ap-topic-latin-caesar', 19, false, 'B', 'ap-topic-latin-grammar', 'hard', 'Translate: ''Si hoc dixisses, vehementer erravissetis.''', '["Present contrary-to-fact conditional: ''If you were saying this, you would be erring.''","Past contrary-to-fact conditional: ''If you had said this, you would have erred vehemently.''","Future more vivid conditional: ''If you say this, you will err.''","Future less vivid conditional: ''If you should say this, you would err.''"]'::jsonb, 'Pluperfect subjunctive in both the protasis (''dixisses'') and apodosis (''erravissetis'') forms a past contrary-to-fact (unreal past) conditional.'),
  ('ap-topic-latin-caesar_q20', 'ap-topic-latin-caesar', 20, false, 'C', 'ap-topic-latin-aeneid', 'medium', 'In Aeneid Book 6, where does the Cumaean Sibyl lead Aeneas, and what vision does Anchises reveal to him?', '["To Mount Olympus to be crowned an immortal god","To the ruins of Troy to exhume King Priam''s buried treasure","Into the Underworld (Dis), where Anchises parades the future heroes, leaders, and glory of Rome (the Pageant of Heroes)","To Athens to study philosophy under Plato"]'::jsonb, 'After crossing the Styx with the golden bough, Aeneas meets Anchises in the Elysian Fields, who displays Augustus Caesar, Romulus, and the glorious destiny of Rome.'),
  ('ap-topic-seminar-quest_q1', 'ap-topic-seminar-quest', 1, false, 'B', 'Seminar', 'easy', 'In the AP Seminar QUEST framework, what does the letter ''E'' stand for?', '["Evaluate Line of Reasoning","Examine Evidence","Explore Options","Establish Context"]'::jsonb, '''E'' stands for Evaluate Evidence in QUEST.'),
  ('ap-topic-seminar-quest_q2', 'ap-topic-seminar-quest', 2, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'In the AP Capstone QUEST pedagogical framework, what does the acronym "QUEST" stand for?', '["Question and explore, Understand and analyze, Evaluate multiple perspectives, Synthesize ideas, Team, transform, and transmit","Query, Understand, Experiment, Solve, Test","Qualitative evaluation, Universal standards, Empirical evidence, Statistical testing","Quotation, Underlining, Editing, Spelling, Typographic formatting"]'::jsonb, 'The Capstone QUEST framework guides interdisciplinary inquiry: Question and explore, Understand and analyze, Evaluate multiple perspectives, Synthesize ideas, Team, transform, and transmit.'),
  ('ap-topic-seminar-quest_q3', 'ap-topic-seminar-quest', 3, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'When evaluating the credibility of a secondary source using the RAVEN tool in AP Seminar, what does the "V" represent?', '["Vested interest: whether the author or organization has a personal, financial, or political stake in the outcome","Validity: the statistical margin of error in the sample","Vocabulary: the academic reading level of the text","Verifiable: whether the book is available in a physical university library"]'::jsonb, 'RAVEN assesses source reliability: Reputation, Ability to see, Vested interest (bias/stake in outcome), Expertise, and Neutrality.'),
  ('ap-topic-seminar-quest_q4', 'ap-topic-seminar-quest', 4, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'What is a "line of reasoning" in academic argumentation?', '["The logical sequence of connected claims, reasons, and evidence that leads cohesively from an opening premise to the ultimate conclusion","A list of bibliographic citations formatted in alphabetical order","A chronological timeline of historical dates mentioned in a text","The grammatical syntax connecting compound-complex sentences"]'::jsonb, 'A line of reasoning is the coherent connective tissue of an argument: each claim builds upon the previous, substantiated by evidence, guiding the reader logically toward the thesis conclusion.'),
  ('ap-topic-seminar-quest_q5', 'ap-topic-seminar-quest', 5, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'In AP Seminar, how does a "lens" differ from a "perspective"?', '["A lens is a broad category or discipline through which an issue is viewed (e.g., economic, ethical, environmental); a perspective is a specific viewpoint held by a person or group with particular values or stakes","Lenses apply only to quantitative data; perspectives apply only to qualitative interviews","A lens is always held by an individual; a perspective is an academic textbook","Lenses and perspectives are completely interchangeable terms with no distinction"]'::jsonb, 'A lens is an analytical filter or framework (economic, social, political, cultural, ethical). A perspective is a distinct position or stance within or across lenses (e.g., indigenous farmers vs multinational corporate executives).'),
  ('ap-topic-seminar-quest_q6', 'ap-topic-seminar-quest', 6, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'What makes a research question effective, viable, and researchable for an academic inquiry paper?', '["It is focused, open-ended (cannot be answered with a simple yes/no), debate-worthy, complex, and addressable with credible scholarly evidence","It has a simple, undisputed factual answer that can be answered in one sentence","It is so broad that it attempts to solve global poverty across all continents and centuries","It is based entirely on personal emotional preference without empirical grounding"]'::jsonb, 'A high-quality inquiry question avoids simplistic yes/no answers, is sufficiently narrow to explore deeply within word constraints, and invites nuanced investigation of multiple perspectives.'),
  ('ap-topic-seminar-quest_q7', 'ap-topic-seminar-quest', 7, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'In academic synthesis, what does it mean to place two authors "in conversation" with each other?', '["Comparing and contrasting their claims, evidence, and underlying assumptions to show where they agree, disagree, or qualify one another on a shared issue","Quoting two authors consecutively without any explanatory commentary","Fabricating an imaginary dialogue script between two historical figures","Proving that one author is 100% correct and the other author is a criminal"]'::jsonb, 'Placing sources in conversation moves beyond cataloging sources: it actively analyzes how their arguments intersect, illuminate nuances, or expose counterpoints on an issue.'),
  ('ap-topic-seminar-quest_q8', 'ap-topic-seminar-quest', 8, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'What is a "fallacy of relevance"?', '["An argument whose premises are logically irrelevant to the truth of the conclusion they are supposed to support (such as an ad hominem or red herring)","A mathematical miscalculation in a standard deviation formula","A citation from a source published more than five years ago","An argument that presents too many peer-reviewed sources"]'::jsonb, 'Fallacies of relevance (ad hominem, red herring, appeal to pity) introduce emotionally charged or unrelated information that distracts from the core issue without providing logical proof.'),
  ('ap-topic-seminar-quest_q9', 'ap-topic-seminar-quest', 9, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'When evaluating empirical evidence, what is the difference between evidence that is "sufficient" versus evidence that is "relevant"?', '["Relevant evidence directly pertains to the specific claim being made; sufficient evidence provides enough quantity and variety of data to convincingly prove the claim","Relevant evidence is quantitative; sufficient evidence is qualitative","Sufficient evidence means an author is peer-reviewed; relevant evidence means it was published online","There is no distinction; both terms mean the evidence is true"]'::jsonb, 'Relevance ensures the evidence connects logically to the claim. Sufficiency evaluates whether the amount and breadth of evidence is adequate to justify accepting the conclusion without hasty generalization.'),
  ('ap-topic-seminar-quest_q10', 'ap-topic-seminar-quest', 10, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'What constitutes an academic "qualification" of an argument?', '["Limiting the scope of a claim by acknowledging conditions, exceptions, or contexts in which the claim may not apply (e.g., using terms like \"under specific circumstances\" or \"often\")","The formal degrees held by the researcher (e.g., Ph.D.)","The number of pages in a research paper","A statement asserting that an argument is absolute and infallible under all conditions"]'::jsonb, 'Qualifying an argument prevents overgeneralization: recognizing boundary conditions, nuances, and exceptions makes an argument defensible and intellectually rigorous.'),
  ('ap-topic-seminar-quest_q11', 'ap-topic-seminar-quest', 11, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'Why is peer review considered the gold standard for scholarly academic literature?', '["Independent field experts critically evaluate the research methodology, data validity, and theoretical rigor before publication, filtering out flawed or fraudulent work","Peer review guarantees that a study will never be challenged or revised in the future","Peer review allows authors to publish their opinions without presenting empirical evidence","Peer review is completed automatically by computer grammar algorithms"]'::jsonb, 'Peer review provides rigorous quality control: independent scholarly experts anonymously examine research design, statistical analyses, and ethical standards before accepting manuscripts.'),
  ('ap-topic-seminar-quest_q12', 'ap-topic-seminar-quest', 12, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'What is confirmation bias, and how can a student researcher actively counteract it during academic inquiry?', '["The psychological tendency to favor information confirming existing beliefs; researchers counteract it by deliberately seeking out and evaluating credible disconfirming evidence and opposing perspectives","The requirement to confirm interview dates with subjects in advance","A statistical test confirming that correlation equals causation","A software error during digital library database searching"]'::jsonb, 'Confirmation bias leads researchers to select only evidence supporting their initial hunch. Good research methodology actively searches for disconfirming data and alternative hypotheses.'),
  ('ap-topic-seminar-quest_q13', 'ap-topic-seminar-quest', 13, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'In the Team Multimedia Presentation (TMP) component of AP Seminar, what makes a team''s collaborative solution compelling?', '["It synthesizes diverse individual member perspectives into a unified, feasible, and contextualized recommendation with addressed limitations and counterarguments","It simply repeats each student''s individual paper in four separate unrelated speeches","It avoids proposing any solution to keep the presentation strictly neutral","It exceeds the timed limit by twenty minutes"]'::jsonb, 'An effective TMP integrates distinct perspectives (e.g., economic, environmental, ethical) into a coherent, actionable solution, assessing real-world feasibility and trade-offs.'),
  ('ap-topic-seminar-quest_q14', 'ap-topic-seminar-quest', 14, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'What is an "unwarranted assumption" in an argument''s line of reasoning?', '["A foundational belief or premise taken for granted as true without supporting evidence, upon which the entire conclusion depends","A statistical calculation verified with a large random sample","A direct quotation from an encyclopedic source","A formal counterargument provided by an opponent"]'::jsonb, 'An unwarranted assumption is an unproven assertion taken for granted; if the underlying assumption is flawed, the entire line of reasoning collapses.'),
  ('ap-topic-seminar-quest_q15', 'ap-topic-seminar-quest', 15, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'How does an author''s "tone" reflect their attitude toward the subject matter and audience?', '["Through deliberate choices in diction, figurative imagery, syntax, and sentence structure (e.g., objective, urgent, cynical, reverent)","Through the physical volume of their voice when reading aloud","Through the choice of font style on the printed manuscript","Through the total number of footnotes included in the paper"]'::jsonb, 'Tone is the rhetorical expression of attitude conveyed via word choice (diction) and phrasing: a medical journal adopts an objective, analytical tone, whereas an editorial may be impassioned.'),
  ('ap-topic-seminar-quest_q16', 'ap-topic-seminar-quest', 16, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'What constitutes the logical fallacy of "straw man"?', '["Oversimplifying, exaggerating, or completely distorting an opponent''s argument to make it easy to attack and knock down","Presenting peer-reviewed medical statistics from a verified clinic","Attacking the opponent''s hometown instead of their ideas","Assuming that correlation automatically proves causal relationship"]'::jsonb, 'A straw man fallacy replaces a nuanced opposing argument with a caricature or distortion that is easily refuted, giving the false impression of defeating the original claim.'),
  ('ap-topic-seminar-quest_q17', 'ap-topic-seminar-quest', 17, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'When synthesizing evidence, what does it mean to identify a "gap" in existing research?', '["Discovering an unaddressed question, overlooked demographic, unexplored methodology, or contradictory finding in existing scholarly literature","Finding a torn page in a library book","Noticing a missing footnote in an online blog post","Identifying an author who did not attend college"]'::jsonb, 'A research gap represents an unexplored question or missing perspective within published scholarship, providing the scholarly justification for a new investigation.'),
  ('ap-topic-seminar-quest_q18', 'ap-topic-seminar-quest', 18, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'In academic research, why is "triangulation" valuable when collecting and analyzing evidence?', '["Using multiple independent data sources, methods, or researchers to cross-verify findings, increasing credibility and validity","Measuring geographic distances using three global satellites","Restricting sources exclusively to three peer-reviewed journals","Writing an argument in exactly three paragraphs"]'::jsonb, 'Methodological triangulation combines different data streams (e.g., surveys, interviews, observational data) to cross-validate findings, mitigating individual bias and bolstering robustness.'),
  ('ap-topic-seminar-quest_q19', 'ap-topic-seminar-quest', 19, false, 'A', 'QUEST Framework & Argumentation', 'medium', 'What is a "red herring" fallacy in argument?', '["Introducing an irrelevant topic or side issue to distract the audience and derail attention from the original argument","Proving that two events are correlated through statistical analysis","Citing a source from marine biology in an environmental paper","Refusing to speak during an oral presentation"]'::jsonb, 'A red herring intentionally diverts focus from the real debate by injecting a tangential, emotionally inflammatory, or unrelated subject.'),
  ('ap-topic-seminar-quest_q20', 'ap-topic-seminar-quest', 20, false, 'A', 'QUEST Framework & Argumentation', 'hard', 'How should a researcher handle anomalous data or counter-evidence that contradicts their initial thesis hypothesis?', '["Transparently report the contradictory data, analyze why it occurred, and explain how it qualifies or refines the proposed conclusion","Delete the anomalous data points to preserve a neat trendline","Falsify alternative survey entries to outweigh the contradictory data","Abandon the entire research project immediately"]'::jsonb, 'Scientific integrity demands reporting all empirical findings, including outliers and contradictions. Addressing anomalies demonstrates intellectual honesty and refines conclusions.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-research-methods_q1', 'ap-topic-research-methods', 1, false, 'B', 'Research', 'medium', 'A detailed description of the tools, procedures, and data collection techniques in a research paper is the:', '["Literature Review","Methodology","Discussion","Abstract"]'::jsonb, 'The Methodology section explains data collection and analytical methods.'),
  ('ap-topic-research-methods_q2', 'ap-topic-research-methods', 2, false, 'A', 'Methodology & Defense', 'medium', 'In academic research design, what is the primary purpose of obtaining Institutional Review Board (IRB) approval prior to data collection?', '["To review proposed human subjects research to ensure ethical compliance, informed consent, risk minimization, and confidentiality protections","To verify the grammar and citation style formatting of the research proposal","To secure federal patent rights on commercial inventions","To assign monetary grants to student researchers"]'::jsonb, 'The Institutional Review Board (IRB) protects human subjects from ethical violations (codified in the Belmont Report: respect for persons, beneficence, justice), reviewing consent and risk mitigation.'),
  ('ap-topic-research-methods_q3', 'ap-topic-research-methods', 3, false, 'A', 'Methodology & Defense', 'medium', 'What distinguishes a qualitative research methodology from a quantitative research methodology?', '["Qualitative research gathers non-numerical, descriptive data (interviews, focus groups, thematic analysis) to understand lived experiences; quantitative research gathers numerical data to test statistical relationships and generalize patterns","Qualitative research uses laboratory experiments; quantitative research uses only historical books","Quantitative research is always biased; qualitative research is mathematically infallible","Qualitative research cannot be published in peer-reviewed journals"]'::jsonb, 'Quantitative methods emphasize statistical measurement, hypotheses, and numerical variables. Qualitative methods explore subjective meaning, cultural context, and lived human experiences through thematic coding.'),
  ('ap-topic-research-methods_q4', 'ap-topic-research-methods', 4, false, 'A', 'Methodology & Defense', 'hard', 'What is the distinction between "internal validity" and "external validity" in an experimental research study?', '["Internal validity measures the extent to which the experimental manipulation (and not confounding variables) caused the observed outcome; external validity measures the generalizability of the findings to real-world populations and settings","Internal validity applies to surveys; external validity applies only to blood tests","External validity is determined by the size of the computer hard drive storing the data","Both terms mean that the p-value is less than 0.05"]'::jsonb, 'Internal validity asks: "Did the treatment truly cause the effect, with confounders controlled?" External validity asks: "Do these lab results generalize to broader populations outside this setting?"'),
  ('ap-topic-research-methods_q5', 'ap-topic-research-methods', 5, false, 'A', 'Methodology & Defense', 'medium', 'What is "informed consent" in human subjects research ethics?', '["Voluntary participation agreed to by subjects after being fully informed of the study''s purpose, procedures, potential risks, and their right to withdraw at any time without penalty","A legally binding contract preventing participants from ever discussing the study","An agreement by the researcher to pay every participant $\\$1,000$","Verbal permission granted by a school principal on behalf of adult teachers"]'::jsonb, 'Informed consent guarantees autonomy: participants must understand study expectations, potential discomforts, confidentiality safeguards, and that participation is entirely voluntary.'),
  ('ap-topic-research-methods_q6', 'ap-topic-research-methods', 6, false, 'A', 'Methodology & Defense', 'hard', 'What is a "mixed-methods" research design and what primary advantage does it provide?', '["Integrating both quantitative and qualitative methods to gain a comprehensive understanding by combining statistical breadth with contextual depth","Using both Google and Yahoo search engines simultaneously","Interviewing both children and adults in the same room","Publishing in two different languages"]'::jsonb, 'Mixed-methods research (e.g., convergent parallel design) leverages the strengths of both paradigms: quantitative surveys provide generalizable statistical trends, while qualitative interviews explain the mechanisms.'),
  ('ap-topic-research-methods_q7', 'ap-topic-research-methods', 7, false, 'A', 'Methodology & Defense', 'medium', 'What is a "confounding variable" (lurking variable) in research design?', '["An unmeasured extraneous factor that correlates with both the independent and dependent variables, potentially creating a spurious apparent relationship","The variable deliberately manipulated by the experimenter","The outcome measured on the dependent axis","A software bug in statistical analysis scripts"]'::jsonb, 'A confounder intertwines with the independent variable, distorting causal inference (e.g., ice cream sales and drowning rates both correlate with hot weather).'),
  ('ap-topic-research-methods_q8', 'ap-topic-research-methods', 8, false, 'A', 'Methodology & Defense', 'hard', 'In qualitative data analysis, what is "thematic coding"?', '["A systematic process of reviewing qualitative transcripts, identifying recurring patterns and concepts, and grouping them into organized analytic themes","Converting text into binary code for encryption","Counting words using an automated spellchecker","Ranking interviewees by their age and income"]'::jsonb, 'Thematic analysis (Braun & Clarke) systematically reads qualitative data to generate open codes, refine categories, and articulate overarching themes that address the research question.'),
  ('ap-topic-research-methods_q9', 'ap-topic-research-methods', 9, false, 'A', 'Methodology & Defense', 'medium', 'What is a "convenience sample" and what is its primary methodological limitation?', '["Sampling individuals who are easiest to reach (e.g., surveying one''s own classmates); it introduces severe selection bias and cannot be generalized to broader populations","A computerized simple random sample of an entire national census","A stratified sample of medical patients across fifty hospitals","A sampling technique that eliminates all sampling error"]'::jsonb, 'Convenience sampling lacks random selection. Because participants are chosen based on accessibility rather than representative sampling, external validity is severely compromised.'),
  ('ap-topic-research-methods_q10', 'ap-topic-research-methods', 10, false, 'A', 'Methodology & Defense', 'hard', 'What does "operationalizing" a variable mean in research methodology?', '["Defining an abstract theoretical concept (such as \"stress\" or \"academic engagement\") in terms of specific, measurable, and quantifiable empirical procedures","Hiring an operations manager for the laboratory","Writing an operating system for data storage","Translating a survey into three foreign languages"]'::jsonb, 'Operationalization bridges abstract constructs to empirical reality: specifying exact measurable indicators (e.g., measuring "anxiety" via salivary cortisol levels or a validated 10-item Likert scale).'),
  ('ap-topic-research-methods_q11', 'ap-topic-research-methods', 11, false, 'A', 'Methodology & Defense', 'medium', 'What is the purpose of a "literature review" chapter in an academic thesis or AP Research paper?', '["To contextualize the study within existing scholarly conversation, synthesize foundational theories, demonstrate knowledge of the field, and justify the research gap","To summarize random popular news articles about the topic","To present the raw, unanalyzed data collected from surveys","To provide personal autobiographical reflections on why the author loves the topic"]'::jsonb, 'A literature review surveys academic conversations, establishes theoretical frameworks, benchmarks past findings, and demonstrates why the author''s specific research gap warrants investigation.'),
  ('ap-topic-research-methods_q12', 'ap-topic-research-methods', 12, false, 'A', 'Methodology & Defense', 'hard', 'What is "inter-rater reliability" in empirical research?', '["The degree of agreement or consistency between two or more independent observers or coders scoring the same categorical data","The speed at which participants complete an online questionnaire","The correlation between test scores on two different days","The percentage of invited participants who agree to be interviewed"]'::jsonb, 'Inter-rater reliability (often measured via Cohen''s kappa) quantifies the consistency with which different judges assign codes or ratings, ensuring scoring is objective rather than idiosyncratic.'),
  ('ap-topic-research-methods_q13', 'ap-topic-research-methods', 13, false, 'A', 'Methodology & Defense', 'medium', 'What is a "Likert scale" commonly used in survey research instruments?', '["A psychometric rating scale that measures participants'' degree of agreement or disagreement with a statement along an ordered continuum (e.g., 1 = Strongly Disagree to 5 = Strongly Agree)","A physical weight scale used in laboratory experiments","A timer that records reaction speeds in milliseconds","A method for measuring geographic elevation above sea level"]'::jsonb, 'A Likert scale quantifies attitudes, perceptions, and beliefs through symmetric ordered response categories (e.g., Strongly Disagree, Disagree, Neutral, Agree, Strongly Agree).'),
  ('ap-topic-research-methods_q14', 'ap-topic-research-methods', 14, false, 'A', 'Methodology & Defense', 'hard', 'What constitutes the "Hawthorne Effect" in observational behavioral studies?', '["Participants altering or improving their natural behavior simply because they know they are being actively observed by a researcher","Participants dropping out of a study due to boredom","Researchers falsifying data to match their hypotheses","The tendency of interviewers to ask leading questions"]'::jsonb, 'Discovered in industrial studies at Western Electric''s Hawthorne Works, the Hawthorne Effect shows that human subjects modify their behavior when they are conscious of being scrutinized.'),
  ('ap-topic-research-methods_q15', 'ap-topic-research-methods', 15, false, 'A', 'Methodology & Defense', 'medium', 'In an academic oral defense, how should a student respond when asked a question about a methodological limitation they did not foresee?', '["Acknowledge the insight graciously, explain how that factor might influence the interpretation of the results, and suggest how future studies could address it","Argue aggressively that the question is completely irrelevant to the project","Claim that the limitation was secretly anticipated but omitted due to page counts","Remain silent until the panel moves to the next question"]'::jsonb, 'Scholarly maturity in an oral defense values intellectual honesty: acknowledging unconsidered variables, discussing their potential confounding effects, and proposing future refinements.'),
  ('ap-topic-research-methods_q16', 'ap-topic-research-methods', 16, false, 'A', 'Methodology & Defense', 'hard', 'What is a "double-blind" experimental procedure, and what does it prevent?', '["Neither the participants nor the experimenters interacting with them know who belongs to the control group or experimental group, preventing both participant placebo effects and experimenter expectancy bias","The experiment is conducted in a room with zero natural sunlight","Participants are required to complete the study with their eyes covered","Two different researchers analyze the data without speaking to each other"]'::jsonb, 'Double-blind trials eliminate confirmation bias and subtle behavioral cues from experimenters while preventing participant placebo responses, providing gold-standard clinical rigor.'),
  ('ap-topic-research-methods_q17', 'ap-topic-research-methods', 17, false, 'A', 'Methodology & Defense', 'medium', 'What is the primary difference between a cross-sectional study and a longitudinal study?', '["A cross-sectional study observes different individuals of varied ages at a single point in time; a longitudinal study tracks the same cohort of individuals repeatedly over an extended period of time","Cross-sectional studies are quantitative; longitudinal studies are always qualitative","Longitudinal studies must be completed within 24 hours","Cross-sectional studies require surgical interventions"]'::jsonb, 'Cross-sectional designs take a rapid snapshot of multiple age groups simultaneously (vulnerable to cohort effects). Longitudinal designs follow the same participants over years to measure development directly.'),
  ('ap-topic-research-methods_q18', 'ap-topic-research-methods', 18, false, 'A', 'Methodology & Defense', 'hard', 'What is "selection bias" in empirical sampling?', '["A systematic error where the sample selected is not representative of the target population due to non-random participant recruitment procedures","Selecting the wrong software package to run regressions","Choosing an uninteresting research question","Random assignment of participants into equal experimental groups"]'::jsonb, 'Selection bias occurs when the sampling frame systematically favors certain traits over others (e.g., voluntary response bias, non-response bias), undermining generalizability.'),
  ('ap-topic-research-methods_q19', 'ap-topic-research-methods', 19, false, 'A', 'Methodology & Defense', 'medium', 'What is the role of "debriefing" in psychological and social science research involving deception?', '["Explaining the true hypothesis and purpose of the study to participants immediately following their participation, dispelling misconceptions and addressing any distress","Reporting participant names to law enforcement authorities","Publishing participant phone numbers in an academic appendix","Deleting all recorded interview audio files immediately"]'::jsonb, 'If IRB-approved deception is employed, researchers are ethically mandated to debrief participants immediately afterward, revealing the true aims and providing psychological support if needed.'),
  ('ap-topic-research-methods_q20', 'ap-topic-research-methods', 20, false, 'A', 'Methodology & Defense', 'hard', 'What does a $p$-value ($p < 0.05$) indicate in inferential statistical hypothesis testing?', '["The probability of obtaining sample results as extreme as, or more extreme than, the observed data, assuming the null hypothesis ($H_0$) is strictly true","The probability that the alternative hypothesis is false","The probability that the researcher made a calculation error","The exact percentage of the population that supports the policy"]'::jsonb, 'A $p$-value quantifies compatibility with $H_0$: the likelihood of seeing the observed effect (or greater) purely by random sampling variability if there were truly no effect in the population.'),
  ('ap-mock-full-1_q1', 'ap-mock-full-1', 1, false, 'B', 'Limits', 'medium', 'Evaluate $\lim_{x \to 0} \frac{1 - \cos x}{x^2}$.', '["0","0.5","1","Undefined"]'::jsonb, 'L''Hôpital gives $\frac{\sin x}{2x} \to 1/2 = 0.5$.'),
  ('ap-mock-full-1_q2', 'ap-mock-full-1', 2, false, 'A', 'Derivatives', 'medium', 'If $f(x) = \arctan(3x)$, find $f''(x)$.', '["$\\frac{3}{1+9x^2}$","$\\frac{1}{1+9x^2}$","$\\frac{3}{1+3x^2}$","$\\frac{1}{\\sqrt{1-9x^2}}$"]'::jsonb, '$\frac{3}{1+(3x)^2} = \frac{3}{1+9x^2}$.'),
  ('ap-mock-full-1_q3', 'ap-mock-full-1', 3, true, 'FRQ_MANUAL_EVALUATION', 'Particle Motion', 'hard', 'A particle moves along x-axis with v(t) = 3t^2 - 12t + 9. Find total distance from t = 0 to t = 4.', '["Submit text solution below"]'::jsonb, 'Velocity v(t) = 3t^2 - 12t + 9 = 3(t - 1)(t - 3). The particle changes direction at t = 1 and t = 3. Total distance is \int_{0}^{1} v(t)dt - \int_{1}^{3} v(t)dt + \int_{3}^{4} v(t)dt. [t^3 - 6t^2 + 9t]_{0}^{1} = 4; -[t^3 - 6t^2 + 9t]_{1}^{3} = 4; [t^3 - 6t^2 + 9t]_{3}^{4} = 4. Total distance = 4 + 4 + 4 = 12.'),
  ('ap-mock-full-1_q4', 'ap-mock-full-1', 4, false, 'C', 'Limits', 'easy', 'Evaluate $\lim_{x \to 3} \frac{x^2 - 9}{x - 3}$.', '["0","3","6","Undefined"]'::jsonb, 'Factor numerator: $x^2 - 9 = (x - 3)(x + 3)$. Cancel $(x - 3)$ to get $\lim_{x \to 3} (x + 3) = 6$.'),
  ('ap-mock-full-1_q5', 'ap-mock-full-1', 5, false, 'C', 'Limits', 'easy', 'What is $\lim_{x \to 0} \frac{\sin(4x)}{x}$?', '["0","1","4","Does not exist"]'::jsonb, 'Using $\lim_{u \to 0} \frac{\sin(k u)}{u} = k$, we get 4.'),
  ('ap-mock-full-1_q6', 'ap-mock-full-1', 6, false, 'B', 'Limits', 'medium', 'Find $\lim_{x \to \infty} \frac{5x^3 - 2x + 1}{2x^3 + 7x^2}$.', '["0","2.5","5","$\\infty$"]'::jsonb, 'Leading coefficients ratio: 5/2 = 2.5.'),
  ('ap-mock-full-1_q7', 'ap-mock-full-1', 7, false, 'A', 'Derivatives', 'easy', 'If $f(x) = 4x^3 - 5x^2 + 7x - 2$, what is $f''(x)$?', '["$12x^2 - 10x + 7$","$12x^2 - 5x + 7$","$4x^2 -10x$","$12x^3 - 10x^2$"]'::jsonb, 'Apply power rule term by term: $12x^2 - 10x + 7$.'),
  ('ap-mock-full-1_q8', 'ap-mock-full-1', 8, false, 'A', 'Derivatives', 'medium', 'Find the slope of the tangent line to $x^2 + y^2 = 25$ at $(3, 4)$.', '["$\\frac{-3}{4}$","$\\frac{3}{4}$","$\\frac{-4}{3}$","$\\frac{4}{3}$"]'::jsonb, '$2x + 2y y'' = 0 \implies y'' = $-x$/y = -3/4$.'),
  ('ap-mock-full-1_q9', 'ap-mock-full-1', 9, false, 'A', 'Integrals', 'easy', 'Evaluate $\int (3x^2 - 4x + 5) dx$.', '["$x^3 - 2x^2 + 5x + C$","$6x - 4 + C$","$x^3 - 4x^2 + 5x + C$","$3x^3 - 2x^2 + C$"]'::jsonb, 'Power rule for integration gives $x^3 - 2x^2 + 5x + C$.'),
  ('ap-mock-full-1_q10', 'ap-mock-full-1', 10, false, 'B', 'Integrals', 'medium', 'Find $\int_{0}^{\pi/2} \sin(x) \cos(x)\,dx$.', '["0","0.5","1","2"]'::jsonb, 'Substitution $u = \sin(x)$ gives $[u^2/2]_0^1 = 0.5$.'),
  ('ap-mock-full-1_q11', 'ap-mock-full-1', 11, false, 'A', 'Applications', 'medium', 'Find the average value of $f(x) = x^2$ on $[0, 3]$.', '["3","4.5","9","27"]'::jsonb, '$\frac{1}{3}$\int_{0}^{3} x^2 dx = $frac{1}{3} [x^3/3]_0^3 = 3$.'),
  ('ap-mock-full-1_q12', 'ap-mock-full-1', 12, false, 'B', 'Derivatives', 'medium', 'Find $\frac{d}{dx}[\sin(x^2)]$.', '["$\\cos(x^2)$","$2x\\cos(x^2)$","$-\\sin(x^2)$","\\$2\\cos(x^2)$"]'::jsonb, 'Chain rule: $\cos(x^2) \cdot 2x = 2x\cos(x^2)$.'),
  ('ap-mock-full-1_q13', 'ap-mock-full-1', 13, false, 'B', 'Derivatives', 'medium', 'Use the product rule to differentiate $f(x) = x^2 e^x$.', '["$2xe^x$","$x^2 e^x + 2xe^x$","$2xe^x - x^2 e^x$","$x^2 e^x$"]'::jsonb, '$f''(x) = x^2 e^x + 2x e^x$ by product rule.'),
  ('ap-mock-full-1_q14', 'ap-mock-full-1', 14, false, 'B', 'Derivatives', 'easy', 'What is the derivative of $\ln(x)$?', '["$x$","\\$1/x$","$e^x$","$\\ln(x)/x$"]'::jsonb, '$\frac{d}{dx}[\ln x] = \frac{1}{x}$.'),
  ('ap-mock-full-1_q15', 'ap-mock-full-1', 15, false, 'C', 'Integrals', 'medium', 'Evaluate $\int e^{3x} dx$.', '["$e^{3x} + C$","$3e^{3x} + C$","$\\frac{1}{3}e^{3x} + C$","$\\frac{e^{3x}}{x} + C$"]'::jsonb, '$\int e^{3x} dx = \frac{1}{3}e^{3x}  + C$.'),
  ('ap-mock-full-1_q16', 'ap-mock-full-1', 16, false, 'B', 'Applications', 'medium', 'If $f''(x) > 0$ on $(a, b)$, then $f$ is:', '["Decreasing on $(a,b)$","Increasing on $(a,b)$","Concave up","Has a local max"]'::jsonb, 'Positive first derivative means the function is increasing on that interval.'),
  ('ap-mock-full-1_q17', 'ap-mock-full-1', 17, false, 'B', 'Applications', 'medium', 'Find the critical points of $f(x) = x^3 -3x$.', '["$x = 0$","$x = \\pm 1$","$x = \\pm 3$","$x = 1$ only"]'::jsonb, '$f''(x) = 3x^2 - 3 = 0 \implies x = \pm 1$.'),
  ('ap-mock-full-1_q18', 'ap-mock-full-1', 18, false, 'B', 'Integrals', 'hard', 'Evaluate $\int_1^e \frac{\ln(x)}{x}\,dx$.', '["0","$\\frac{1}{2}$","1","e"]'::jsonb, 'Let $u = \ln x$, $du = dx/x$. Integral becomes  \int_{0}^{1} u$\, du = 1/2$.'),
  ('ap-mock-full-1_q19', 'ap-mock-full-1', 19, false, 'A', 'Derivatives', 'hard', 'Find $\frac{d}{dx}[\tan^{-1}(x)]$.', '["$\\frac{1}{1+x^2}$","$\\frac{1}{\\sqrt{1-x^2}}$","$-\\frac{1}{1+x^2}$","$\\sec^2(x)$"]'::jsonb, 'Standard derivative: $\frac{d}{dx}[\arctan x] = \frac{1}{1+x^2}$.'),
  ('ap-mock-full-1_q20', 'ap-mock-full-1', 20, false, 'A', 'Applications', 'medium', 'The second derivative test: if $f''(c)=0$ and $f''''(c) > 0$, then $f$ has a:', '["Local minimum at $x=c$","Local maximum at $x=c$","Inflection point","No conclusion"]'::jsonb, 'Positive second derivative at a critical point indicates a local minimum.'),
  ('ap-mock-full-1_q21', 'ap-mock-full-1', 21, false, 'A', 'Integrals', 'medium', 'Use substitution: $\int 2x(x^2+1)^4 dx$.', '["$\\frac{(x^2+1)^5}{5}  + C$","$\\frac{(x^2+1)^5}{10}  + C$","$8x(x^2+1)^3 + C$","$(x^2+1)^5  + C$"]'::jsonb, 'Let $u = x^2+\$1$, $du = 2x\\,$dx$. Integral = $u^5/5 + C$.'),
  ('ap-mock-full-1_q22', 'ap-mock-full-1', 22, false, 'B', 'Limits', 'hard', 'Apply L''Hopital''s Rule: $\lim_{x \to 0} \frac{e^x - 1}{x}$.', '["0","1","e","Does not exist"]'::jsonb, 'Both numerator and denominator are 0/0. Differentiate: $e^x/1 = 1$ at $x=0$.'),
  ('ap-mock-full-1_q23', 'ap-mock-full-1', 23, false, 'A', 'Applications', 'medium', 'The area between $y = x^2$ and $y = x$ from $x=0$ to $x=1$ is:', '["$\\frac{1}{6}$","$\\frac{1}{3}$","$\\frac{1}{2}$","1"]'::jsonb, '$\int_0^1 (x - x^2) dx = 1/2 - 1/3 = 1/6$.'),
  ('ap-mock-full-1_q24', 'ap-mock-full-1', 24, false, 'B', 'Derivatives', 'medium', 'What is $\frac{d}{dx}[x^x]$?', '["$x \\cdot x^{x-1}$","$x^x(1 + \\ln x)$","$x^x \\ln x$","$x^{x-1}$"]'::jsonb, 'Take $\ln y = x \ln x$. Then $y''/y = \ln x + 1$, so $y'' = x^x(1+\ln x)$.'),
  ('ap-mock-full-1_q25', 'ap-mock-full-1', 25, false, 'B', 'Integrals', 'medium', 'Evaluate $\int \cos^2(x) dx$.', '["$\\frac{\\sin(2x)}{4}  + C$","$\\frac{x}{2} + \\frac{\\sin(2x)}{4}  + C$","$-\\sin^2(x)  + C$","$\\cos(x)\\sin(x)  + C$"]'::jsonb, 'Use $\cos^2 x = (1+\cos 2x)/2$: integral = $x/2 + \sin(2x)/4 + C$.'),
  ('ap-mock-full-1_q26', 'ap-mock-full-1', 26, false, 'B', 'Applications', 'hard', 'Volume from rotating $y=\sqrt{x}$ around x-axis, $x=0$ to $x=4$:', '["\\$4\\pi$","\\$8\\pi$","\\$16\\pi$","\\$32\\pi$"]'::jsonb, '$V = \pi$\int_{0}^{4} x$\,dx = \pi[x^2/2]_0^4 = 8\pi$.'),
  ('ap-mock-full-1_q27', 'ap-mock-full-1', 27, false, 'B', 'Derivatives', 'easy', 'Find $\frac{d}{dx}[\cos(3x)]$.', '["$-\\sin(3x)$","$-3\\sin(3x)$","\\$3\\cos(3x)$","$\\sin(3x)$"]'::jsonb, 'Chain rule: $-\sin(3x) \cdot 3 = -3\sin(3x)$.'),
  ('ap-mock-full-1_q28', 'ap-mock-full-1', 28, false, 'C', 'Limits', 'easy', '$\lim_{x \to 2} (3x^2 - 4) = $?', '["2","4","8","12"]'::jsonb, 'Direct substitution: \$3(4) - 4 = 8$.'),
  ('ap-mock-full-1_q29', 'ap-mock-full-1', 29, false, 'B', 'Integrals', 'easy', 'Evaluate $\int_{0}^{2} 3\,dx$.', '["3","6","9","0"]'::jsonb, '$$\int_{0}^{2} 3$\,dx = 3x\\Big|_0^2 = 6$.'),
  ('ap-mock-full-1_q30', 'ap-mock-full-1', 30, false, 'C', 'Applications', 'hard', 'A particle moves with velocity $v(t) = t^2 - 4$. Total distance on $[0,3]$ is:', '["3","$\\frac{11}{3}$","$\\frac{17}{3}$","9"]'::jsonb, '$v=0$ at $t=2$. Distance =  \int_{0^2(4-t}^{2)dt} $+\int_2^3(t^2-4)dt = 16/3 + 1/3 = 17/3$.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-full-1_q31', 'ap-mock-full-1', 31, false, 'A', 'Derivatives', 'medium', 'Using quotient rule, $\frac{d}{dx}\left[\frac{x^2}{\cos x}\right]$ =', '["$\\frac{2x\\cos x + x^2\\sin x}{\\cos^2 x}$","$\\frac{2x}{-\\sin x}$","$2x\\cos x$","$\\frac{2x\\cos x - x^2\\sin x}{\\cos^2 x}$"]'::jsonb, 'Quotient rule: numerator = $2x\cos x - x^2(-\sin x) = 2x\cos x + x^2\sin x$.'),
  ('ap-mock-full-1_q32', 'ap-mock-full-1', 32, false, 'B', 'Applications', 'hard', 'Linearization of $f(x)=\sqrt{x}$ at $x=9$ approximates $\sqrt{9.1}$ as:', '["3.0150","3.0167","3.0200","3.0100"]'::jsonb, '$L(x) = 3 + \frac{1}{6}(x-9)$. $L(9.1) = 3 + 0.1/6 \approx 3.0167$.'),
  ('ap-mock-full-1_q33', 'ap-mock-full-1', 33, false, 'C', 'Limits', 'easy', 'Evaluate: $\lim_{x \to 2} \frac{x^2 - 4}{x - 2}$', '["0","2","4","Does not exist"]'::jsonb, 'Factor $x^2 - 4 = (x - 2)(x + 2)$. The expression simplifies to $x + 2$, so as $x \to 2$, the limit is \$2 + 2 = 4$.'),
  ('ap-mock-full-1_q34', 'ap-mock-full-1', 34, false, 'B', 'Continuity', 'medium', 'For which value of $k$ is $f(x)$ continuous at $x = 3$? <br>$f(x) = \begin{cases} x^2 + k, & x < 3 \\ 12, & x \ge 3 \end{cases}$', '["2","3","4","6"]'::jsonb, 'For continuity at $x = 3$, $\lim_{x \to 3^-} f(x) = f(3)$. Thus, \$3^2 + k = 12 \implies 9 + k = 12 \implies k = 3$.'),
  ('ap-mock-full-1_q35', 'ap-mock-full-1', 35, false, 'B', 'Derivatives', 'easy', 'If $f(x) = x^2$, then $f''(3)$ is:', '["3","6","9","12"]'::jsonb, '$f''(x) = 2x$, so $f''(3) = 2(3) = 6$.'),
  ('ap-mock-full-1_q36', 'ap-mock-full-1', 36, false, 'A', 'Power Rule', 'easy', 'If $f(x) = 5x^4 - 3x^2 + 7$, then $f''(x)$ is:', '["$20x^3 -6x$","$20x^4 -6x$","$5x^3 -3x$","$20x^3 -3x$"]'::jsonb, 'Apply the power rule term-by-term: $\frac{d}{dx}(5x^4) - \frac{d}{dx}(3x^2) + \frac{d}{dx}(7) = 20x^3 $-6x$.'),
  ('ap-mock-full-1_q37', 'ap-mock-full-1', 37, false, 'C', 'Product Rule', 'medium', 'Find the derivative of $f(x) = x^2 e^x$:', '["$2x e^x$","$x^2 e^x$","$e^x (x^2 + 2x)$","$2x + e^x$"]'::jsonb, 'Using the product rule: $f''(x) = (2x)e^x + x^2 e^x = e^x(x^2 + 2x)$.'),
  ('ap-mock-full-1_q38', 'ap-mock-full-1', 38, false, 'B', 'Chain Rule', 'medium', 'Find $\frac{d}{dx} \sin(3x^2)$:', '["$\\cos(3x^2)$","$6x \\cos(3x^2)$","$3x \\cos(3x^2)$","$6x \\sin(3x^2)$"]'::jsonb, 'Outer derivative is $\cos(3x^2)$ and inner derivative is $6x$, so $f''(x) = 6x \cos(3x^2)$.'),
  ('ap-mock-full-1_q39', 'ap-mock-full-1', 39, false, 'D', 'Implicit Differentiation', 'medium', 'Given $x^2 + y^2 = 25$, what is $\frac{dy}{dx}$?', '["$\\frac{y}{x}$","$-\\frac{y}{x}$","$\\frac{x}{y}$","$-\\frac{x}{y}$"]'::jsonb, 'Differentiating implicitly: $2x + 2y \frac{dy}{dx} = 0 \implies 2y \frac{dy}{dx} = $-2x$ \implies \frac{dy}{dx} = -\frac{x}{y}$.'),
  ('ap-mock-full-1_q40', 'ap-mock-full-1', 40, false, 'A', 'Tangent Line', 'medium', 'For $f(x) = x^2 + 1$, find the equation of the tangent line at $x = 2$.', '["$y = 4x - 3$","$y = 4x + 3$","$y = 2x + 1$","$y = 4x - 1$"]'::jsonb, '$f(2) = 5$, slope $m = f''(2) = 2(2) = 4$. Tangent equation: $y - 5 = 4(x - 2) \implies y = 4x - 3$.'),
  ('ap-mock-full-1_q41', 'ap-mock-full-1', 41, false, 'C', 'Related Rates', 'hard', 'The radius of a circle increases at \$2 \text{ cm/s}$. How fast is its area increasing when $r = 3$?', '["\\$6\\pi$","\\$9\\pi$","\\$12\\pi$","\\$18\\pi$"]'::jsonb, '$A = \pi r^2 \implies \frac{dA}{dt} = 2\pi r \frac{dr}{dt} = 2\pi(3)(2) = 12\pi$.'),
  ('ap-mock-full-1_q42', 'ap-mock-full-1', 42, false, 'A', 'Critical Points', 'medium', 'For $f(x) = x^3 - 3x^2$, the critical numbers are:', '["0, 2","1, 2","0, 3","2, 3"]'::jsonb, '$f''(x) = 3x^2 - 6x = 3x(x - 2) = 0 \implies x = 0, 2$.'),
  ('ap-mock-full-1_q43', 'ap-mock-full-1', 43, false, 'B', 'Increasing Function', 'medium', 'For $f(x) = x^3 -3x$, on which interval(s) is $f$ increasing?', '["$(-1, 1)$","$(-\\infty, -1) \\cup (1, \\infty)$","$(-\\infty, 1)$","$(1, \\infty)$"]'::jsonb, '$f''(x) = 3x^2 - 3 = 3(x - 1)(x + 1)$. The derivative is positive when $x < -1$ or $x > 1$.'),
  ('ap-mock-full-1_q44', 'ap-mock-full-1', 44, false, 'A', 'Local Maximum', 'medium', 'For $f(x) = x^3 -3x$, where does the local maximum occur?', '["$x = -1$","$x = 0$","$x = 1$","$x = 3$"]'::jsonb, '$f''(x) = 3(x+1)(x-1)$ changes sign from positive to negative at $x = -1$, giving a local maximum.'),
  ('ap-mock-full-1_q45', 'ap-mock-full-1', 45, false, 'A', 'Concavity', 'easy', 'For $f(x) = x^3$, where is the function concave down?', '["$x < 0$","$x > 0$","All real $x$","Nowhere"]'::jsonb, '$f''''(x) = 6x$. Concave down means $f''''(x) < 0$, which holds for $x < 0$.')
